"use client";

import React, { useState, useRef, useEffect, useMemo } from "react";
import { ChevronLeft, ChevronRight, ChevronDown, TrendingUp, BarChart3, Calendar as CalendarIcon } from "lucide-react";
import { cn } from "@/lib/utils";

import { useModeFilteredAccounts } from "@/hooks/useModeFilteredAccounts";
import calendarPopUp from "@/store/calendarPopUp";
import datesforcal from "@/store/datesforcal";
import useCurrencyStore, { formatCompactCurrency } from "@/store/currencyStore";

interface Trade {
  date: string;
  Profit: number;
  [key: string]: unknown;
}

interface Account {
  tradeData?: Trade[];
  [key: string]: unknown;
}

interface GroupedTrade {
  date: string;
  trades: Trade[];
  profit: number;
  tradeLength: number;
}

const Calendar = () => {
  const { setShowTr, setDataDate } = calendarPopUp();
  const { setcalMonth, setcalYear } = datesforcal();
  const { selectedAccounts } = useModeFilteredAccounts();
  const { currency, exchangeRate } = useCurrencyStore();

  const accountBalance = useMemo(() => {
    return (selectedAccounts as Account[]).reduce((sum, acc) => {
      const balance = Number((acc as any).accountBalance) || 0;
      return sum + balance;
    }, 0);
  }, [selectedAccounts]);

  const groupedTrades = (selectedAccounts as Account[]).flatMap((acc) => acc.tradeData || [])
    .reduce((acc: Record<string, GroupedTrade>, trade: Trade) => {
      if (!acc[trade.date]) {
        acc[trade.date] = { date: trade.date, trades: [], profit: 0, tradeLength: 0 };
      }
      acc[trade.date].trades.push(trade);
      acc[trade.date].profit += trade.Profit;
      acc[trade.date].tradeLength += 1;
      return acc;
    }, {});

  const calendarData = Object.values(groupedTrades) as GroupedTrade[];

  const [selectedYear, setSelectedYear] = useState(new Date().getFullYear());
  const [selectedMonth, setSelectedMonth] = useState(new Date().getMonth());
  const [showYearView, setShowYearView] = useState(false);
  const [isDropdownVisible, setIsDropdownVisible] = useState(false);
  const yearContainerRef = useRef<HTMLDivElement>(null);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (isDropdownVisible && showYearView && yearContainerRef.current) {
      const activeYearElement = yearContainerRef.current.querySelector(".year-active");
      if (activeYearElement) {
        yearContainerRef.current.scrollTop =
          (activeYearElement as HTMLElement).offsetTop - yearContainerRef.current.offsetTop - 40;
      }
    }
  }, [isDropdownVisible, showYearView]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownVisible(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const formatCurrencyDisplay = (num: number) => {
    return formatCompactCurrency(Math.abs(num), currency, exchangeRate, accountBalance);
  };

  const daysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();

  const calculateWeeklyProfits = (year: number, month: number) => {
    const days = daysInMonth(year, month);
    const weeks: number[] = [];
    let weekProfit = 0;

    for (let day = 1; day <= days; day++) {
      const dateStr = `${year}-${(month + 1).toString().padStart(2, "0")}-${day.toString().padStart(2, "0")}`;
      const dayData = calendarData.find((d) => d.date === dateStr);

      if (dayData) {
        weekProfit += dayData.profit;
      }

      if (new Date(year, month, day).getDay() === 6 || day === days) {
        weeks.push(weekProfit);
        weekProfit = 0;
      }
    }
    return weeks;
  };

  const monthlyStats = useMemo(() => {
    const monthStart = `${selectedYear}-${(selectedMonth + 1).toString().padStart(2, "0")}-01`;
    const monthEnd = `${selectedYear}-${(selectedMonth + 1).toString().padStart(2, "0")}-${daysInMonth(selectedYear, selectedMonth).toString().padStart(2, "0")}`;

    let totalPnL = 0;
    let totalTrades = 0;
    let tradingDays = 0;
    let winningDays = 0;

    calendarData.forEach((day) => {
      if (day.date >= monthStart && day.date <= monthEnd) {
        totalPnL += day.profit;
        totalTrades += day.tradeLength;
        tradingDays += 1;
        if (day.profit > 0) winningDays += 1;
      }
    });

    const winRate = tradingDays > 0 ? Math.round((winningDays / tradingDays) * 100) : 0;

    return { totalPnL, totalTrades, tradingDays, winRate };
  }, [calendarData, selectedYear, selectedMonth]);

  const renderCalendar = () => {
    const days = daysInMonth(selectedYear, selectedMonth);
    const firstDayIndex = new Date(selectedYear, selectedMonth, 1).getDay();
    const cells = [];

    for (let i = 0; i < firstDayIndex; i++) {
      cells.push(
        <div key={`empty-${i}`} className="aspect-square sm:h-[80px] sm:aspect-auto rounded-xl bg-muted/20" />
      );
    }

    for (let day = 1; day <= days; day++) {
      const dateStr = `${selectedYear}-${(selectedMonth + 1).toString().padStart(2, "0")}-${day.toString().padStart(2, "0")}`;
      const dayData = calendarData.find((d) => d.date === dateStr);

      const hasTrades = dayData && dayData.tradeLength > 0;
      const isProfit = dayData && dayData.profit > 0;
      const isLoss = dayData && dayData.profit < 0;

      const getProfitBgClass = () => {
        if (!hasTrades) return "bg-muted/20 hover:bg-muted/40";
        if (isProfit) return "bg-profit/10 border border-profit/20 hover:border-profit/40 hover:bg-profit/15";
        if (isLoss) return "bg-loss/10 border border-loss/20 hover:border-loss/40 hover:bg-loss/15";
        return "bg-card/80 border border-border/50 hover:border-border hover:bg-card";
      };

      cells.push(
        <div
          key={day}
          className={cn(
            "aspect-square sm:h-[80px] sm:aspect-auto rounded-xl flex flex-col justify-center items-center cursor-pointer transition-all duration-200 relative",
            getProfitBgClass()
          )}
          onClick={() => {
            setShowTr();
            document.body.classList.add("no-scroll");
            setDataDate(selectedYear, selectedMonth, day);
          }}
        >
          <span className={cn(
            "text-[10px] sm:text-xs font-medium",
            hasTrades ? "text-foreground/70" : "text-muted-foreground/60"
          )}>
            {day}
          </span>
          {hasTrades && (
            <>
              <span className={cn(
                "text-[10px] sm:text-sm font-bold mt-0.5",
                isProfit ? "text-profit" : isLoss ? "text-loss" : "text-muted-foreground"
              )}>
                {formatCurrencyDisplay(dayData.profit)}
              </span>
              <span className="text-[8px] sm:text-[9px] text-muted-foreground/70 hidden sm:block">
                {dayData.tradeLength} {dayData.tradeLength === 1 ? 'trade' : 'trades'}
              </span>
            </>
          )}
        </div>
      );
    }

    return cells;
  };

  const weeklyProfits = calculateWeeklyProfits(selectedYear, selectedMonth);

  const handlePrevMonth = () => {
    setIsDropdownVisible(false);
    if (selectedMonth === 0) {
      setSelectedYear((prev) => prev - 1);
      setSelectedMonth(11);
      setcalYear(selectedYear - 1);
      setcalMonth(12);
    } else {
      setSelectedMonth((prev) => prev - 1);
      setcalYear(selectedYear);
      setcalMonth(selectedMonth);
    }
  };

  const handleNextMonth = () => {
    setIsDropdownVisible(false);
    if (selectedMonth === 11) {
      setSelectedYear((prev) => prev + 1);
      setSelectedMonth(0);
      setcalYear(selectedYear + 1);
      setcalMonth(1);
    } else {
      setSelectedMonth((prev) => prev + 1);
      setcalYear(selectedYear);
      setcalMonth(selectedMonth + 2);
    }
  };

  const monthName = new Date(selectedYear, selectedMonth).toLocaleString("default", { month: "long" });

  return (
    <div className="flex-1 bg-card/50 backdrop-blur-sm border border-border/50 rounded-2xl p-4 sm:p-5 overflow-hidden">
      <div className="flex justify-between items-center mb-4 sm:mb-5">
        <button 
          onClick={handlePrevMonth}
          className="w-8 h-8 rounded-lg flex items-center justify-center text-muted-foreground hover:text-foreground hover:bg-muted transition-colors"
        >
          <ChevronLeft className="h-4 w-4" />
        </button>

        <div className="relative" ref={dropdownRef}>
          <button
            onClick={() => setIsDropdownVisible(!isDropdownVisible)}
            className="flex items-center gap-2 px-4 py-2 rounded-xl hover:bg-muted/50 transition-colors"
          >
            <span className="text-base sm:text-lg font-semibold text-foreground">
              {monthName}
            </span>
            <span className="text-base sm:text-lg text-muted-foreground">
              {selectedYear}
            </span>
            <ChevronDown className={cn(
              "h-4 w-4 text-muted-foreground transition-transform",
              isDropdownVisible && "rotate-180"
            )} />
          </button>

          {isDropdownVisible && (
            <div className="absolute top-full left-1/2 -translate-x-1/2 mt-2 bg-card border border-border rounded-xl shadow-xl z-50 p-4 w-64">
              <div className="flex items-center justify-center mb-3">
                <button
                  onClick={() => setShowYearView(!showYearView)}
                  className="flex items-center gap-1 text-sm font-medium text-muted-foreground hover:text-foreground transition-colors"
                >
                  {showYearView ? monthName : selectedYear}
                  <ChevronDown className="h-3 w-3" />
                </button>
              </div>

              {!showYearView ? (
                <div className="grid grid-cols-3 gap-2">
                  {Array.from({ length: 12 }, (_, i) => (
                    <button
                      key={i}
                      className={cn(
                        "px-2 py-2 text-xs rounded-lg transition-colors font-medium",
                        i === selectedMonth
                          ? "bg-foreground text-background"
                          : "hover:bg-muted text-foreground"
                      )}
                      onClick={() => {
                        setSelectedMonth(i);
                        setcalMonth(i + 1);
                        setIsDropdownVisible(false);
                      }}
                    >
                      {new Date(0, i).toLocaleString("default", { month: "short" })}
                    </button>
                  ))}
                </div>
              ) : (
                <div
                  className="grid grid-cols-3 gap-2 max-h-40 overflow-y-auto scrollbar-thin"
                  ref={yearContainerRef}
                >
                  {Array.from({ length: new Date().getFullYear() - 2000 + 1 }, (_, i) => 2000 + i).map(
                    (year) => (
                      <button
                        key={year}
                        className={cn(
                          "px-2 py-2 text-xs rounded-lg transition-colors font-medium",
                          year === selectedYear
                            ? "bg-foreground text-background year-active"
                            : "hover:bg-muted text-foreground"
                        )}
                        onClick={() => {
                          setSelectedYear(year);
                          setcalYear(year);
                          setShowYearView(false);
                        }}
                      >
                        {year}
                      </button>
                    )
                  )}
                </div>
              )}
            </div>
          )}
        </div>

        <button 
          onClick={handleNextMonth}
          className="w-8 h-8 rounded-lg flex items-center justify-center text-muted-foreground hover:text-foreground hover:bg-muted transition-colors"
        >
          <ChevronRight className="h-4 w-4" />
        </button>
      </div>

      <div className="flex gap-2 sm:gap-3 mb-4">
        <div className="flex-1 min-w-0">
          <div className="grid grid-cols-7 gap-1 sm:gap-1.5 mb-1 sm:mb-2">
            {["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].map((day) => (
              <div key={day} className="text-center text-[8px] sm:text-[10px] font-semibold text-muted-foreground/70 uppercase tracking-wider py-1 sm:py-2">
                {day}
              </div>
            ))}
          </div>
          <div className="grid grid-cols-7 gap-1 sm:gap-1.5">
            {renderCalendar()}
          </div>
        </div>

        <div className="hidden sm:flex w-[72px] flex-col gap-1.5 pt-8">
          {weeklyProfits.map((profit, index) => (
            <div
              key={index}
              className={cn(
                "h-[80px] rounded-xl flex flex-col items-center justify-center text-center transition-all",
                profit !== 0 
                  ? "bg-card/80 border border-border/50" 
                  : "bg-muted/20"
              )}
            >
              <span className="text-[9px] text-muted-foreground/70 font-medium">Week {index + 1}</span>
              <span className={cn(
                "text-xs font-bold mt-0.5",
                profit > 0 ? "text-profit" : profit < 0 ? "text-loss" : "text-muted-foreground/50"
              )}>
                {profit !== 0 ? formatCurrencyDisplay(profit) : formatCompactCurrency(0, currency, exchangeRate, accountBalance)}
              </span>
            </div>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-3 gap-2 sm:gap-3 pt-3 border-t border-border/50">
        <div className="bg-muted/20 rounded-xl p-2.5 sm:p-3 text-center">
          <div className="flex items-center justify-center gap-1 sm:gap-1.5 mb-0.5 sm:mb-1">
            <TrendingUp className={cn(
              "w-3 h-3 sm:w-3.5 sm:h-3.5",
              monthlyStats.totalPnL >= 0 ? "text-profit" : "text-loss"
            )} />
            <span className="text-[9px] sm:text-xs text-muted-foreground">Monthly P&L</span>
          </div>
          <p className={cn(
            "text-sm sm:text-lg font-bold",
            monthlyStats.totalPnL >= 0 ? "text-profit" : "text-loss"
          )}>
            {monthlyStats.totalPnL >= 0 ? "+" : "-"}{formatCurrencyDisplay(monthlyStats.totalPnL)}
          </p>
        </div>

        <div className="bg-muted/20 rounded-xl p-2.5 sm:p-3 text-center">
          <div className="flex items-center justify-center gap-1 sm:gap-1.5 mb-0.5 sm:mb-1">
            <BarChart3 className="w-3 h-3 sm:w-3.5 sm:h-3.5 text-primary" />
            <span className="text-[9px] sm:text-xs text-muted-foreground">Total Trades</span>
          </div>
          <p className="text-sm sm:text-lg font-bold text-foreground">
            {monthlyStats.totalTrades}
          </p>
        </div>

        <div className="bg-muted/20 rounded-xl p-2.5 sm:p-3 text-center">
          <div className="flex items-center justify-center gap-1 sm:gap-1.5 mb-0.5 sm:mb-1">
            <CalendarIcon className="w-3 h-3 sm:w-3.5 sm:h-3.5 text-purple-400" />
            <span className="text-[9px] sm:text-xs text-muted-foreground">Win Rate</span>
          </div>
          <p className="text-sm sm:text-lg font-bold text-foreground">
            {monthlyStats.winRate}%
          </p>
        </div>
      </div>
    </div>
  );
};

export default Calendar;

src/components/strategy/components/Strat.content:
"use client"
import React, { useState, useRef, useEffect } from "react";
import { ChevronDown, Check } from "lucide-react";

interface StrategyDropdownProps {
  allStrategies: string[];
  selected: string[];
  setSelected: (strategies: string[]) => void;
}

const StrategyDropdown: React.FC<StrategyDropdownProps> = ({ 
  allStrategies, 
  selected, 
  setSelected 
}) => {
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) {
        setOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const toggleSelect = (strategy: string) => {
    const newSelection = selected.includes(strategy)
      ? selected.filter((s) => s !== strategy)
      : [...selected, strategy];
    setSelected(newSelection);
  };

  return (
    <div className="relative w-full sm:w-auto" ref={ref}>
      <button 
        className="flex items-center justify-between sm:justify-start gap-2 w-full sm:w-auto bg-card text-foreground border border-border px-4 py-2.5 rounded-lg cursor-pointer transition-all duration-200 hover:bg-muted text-sm font-medium touch-manipulation"
        onClick={() => setOpen(!open)}
      >
        Strategies
        <ChevronDown className={`w-4 h-4 transition-transform ${open ? 'rotate-180' : ''}`} />
      </button>
      {open && (
        <div className="absolute left-0 sm:left-auto sm:right-0 top-full mt-2 bg-card border border-border rounded-xl p-2 shadow-lg z-30 w-full sm:min-w-[200px] max-h-[60vh] overflow-y-auto">
          {allStrategies.length === 0 ? (
            <p className="text-muted-foreground text-sm px-3 py-2">No strategies available</p>
          ) : (
            allStrategies.map((strategy) => (
              <label 
                key={strategy} 
                className="flex items-center gap-3 text-foreground cursor-pointer py-2.5 px-3 hover:bg-muted rounded-lg transition-colors text-sm touch-manipulation"
              >
                <div className={`w-5 h-5 rounded border flex items-center justify-center transition-colors flex-shrink-0 ${
                  selected.includes(strategy) 
                    ? 'bg-primary border-primary' 
                    : 'border-border'
                }`}>
                  {selected.includes(strategy) && <Check className="w-3.5 h-3.5 text-primary-foreground" />}
                </div>
                <input
                  type="checkbox"
                  checked={selected.includes(strategy)}
                  onChange={() => toggleSelect(strategy)}
                  className="sr-only"
                />
                <span className="truncate">{strategy}</span>
              </label>
            ))
          )}
        </div>
      )}
    </div>
  );
};

export default StrategyDropdown;

src/components/dashboard-components/dash.content:
"use client";

import React from 'react';
import { Doughnut } from "react-chartjs-2";
import { Chart as ChartJS, ArcElement, Tooltip, Legend, DoughnutController } from "chart.js";
import { DollarSign, Target, Activity, Wallet, Scale } from "lucide-react";
import { cn } from "@/lib/utils";
import TinyChart from "./TinyChart";
import useCurrencyStore, { formatCurrencyValue, formatCompactCurrency } from "@/store/currencyStore";

ChartJS.register(DoughnutController, ArcElement, Tooltip, Legend);

interface DashWidgetsProps {
  data: { value: number }[];
  pnl: number | string;
  winrate?: number | string;
  winners?: number;
  losers?: number;
  profitF: number | string;
  avgProfits: number;
  avgLoses: number;
  rrRatio: number | string;
  accBal: number | string;
  totalProfits: number;
  totalLoses: number;
}

interface StatCardProps {
  title: string;
  value: string | number;
  subtitle?: string;
  icon?: React.ReactNode;
  iconColor?: 'blue' | 'emerald' | 'amber' | 'violet' | 'rose' | 'neutral';
  status?: string;
  valueType?: 'profit' | 'loss' | 'neutral';
  children?: React.ReactNode;
}

const StatCard: React.FC<StatCardProps> = ({ 
  title, 
  value, 
  subtitle, 
  icon, 
  iconColor = 'neutral',
  status,
  valueType = 'neutral',
  children 
}) => {
  const getValueColor = () => {
    switch (valueType) {
      case 'profit': return 'text-profit';
      case 'loss': return 'text-loss';
      default: return 'text-foreground';
    }
  };

  const getIconColorClasses = () => {
    switch (iconColor) {
      case 'blue': return 'bg-blue-500/10 text-blue-400';
      case 'emerald': return 'bg-emerald-500/10 text-emerald-400';
      case 'amber': return 'bg-amber-500/10 text-amber-400';
      case 'violet': return 'bg-violet-500/10 text-violet-400';
      case 'rose': return 'bg-rose-500/10 text-rose-400';
      default: return 'bg-muted/50 text-muted-foreground';
    }
  };

  return (
    <div className="group bg-card/50 backdrop-blur-sm border border-border/50 rounded-xl px-3.5 py-3 transition-all duration-300 hover:bg-card/80 hover:border-border">
      <div className="flex items-start justify-between mb-2">
        <div className="flex items-center gap-2">
          {icon && (
            <div className={cn("p-1.5 rounded-lg", getIconColorClasses())}>
              {icon}
            </div>
          )}
          <span className="text-xs font-medium text-muted-foreground">
            {title}
          </span>
        </div>
        {status && (
          <span className="px-2 py-0.5 rounded-full text-[9px] font-semibold uppercase tracking-wide bg-muted/50 text-muted-foreground">
            {status}
          </span>
        )}
      </div>

      <div className="flex items-end justify-between gap-3">
        <div className="min-w-0 flex-1">
          <p className={cn(
            "text-lg font-bold tracking-tight truncate",
            getValueColor()
          )}>
            {value}
          </p>
          {subtitle && (
            <p className="text-[10px] text-muted-foreground mt-0.5">{subtitle}</p>
          )}
        </div>
        {children && (
          <div className="flex-shrink-0">
            {children}
          </div>
        )}
      </div>
    </div>
  );
};

const DashWidgets: React.FC<DashWidgetsProps> = ({ 
  data, 
  pnl, 
  winners = 0, 
  losers = 0, 
  profitF, 
  avgProfits, 
  avgLoses, 
  rrRatio, 
  accBal, 
}) => {
  const { currency, exchangeRate } = useCurrencyStore();

  const numericPnl = typeof pnl === 'string' ? parseFloat(pnl) : pnl;
  const winrate = winners || losers ? ((winners / (winners + losers)) * 100).toFixed(1) : '0';
  const totalTrades = winners + losers;
  const balanceValue = typeof accBal === 'string' ? parseFloat(accBal) : accBal;

  const pnlFormatted = formatCurrencyValue(Math.abs(numericPnl), currency, exchangeRate, balanceValue);
  const balanceFormatted = formatCurrencyValue(balanceValue, currency, exchangeRate);
  const avgProfitFormatted = formatCompactCurrency(avgProfits || 0, currency, exchangeRate);
  const avgLossFormatted = formatCompactCurrency(Math.abs(avgLoses || 0), currency, exchangeRate);

  const dataWinLoss = {
    labels: ["Wins", "Losses"],
    datasets: [
      {
        data: [winners, losers],
        backgroundColor: ["rgba(34, 197, 94, 0.7)", "rgba(239, 68, 68, 0.7)"],
        hoverBackgroundColor: ["rgba(34, 197, 94, 0.9)", "rgba(239, 68, 68, 0.9)"],
        borderColor: ["rgba(34, 197, 94, 1)", "rgba(239, 68, 68, 1)"],
        borderWidth: 1,
        spacing: 2,
      },
    ],
  };

  const optionsWinLoss = {
    responsive: true,
    maintainAspectRatio: true,
    cutout: "70%",
    rotation: -90,
    circumference: 180,
    plugins: {
      legend: { display: false },
      tooltip: { enabled: true },
    },
    elements: {
      arc: { borderRadius: 4 },
    },
  };

  const profitFactorNum = parseFloat(profitF as string);
  const profitFactorStatus = profitFactorNum >= 1.5 ? "Good" : profitFactorNum >= 1 ? "Even" : "Needs work";

  const avgProfitPercentage = avgProfits && avgLoses ? (avgProfits / (Math.abs(avgProfits) + Math.abs(avgLoses))) * 100 : 50;

  return (
    <div className="grid grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-3 sm:gap-4">
      <StatCard
        title="Net P&L"
        value={numericPnl >= 0 ? pnlFormatted : pnlFormatted.replace(/^([₹$])/, '-$1')}
        icon={<DollarSign className="w-4 h-4" />}
        iconColor="emerald"
        valueType={numericPnl > 0 ? 'profit' : numericPnl < 0 ? 'loss' : 'neutral'}
        subtitle={numericPnl !== 0 ? `${numericPnl >= 0 ? '+' : ''}${((numericPnl / (balanceValue || 1)) * 100).toFixed(1)}% return` : 'No change'}
      >
        <div className="w-16 h-8">
          <TinyChart data={data} />
        </div>
      </StatCard>

      <div className="group bg-card/50 backdrop-blur-sm border border-border/50 rounded-xl px-3.5 py-3 transition-all duration-300 hover:bg-card/80 hover:border-border">
        <div className="flex items-center gap-2 mb-1.5">
          <div className="p-1.5 rounded-lg bg-blue-500/10 text-blue-400">
            <Target className="w-4 h-4" />
          </div>
          <span className="text-xs font-medium text-muted-foreground">Win Rate</span>
        </div>

        <div className="flex items-center justify-between">
          <div>
            <p className="text-lg font-bold text-foreground">{winrate}%</p>
            <p className="text-[10px] text-muted-foreground mt-0.5">{totalTrades} trades</p>
          </div>

          <div className="flex flex-col items-center">
            <div className="relative w-20 h-12">
              <Doughnut data={dataWinLoss} options={optionsWinLoss} />
            </div>
            <div className="flex items-center gap-1 -mt-1">
              <span className="px-1.5 py-0.5 rounded text-[9px] font-bold bg-profit/20 text-profit">{winners}</span>
              <span className="px-1 py-0.5 rounded text-[9px] font-medium bg-muted/50 text-muted-foreground">0</span>
              <span className="px-1.5 py-0.5 rounded text-[9px] font-bold bg-loss/20 text-loss">{losers}</span>
            </div>
          </div>
        </div>
      </div>

      <StatCard
        title="Profit Factor"
        value={typeof profitF === 'number' ? profitF.toFixed(2) : profitF}
        subtitle={profitFactorStatus}
        icon={<Activity className="w-4 h-4" />}
        iconColor="amber"
        status={profitFactorNum >= 1.5 ? "Profitable" : profitFactorNum < 1 ? "Losing" : "Breakeven"}
      />

      <StatCard
        title="Account Balance"
        value={balanceFormatted}
        icon={<Wallet className="w-4 h-4" />}
        iconColor="violet"
        subtitle="Current balance"
      >
        <div className="w-16 h-8">
          <TinyChart data={data} />
        </div>
      </StatCard>

      <StatCard
        title="Risk : Reward"
        value={typeof rrRatio === 'number' ? `1:${rrRatio.toFixed(1)}` : `1:${rrRatio}`}
        icon={<Scale className="w-4 h-4" />}
        iconColor="rose"
      >
        <div className="w-full">
          <div className="w-full h-1.5 bg-muted/30 rounded-full overflow-hidden flex">
            <div 
              className="h-full bg-foreground/40 rounded-l-full transition-all"
              style={{ width: `${avgProfitPercentage}%` }}
            />
            <div 
              className="h-full bg-foreground/15 rounded-r-full transition-all"
              style={{ width: `${100 - avgProfitPercentage}%` }}
            />
          </div>
          <div className="flex justify-between mt-1.5">
            <span className="text-[9px] text-profit font-medium">
              +{avgProfitFormatted}
            </span>
            <span className="text-[9px] text-loss font-medium">
              -{avgLossFormatted}
            </span>
          </div>
        </div>
      </StatCard>
    </div>
  );
};

export default DashWidgets;

src/app/login/spare.tsx.content:
"use client";

import { useState, FormEvent } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";

export default function LoginPage() {

  const router = useRouter();

  const [loginData, setLoginData] = useState({
    email: "",
    password: "",
  });

  const [error, setError] = useState("");

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setLoginData({ ...loginData, [name]: value });
  };

  const postLoginDetails = async (e: FormEvent) => {
    e.preventDefault();
    const { email, password } = loginData;

    try {
      const res = await fetch("/api/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include", // ✅ this allows browser to store cookies from backend
        body: JSON.stringify({ email, password }),
      });

      const data = await res.json();

      if (res.status === 200) {
        router.push(`/welcome/${data.name}`);
      } else {
        if (data.error === "Invalid credentials") {
          setError("Invalid credentials, please recheck your Email & Password");
        } else if (data.error === "Enter all the details") {
          setError("Fill all the entries");
        } else {
          setError("Something went wrong. Please try again.");
        }
      }
    } catch (err) {
      console.error("Login error:", err);
      setError("Server error. Please try again later.");
    }
  };

  return (
    <div className="relative flex min-h-screen w-full items-center justify-center bg-[#1A1A1A] text-white overflow-hidden">
      {/* Background Overlay */}
      <div className="absolute inset-0 z-0 opacity-30 bg-[url('/images/bg-pattern.png')] bg-repeat bg-center"></div>
      <div className="absolute inset-0 bg-[#2828287b] z-0"></div>

      <div className="relative z-10 flex w-full max-w-[1450px] flex-col md:flex-row items-center justify-center gap-10 px-6">
        {/* Left Section */}
        <div className="w-full md:w-2/3 space-y-8 p-4">
          <h3 className="text-4xl md:text-6xl font-bold ml-4">
            Let’s <span className="text-[#FFA734]">Signup</span>
          </h3>

          <div className="bg-[#1A1A1A] rounded-2xl p-8 md:p-12 text-white">
            <p className="w-fit px-4 py-1 text-sm text-orange-400 bg-[#388cfa24] border border-[#388cfa] rounded-full">
              ✨ Advanced Trade Analytics Platform
            </p>

            <h1 className="mt-6 text-3xl md:text-5xl font-semibold leading-tight">
              Data doesn’t lie — and neither will your{" "}
              <span className="text-[#FFAC5E]">trading journal</span>. Let’s get
              started.
            </h1>

            <p className="mt-6 text-gray-400 text-base md:text-lg w-full md:w-2/3">
              The most advanced trade journaling and performance analytics
              platform designed for serious traders. Auto-sync your trades,
              analyze your performance, and accelerate your growth.
            </p>

            <div className="flex justify-between mt-8 border-t border-gray-700 pt-6 flex-wrap gap-4">
              <div className="flex flex-col items-center">
                <h2 className="text-orange-400 text-2xl md:text-3xl font-semibold">
                  50K+
                </h2>
                <span className="text-gray-400 text-sm">Active Traders</span>
              </div>
              <div className="flex flex-col items-center">
                <h2 className="text-green-500 text-2xl md:text-3xl font-semibold">
                  98.2%
                </h2>
                <span className="text-gray-400 text-sm">Accuracy Rate</span>
              </div>
              <div className="flex flex-col items-center">
                <h2 className="text-orange-400 text-2xl md:text-3xl font-semibold">
                  $2.4B+
                </h2>
                <span className="text-gray-400 text-sm">Trades Analysed</span>
              </div>
            </div>
          </div>
        </div>

        {/* Right Section */}
        <div className="w-full md:w-1/3 bg-gradient-to-br from-[#17191d9f] to-[#1e212492] backdrop-blur-md shadow-2xl rounded-2xl flex flex-col items-center p-8 md:p-10">
          <img
            src="/images/logoDark.png"
            alt="Logo"
            className="w-40 md:w-56 mt-4 mb-6"
          />

          <h1 className="text-2xl font-medium">Welcome back</h1>
          <p className="text-gray-400 text-sm mt-2 mb-4">
            Login to your trading journal.
          </p>

          <form
            onSubmit={postLoginDetails}
            className="w-full flex flex-col items-center gap-4"
          >
            <input
              type="text"
              name="email"
              placeholder="Email or Phone"
              value={loginData.email}
              onChange={handleInputChange}
              required
              className="w-11/12 rounded-xl bg-[#191D24] text-white px-4 py-3 outline-none text-sm"
            />
            <input
              type="password"
              name="password"
              placeholder="Password"
              value={loginData.password}
              onChange={handleInputChange}
              required
              className="w-11/12 rounded-xl bg-[#191D24] text-white px-4 py-3 outline-none text-sm"
            />
            {error && <p className="text-red-500 text-sm">{error}</p>}

            <button
              type="submit"
              className="w-11/12 bg-[#DDDDDD] text-[#111] font-medium py-3 rounded-xl mt-2 hover:bg-white transition"
            >
              Log In
            </button>

            <div className="w-11/12 flex justify-between text-xs mt-4 text-[#94A3B8]">
              <Link href="/forgotpassword" className="text-[#00E6B0]">
                Forgot Password?
              </Link>
              <Link href="/signup" className="text-[#94A3B8]">
                New to TYT? Create account
              </Link>
            </div>
          </form>

          <button
            className="w-11/12 flex items-center justify-center bg-black text-[#94A3B8] border border-[#F8FAFC1A] rounded-xl py-2 mt-6 hover:bg-[#111] transition"
          >
            <i className="fa-brands fa-google mr-2"></i>
            <span>Sign in with Google</span>
          </button>

          <button
            className="w-11/12 flex items-center justify-center bg-black text-[#94A3B8] border border-[#F8FAFC1A] rounded-xl py-2 mt-3 hover:bg-[#111] transition"
          >
            <i className="fa-brands fa-apple mr-2"></i>
            <span>Sign in with Apple</span>
          </button>

          <div className="w-2/3 mt-4">
            <img src="/images/purple-bar.png" alt="Bar" className="w-full" />
          </div>
        </div>
      </div>
    </div>
  );
}

