src/utils/reports/calculateCumulativePnL.content:
// utils/calculateCumulativePnL.ts

interface Trade {
  date: string;
  Profit: number;
  Commission: number;
  Swap: number;
}

interface CumulativePnLDataPoint {
  date: string;
  value: number;
}

/**
 * Calculates cumulative P&L data points from an array of trade objects.
 * @param {Array} trades - Array of trade objects.
 * @returns {Array} An array of objects with 'date' and 'value' properties for the cumulative P&L chart.
 */
export const calculateCumulativePnL = (trades: Trade[]): CumulativePnLDataPoint[] => {
  if (!Array.isArray(trades) || trades.length === 0) {
    // Return default structure instead of empty array to prevent crashes
    return [
      {
        date: new Date().toISOString().split('T')[0], // Today's date in YYYY-MM-DD format
        value: 0
      }
    ];
  }

  // --- Aggregate P&L by Date ---
  const dailyPnL: { [key: string]: number } = {}; // date (YYYY-MM-DD) -> cumulative P&L for that date

  trades.forEach(trade => {
    // Calculate P&L for this trade (Profit + Commission + Swap)
    const tradePnL = trade.Profit + Number(trade.Commission)||0 + trade.Swap;
    const dateKey = trade.date; // Assuming 'date' is YYYY-MM-DD

    if (!dailyPnL[dateKey]) {
      dailyPnL[dateKey] = 0;
    }
    dailyPnL[dateKey] += tradePnL;
  });

  // --- Sort dates and Calculate Cumulative Total ---
  const sortedDates = Object.keys(dailyPnL).sort((a, b) => new Date(a).getTime() - new Date(b).getTime());
  const cumulativePnLData: CumulativePnLDataPoint[] = [];
  let runningTotal = 0;

  sortedDates.forEach(date => {
    runningTotal += dailyPnL[date];
    cumulativePnLData.push({
      date: date,
      value: parseFloat(runningTotal.toFixed(2)) // Round to 2 decimal places
    });
  });

  return cumulativePnLData;
};

src/components/dashboard-components/Dash.content:
"use client";

import { useState, useEffect, useRef } from "react";
import { useParams } from "next/navigation";
import { usePathname } from "next/navigation";
import "./DashboardNav.css";
import useAccountDetails from "@/store/accountdetails";
import notebookStore from "@/store/notebookStore";
import calendarPopUp from "@/store/calendarPopUp";
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faDollarSign, faIndianRupeeSign, faPercent, faAsterisk, faCaretDown, faUserGear, faFileInvoice } from '@fortawesome/free-solid-svg-icons';

interface Account {
  _id: string;
  accountName: string;
  checked: boolean;
}

interface DashboardNavProps {
  expanded: boolean;
  setExpanded: React.Dispatch<React.SetStateAction<boolean>>;
}

const DashboardNav = ({ expanded, setExpanded }: DashboardNavProps) => {

  const pathname = usePathname();

  const params = useParams();
  const userId = params.userId as string;

  const [isAccOpen, setAcc] = useState(false);
  const [isCurrOpen, setCrr] = useState(false);
  const [allSelected, setAllSelected] = useState(false);

  // Refs
  const accDropdownRef = useRef<HTMLDivElement>(null);
  const currDropdownRef = useRef<HTMLDivElement>(null);
  const accButtonRef = useRef<HTMLLIElement>(null);
  const currButtonRef = useRef<HTMLLIElement>(null);

  // Store hooks
  const { setAddAcc } = calendarPopUp();
  const { accounts, setAccounts, updateAccView, checkAll } = useAccountDetails();
  const { setNotes } = notebookStore();

  const getHeadingFromPath = () => {
    if (pathname === "/" || pathname === `/${userId}`) return "Dashboard";
    if (pathname.includes("/daily-journal")) return "Daily Journal";
    if (pathname.includes("/notebook")) return "Notebook";
    if (pathname.includes("/reports")) return "Reports";
    if (pathname.includes("/strategies")) return "Strategies";
    if (pathname.includes("/support")) return "Support";
    if (pathname.includes("/settings")) return "Settings";

    return "Dashboard"; // default
  };

  // Click outside handler
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (
        accDropdownRef.current &&
        !accDropdownRef.current.contains(event.target as Node) &&
        accButtonRef.current &&
        !accButtonRef.current.contains(event.target as Node) &&
        currDropdownRef.current &&
        !currDropdownRef.current.contains(event.target as Node) &&
        currButtonRef.current &&
        !currButtonRef.current.contains(event.target as Node)
      ) {
        setAcc(false);
        setCrr(false);
      }
    };

    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, []);

  const handleAccountChange = (_id: string) => {
    const updatedAccounts = accounts.map(account =>
      account._id === _id ? { ...account, checked: !account.checked } : account
    );

    const allChecked = updatedAccounts.every(account => account.checked);
    setAllSelected(allChecked);
  };

  const handleAllAccountsChange = () => {
    const newAllSelected = !allSelected;
    setAllSelected(newAllSelected);
    checkAll(newAllSelected);
  };

  const getAccDetails = async () => {
    setAccounts();
    setNotes();
  };

  useEffect(() => {
    getAccDetails();
    setAllSelected(accounts.every(account => account.checked === true));
  }, []);

  return (
    <div className="w-full -mt-5 h-16 flex items-center justify-between transition-all duration-300 px-4 font-inter">

      {/* Left spacer for layout balance */}
      <div className="w-10" />

      {/* Right Section - Navigation Items */}
      <div className="flex items-center">
        <ul className="flex items-center space-x-4">

          <li className="relative">
            <button
              className="flex items-center space-x-2 bg-[#252525] backdrop-blur-md rounded-lg px-3 py-2 text-white cursor-pointer transition-colors hover:bg-[#252525]/40 "
              onClick={() => { setCrr(!isCurrOpen); setAcc(false); }}
              ref={currButtonRef}
            >
              <FontAwesomeIcon icon={faDollarSign} className="text-white" />
              <FontAwesomeIcon icon={faCaretDown} className="text-white text-xs" />
            </button>

            <div
              ref={currDropdownRef}
              className={`absolute top-12 right-0 w-48 bg-[#252525] backdrop-blur-md rounded-lg shadow-2xl transition-all duration-300 transform origin-top ${isCurrOpen
                ? "scale-100 opacity-100 visible"
                : "scale-95 opacity-0 invisible"
                }`}
            >
              <div className="p-2">
                <button className="w-full flex items-center justify-between px-3 py-2 text-white hover:bg-gray-700/60 rounded-md transition-colors">
                  Dollar <FontAwesomeIcon icon={faDollarSign} />
                </button>
                <button className="w-full flex items-center justify-between px-3 py-2 text-white hover:bg-gray-700/60 rounded-md transition-colors">
                  Rupees <FontAwesomeIcon icon={faIndianRupeeSign} />
                </button>
                <button className="w-full flex items-center justify-between px-3 py-2 text-white hover:bg-gray-700/60 rounded-md transition-colors">
                  Percentage <FontAwesomeIcon icon={faPercent} />
                </button>
                <button className="w-full flex items-center justify-between px-3 py-2 text-white hover:bg-gray-700/60 rounded-md transition-colors">
                  R factor <FontAwesomeIcon icon={faAsterisk} />
                </button>
              </div>
            </div>
          </li>

          <li className="relative">
            <button
              className="text-[14px] flex items-center space-x-2 bg-[#252525] backdrop-blur-md rounded-lg px-3 py-2 text-white cursor-pointer transition-colors hover:bg-[#252525]/40 "
              onClick={() => { setAcc(!isAccOpen); setCrr(false); }}
              ref={accButtonRef}
            >
              <FontAwesomeIcon icon={faFileInvoice} />
              <span className="text-[14px]" >Accounts</span>
              <FontAwesomeIcon icon={faCaretDown} className="text-xs" />
            </button>

            <div
              ref={accDropdownRef}
              className={`absolute top-12 right-0 w-64 bg-[#252525] backdrop-blur-md rounded-lg shadow-2xl transition-all duration-300 transform origin-top ${isAccOpen
                ? "scale-100 opacity-100 visible"
                : "scale-95 opacity-0 invisible"
                }`}
            >
              <div className="p-3">
                {accounts.length === 0 ? (
                  <>
                    <div className="text-center py-4 text-gray-300">
                      No accounts added
                    </div>
                    <button
                      onClick={() => setAddAcc()}
                      className="w-full flex items-center px-3 py-2 text-gray-300 hover:bg-gray-700/60 rounded-md transition-colors mt-2"
                    >
                      <FontAwesomeIcon icon={faUserGear} className="mr-3" />
                      <span>Add Accounts</span>
                    </button>
                  </>
                ) : (
                  <>
                    <div className="flex items-center px-2 py-2 border-b border-gray-600 mb-2">
                      <input
                        type="checkbox"
                        checked={allSelected}
                        onChange={handleAllAccountsChange}
                        className="w-4 h-4 text-purple-600 bg-gray-700 border-gray-600 rounded focus:ring-purple-500 focus:ring-2 cursor-pointer"
                      />
                      <span className="ml-3 text-white text-sm font-medium">All Accounts</span>
                    </div>

                    <div className="max-h-48 overflow-y-auto">
                      {accounts.map((account) => (
                        <label
                          key={account._id}
                          className="flex items-center px-2 py-2 cursor-pointer hover:bg-gray-700/60 rounded-md transition-colors"
                        >
                          <input
                            type="checkbox"
                            checked={account.checked}
                            onChange={() => {
                              handleAccountChange(account._id);
                              updateAccView(account.accountName);
                            }}
                            className="w-4 h-4 text-purple-600 bg-gray-700 border-gray-600 rounded focus:ring-purple-500 focus:ring-2 cursor-pointer"
                          />
                          <span className="ml-3 text-white text-sm">{account.accountName}</span>
                        </label>
                      ))}
                    </div>

                    <button
                      onClick={() => setAddAcc()}
                      className="w-full flex items-center px-2 py-3 text-gray-300 hover:bg-gray-700/60 rounded-md transition-colors mt-2 border-t border-gray-600"
                    >
                      <FontAwesomeIcon icon={faUserGear} className="mr-3 ml-2" />
                      <span>Manage Accounts</span>
                    </button>
                  </>
                )}
              </div>
            </div>
          </li>
        </ul>
      </div>
    </div>
  );
};

export default DashboardNav;

