'use client';

import { useParams } from "next/navigation";
import Cookies from "js-cookie";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faTrash, faClose } from "@fortawesome/free-solid-svg-icons";
import useAccountDetails from "@/store/accountdetails";
import calendarPopUp from "@/store/calendarPopUp";

const DjImgPopup = () => {
    const { showDjImg, djImgUrl, setDjImg } = calendarPopUp();
    const { setAccounts } = useAccountDetails();


    const deleteImg = async (e: React.MouseEvent) => {
        e.preventDefault();

        try {
            const res = await fetch(`/api/daily-journal/delete`, {
                method: "DELETE",
                headers: {
                    "Content-Type": "application/json"
                },
                body: JSON.stringify({
                    url: djImgUrl,apiName:'deleteImage'
                })
            });

            const data = await res.json();

            if (res.status === 200) {
                document.body.classList.remove("no-scroll");
                setAccounts();
                setDjImg();
            } else {
                console.log(data.error);
            }
        } catch (error) {
            console.log(error);
        }
    };

    const closePopup = () => {
        setDjImg();
        document.body.classList.remove("no-scroll");
    };

    return (
        <div className={`fixed inset-0 bg-black bg-opacity-40 z-50 flex flex-col items-center justify-center ${showDjImg ? "flex" : "hidden"}`}>
            <div className="w-full h-screen flex items-center justify-center relative">
                <img 
                    src={djImgUrl} 
                    alt="djImg" 
                    className="w-4/5 max-w-4xl mx-auto"
                />
                <div className="absolute z-10 top-10 right-16 w-12 flex items-center justify-between">
                    <FontAwesomeIcon 
                        icon={faTrash} 
                        className="text-white text-xl cursor-pointer"
                        onClick={deleteImg}
                    />
                    <FontAwesomeIcon 
                        icon={faClose} 
                        className="text-white text-2xl cursor-pointer"
                        onClick={closePopup}
                    />
                </div>
            </div>
        </div>
    );
};

export default DjImgPopup;

src/components/settings/Security.tsx.content:
"use client";
import { useState } from "react";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faEye, faEyeSlash, faShield, faKey } from "@fortawesome/free-solid-svg-icons";

const Security = () => {
  const [showCurrent, setShowCurrent] = useState(false);
  const [showNew, setShowNew] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const [currentPwd, setCurrentPwd] = useState("");
  const [newPwd, setNewPwd] = useState("");
  const [confirmPwd, setConfirmPwd] = useState("");
  const [twoFactorEnabled, setTwoFactorEnabled] = useState(false);

  const handlePasswordChange = () => {
    if (newPwd !== confirmPwd) return;
    setCurrentPwd("");
    setNewPwd("");
    setConfirmPwd("");
  };

  return (
    <div className="space-y-4">
      <h2 className="text-lg font-semibold text-gray-900 dark:text-white">Security</h2>

      <div className="bg-white dark:bg-[#141414] rounded-xl border border-gray-200 dark:border-[#262626] p-4">
        <div className="flex items-center gap-3 mb-4">
          <div className="w-8 h-8 rounded-lg bg-emerald-500/10 flex items-center justify-center">
            <FontAwesomeIcon icon={faKey} className="text-emerald-500 text-sm" />
          </div>
          <span className="font-medium text-gray-900 dark:text-white">Change Password</span>
        </div>

        <div className="space-y-3">
          <PasswordField 
            label="Current Password"
            value={currentPwd}
            onChange={setCurrentPwd}
            show={showCurrent}
            onToggle={() => setShowCurrent(!showCurrent)}
          />
          <PasswordField 
            label="New Password"
            value={newPwd}
            onChange={setNewPwd}
            show={showNew}
            onToggle={() => setShowNew(!showNew)}
          />
          <PasswordField 
            label="Confirm Password"
            value={confirmPwd}
            onChange={setConfirmPwd}
            show={showConfirm}
            onToggle={() => setShowConfirm(!showConfirm)}
          />
          <button 
            onClick={handlePasswordChange}
            className="w-full py-2 bg-emerald-500 hover:bg-emerald-600 text-white text-sm font-medium rounded-lg transition-colors"
          >
            Update Password
          </button>
        </div>
      </div>

      <div className="bg-white dark:bg-[#141414] rounded-xl border border-gray-200 dark:border-[#262626] p-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
