import { create } from "zustand";

interface DatesForCalStore {
  calMonth: number;
  setcalMonth: (newData: number) => void;
  calYear: number;
  setcalYear: (newData: number) => void;
}

const datesforcal = create<DatesForCalStore>((set) => ({
  calMonth: new Date().getMonth() + 1, 
  setcalMonth: (newData: number) => set({ calMonth: newData }),

  calYear: new Date().getFullYear(),
  setcalYear: (newData: number) => set({ calYear: newData }),
}));

export default datesforcal;

src/app/verify/spare.tsx.content:
"use client";

import { useEffect, useState } from 'react';
import Image from 'next/image';
import { useRouter, useSearchParams } from 'next/navigation';
import "./Verifyemail.css";
// import Logo from "../../../images/Logo.png";

// stores
import { useDataStore as store } from '@/store/store';

const Verifyemail = () => {
  console.log("Verify Email Page Loaded");
    const { bkurl } = store();
    const searchParams = useSearchParams();
    const token = searchParams.get('t');
    console.log("the token in verify page is ",token);

    const [verified, setVerified] = useState(false);
    const [err, setErr] = useState("")
    const [dotFilled2, setDotFilled2] = useState(false);
    const [dotFilled3, setDotFilled3] = useState(false);
    const [tube1, setTube1] = useState(false);
    const [tube2, setTube2] = useState(false);
    const router = useRouter();

    const sendVerify = async () => {
        try {
            const res = await fetch(`api/verify-mail`, {
                method: "POST",
                headers: {
                    "Content-Type": "application/json"
                },
                body: JSON.stringify({
                    token
                })
            });

            const data = await res.json();

            if (res.status === 200) {
                setVerified(true)
            } else {
                if (data.error) {
                    setErr("Some problem occured while verifying your email... Please try again later.")
                }
            }
        } catch (error) {
            // console.log(error)
        }
    }

    useEffect(() => {
        sendVerify();

        setTimeout(() => {
            setTube1(true)
        }, 500);

        setTimeout(() => {
            setDotFilled2(true)
        }, 1000);

        setTimeout(() => {
            setTube2(true)
        }, 1500);

        setTimeout(() => {
            setDotFilled3(true)
        }, 2000);

        setTimeout(() => {
            sendVerify();
        }, 2500);
    }, []);
    const navigateToLogin = () => {
        router.push("/login");
    }

    return (
        <div className="w-screen min-h-screen grid place-content-center bg-[url('/images/loginbggradient.png')] bg-cover bg-center bg-no-repeat">
            <div className="w-[90vw] max-w-[400px] h-[600px] shadow-[rgba(0,0,0,0.24)_0px_3px_8px,rgb(38,57,77)_0px_20px_30px_-10px,rgba(50,50,93,0.25)_0px_50px_100px_-20px,rgba(0,0,0,0.3)_0px_30px_60px_-30px] flex flex-col items-center justify-start rounded-[25px] bg-white font-[SF_Pro_Display]">
                <Image 
                    className="mt-[15px]" 
                    src="/images/Logo.png"
                    alt="Logo" 
                    width={100} 
                    height={100}
                />
                <h1 className="text-[28px]">Email Verification</h1>
                <p className="py-[2px] text-[#817a7a] mx-[5px] text-[12px] font-[550]">Verifying your email...</p>

                <div className="mt-[20px] p-[20px] flex flex-col">
                    <div className="verifyprogress-content">
                        <div className="dot-ve"></div>
                        <p className="verifyprogress-text">Verification Initiated</p>
                    </div>
                    <div className="tube-ve">
                        <div className={tube1 ? "tube-ve-fill" : ""}></div>
                    </div>

                    <div className="verifyprogress-content">
                        <div className={dotFilled2 ? "dot-ve" : "dot-ve-bg"}></div>
                        <p className="verifyprogress-text">We're in Progress</p>
                    </div>
                    <div className="tube-ve">
                        <div className={tube2 ? "tube-ve-fill" : ""}></div>
                    </div>

                    <div className="verifyprogress-content">
                        <div className={dotFilled3 ? "dot-ve" : "dot-ve-bg"}></div>
                        <p className="verifyprogress-text">Email Verified</p>
                    </div>

                    {verified ? (
                        <button  onClick={navigateToLogin} className="verifyprogress_button">
                            LOGIN
                        </button>
                    ) : (
                        <button className="verify-disabled">
                            LOGIN
                        </button>
                    )}
                </div>
            </div>
        </div>
    )
}

export default Verifyemail;

src/components/reports/sub-report/Perfor.content:
"use client"

import React from 'react'
import { TrendingUp, TrendingDown, Activity, Trophy } from 'lucide-react'

interface PerformanceCardProps {
  title: string
  day: string
  trades: number
  pnl?: string
  icon: 'trending-up' | 'trending-down' | 'activity' | 'user-check'
  variant: 'profit' | 'loss' | 'warning' | 'primary'
}

const PerformanceCard: React.FC<PerformanceCardProps> = ({ title, day, trades, pnl, icon, variant }) => {
  const getIcon = (iconType: string) => {
    const iconClasses: Record<string, string> = {
      profit: 'text-profit',
      loss: 'text-loss',
      warning: 'text-warning',
      primary: 'text-primary',
    }
    const iconColor = iconClasses[variant] || 'text-primary'
    const iconClass = `h-4 w-4 ${iconColor}`

    switch (iconType) {
      case 'trending-up': 
        return <TrendingUp className={iconClass} />
      case 'trending-down': 
        return <TrendingDown className={iconClass} />
      case 'activity': 
        return <Activity className={iconClass} />
      case 'user-check': 
        return <Trophy className={iconClass} />
      default: 
        return <Activity className={iconClass} />
    }
  }

  const accentClasses: Record<string, string> = {
    profit: 'bg-profit',
    loss: 'bg-loss',
    warning: 'bg-warning',
    primary: 'bg-primary',
  }

  const iconBgClasses: Record<string, string> = {
    profit: 'bg-profit/10',
    loss: 'bg-loss/10',
    warning: 'bg-warning/10',
    primary: 'bg-primary/10',
  }

  const isProfit = pnl && !pnl.startsWith('-')
  const isLoss = pnl && pnl.startsWith('-')

  return (
    <div className="flex-1 bg-card rounded-xl border border-border overflow-hidden hover:border-primary/50 transition-all duration-200">
      {/* Color accent bar */}
      <div className={`h-1 ${accentClasses[variant] || 'bg-primary'}`} />

      {/* Content */}
      <div className="p-4">
        {/* Header */}
        <div className="flex items-center gap-2 mb-3">
          <div className={`w-7 h-7 rounded-lg flex items-center justify-center ${iconBgClasses[variant] || 'bg-primary/10'}`}>
            {getIcon(icon)}
          </div>
          <span className="text-xs font-medium text-muted-foreground uppercase tracking-wide">
            {title}
          </span>
        </div>

        {/* Day */}
        <div className="text-lg font-bold text-foreground mb-2">{day}</div>

        {/* Stats */}
        <div className="flex items-center justify-between">
          <span className="text-xs text-muted-foreground">
            {trades} trades
          </span>
          {pnl && (
            <span className={`text-sm font-semibold ${
              isLoss ? 'text-loss' : 'text-profit'
            }`}>
              {pnl}
            </span>
          )}
        </div>
      </div>
    </div>
  )
}

export default PerformanceCard

