                    </div>
                  </div>
                );
              })}
          </div>
        </div>

        {/* Contact Form */}
        <div>
          <h2 className="text-xl font-semibold text-foreground mb-4">Contact Support</h2>
          <div className={cn(
            "p-6 rounded-xl border",
            "bg-card border-border"
