src/components/daily-journal/PNLDailyJou.content:
"use client";

import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from "recharts";
import useCurrencyStore, { formatCompactCurrency } from "@/store/currencyStore";

interface Trade {
  time: string;
  Profit: number;
  Item: string;
}

interface GradientAreaChartProps {
  data: Trade[];
}

const GradientAreaChart = ({ data }: GradientAreaChartProps) => {
  const { currency, exchangeRate } = useCurrencyStore();
  const dataa = [
    { time: '', value: 0, Item: '' }
  ];

  let cumulativeValue = 0;

  data.forEach(trade => {
    const [hours, minutes] = trade.time.split(':');
    const shortTime = `${hours}:${minutes}`;

    cumulativeValue += trade.Profit;

    dataa.push({
      time: shortTime,
      value: parseFloat(cumulativeValue.toFixed(2)),
      Item: trade.Item
    });
  });

  const checkValueStatus = (data: { value: number }[]) => {
    const hasPositive = data.some(d => d.value > 0);
    const hasNegative = data.some(d => d.value < 0);

    if (hasPositive && hasNegative) return "both";
    if (hasPositive) return true;
    if (hasNegative) return false;

    return "both";
  };

  const status = checkValueStatus(dataa);

  const calculateOffset = (data: { value: number }[]) => {
    const values = data.map(d => d.value);
    const minValue = Math.min(...values);
    const maxValue = Math.max(...values);

    if (minValue >= 0) return "0%";
    if (maxValue <= 0) return "100%";

    return `${(maxValue / (maxValue - minValue)) * 100}%`;
  };

  const zeroOffset = calculateOffset(dataa);

  return (
    <div className="w-full h-[200px]">
      {status === "both" ? (
        <ResponsiveContainer width="100%" height={200}>
          <AreaChart data={dataa} margin={{ top: 20, right: 20, left: 0, bottom: 0 }}>
            <defs>
              <linearGradient id="strictGradient" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor="rgb(96, 187, 165)" stopOpacity={1} />
                <stop offset={zeroOffset} stopColor="rgba(96, 187, 164, 0.04)" stopOpacity={1} />
                <stop offset={zeroOffset} stopColor="rgba(179, 22, 22, 0.08)" stopOpacity={1} />
                <stop offset="100%" stopColor="rgb(239, 92, 92)" stopOpacity={0.7} />
              </linearGradient>
            </defs>

            <CartesianGrid stroke="rgb(80, 80, 80)" strokeDasharray="3 3" vertical={false} />
            <XAxis 
              dataKey="time" 
              stroke="rgba(255, 255, 255, 0.51)" 
              tick={{ fill: "rgba(255, 255, 255, 0.51)" }} 
            />
            <YAxis
              stroke="rgba(255, 255, 255, 0.51)"
              tick={{ fill: "rgba(255, 255, 255, 0.51)" }}
              tickFormatter={(value) => formatCompactCurrency(value, currency, exchangeRate)}
              interval={0}
              minTickGap={2}
              tickCount={7}
            />

            <Tooltip contentStyle={{ backgroundColor: "#222", color: "white", border: "1px solid white" }} />

            <Area
              type="monotone"
              dataKey="value"
              stroke="white"
              fill="url(#strictGradient)"
              fillOpacity={1}
              isAnimationActive={false}
            />
          </AreaChart>
        </ResponsiveContainer>
      ) : status === true ? (
        <ResponsiveContainer width="100%" height={200}>
          <AreaChart data={dataa} margin={{ top: 20, right: 20, left: 0, bottom: 0 }}>
            <defs>
              <linearGradient id="positiveGradient" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor="rgb(96, 187, 165)" stopOpacity={1} />
                <stop offset="100%" stopColor="rgba(96, 187, 164, 0.04)" stopOpacity={1} />
              </linearGradient>
            </defs>

            <CartesianGrid stroke="rgb(80, 80, 80)" strokeDasharray="3 3" vertical={false} />
            <XAxis 
              dataKey="time" 
              stroke="rgba(255, 255, 255, 0.51)" 
              tick={{ fill: "rgba(255, 255, 255, 0.51)" }} 
            />
            <YAxis
              stroke="rgba(255, 255, 255, 0.51)"
              tick={{ fill: "rgba(255, 255, 255, 0.51)" }}
              tickFormatter={(value) => formatCompactCurrency(value, currency, exchangeRate)}
              interval={0}
              minTickGap={2}
              tickCount={10}
            />

            <Tooltip contentStyle={{ backgroundColor: "#222", color: "white", border: "1px solid white" }} />

            <Area
              type="monotone"
              dataKey="value"
              stroke="white"
              fill="url(#positiveGradient)"
              fillOpacity={1}
              isAnimationActive={false}
            />
          </AreaChart>
        </ResponsiveContainer>
      ) : status === false ? (
        <ResponsiveContainer width="100%" height={200}>
          <AreaChart data={dataa} margin={{ top: 20, right: 20, left: 0, bottom: 0 }}>
            <defs>
              <linearGradient id="negativeGradient" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor="rgba(239, 92, 92, 0.35)" stopOpacity={1} />
                <stop offset="100%" stopColor="rgba(179, 22, 22, 0.7)" stopOpacity={1} />
              </linearGradient>
            </defs>

            <CartesianGrid stroke="rgb(80, 80, 80)" strokeDasharray="3 3" vertical={false} />
            <XAxis 
              dataKey="time" 
              stroke="rgba(255, 255, 255, 0.51)" 
              tick={{ fill: "rgba(255, 255, 255, 0.51)" }} 
            />
            <YAxis
              stroke="rgba(255, 255, 255, 0.51)"
              tick={{ fill: "rgba(255, 255, 255, 0.51)" }}
              tickFormatter={(value) => formatCompactCurrency(value, currency, exchangeRate)}
              interval={0}
              minTickGap={2}
              tickCount={10}
            />

            <Tooltip contentStyle={{ backgroundColor: "#222", color: "white", border: "1px solid white" }} />

            <Area
              type="monotone"
              dataKey="value"
              stroke="white"
              fill="url(#negativeGradient)"
              fillOpacity={1}
              isAnimationActive={false}
            />
          </AreaChart>
        </ResponsiveContainer>
      ) : null}
    </div>
  );
};

export default GradientAreaChart;

src/components/settings/GlobalSettings.t.content:
"use client";
import { useState } from "react";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faClock, faWallet, faCheck, faChevronDown, faMoon, faSun } from "@fortawesome/free-solid-svg-icons";

const GlobalSettings = () => {
  const [timezone, setTimezone] = useState("(GMT+05:30) Asia/Calcutta");
  const [currency, setCurrency] = useState("USD ($)");
  const [tzOpen, setTzOpen] = useState(false);
  const [currOpen, setCurrOpen] = useState(false);
  const [theme, setTheme] = useState<"dark" | "light">("dark");
  const [notifications, setNotifications] = useState({ email: true, push: false });

  const timezones = ["(GMT+05:30) Asia/Calcutta", "(GMT-04:00) America/New_York", "(GMT+00:00) Europe/London", "(GMT+08:00) Asia/Singapore"];
  const currencies = ["USD ($)", "INR (₹)", "EUR (€)", "GBP (£)"];

  const handleSave = () => {
    if (theme === "dark") {
      document.documentElement.classList.add("dark");
    } else {
      document.documentElement.classList.remove("dark");
    }
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h2 className="text-lg font-semibold text-gray-900 dark:text-white">Global Settings</h2>
        <button 
          onClick={handleSave}
          className="flex items-center gap-2 px-3 py-1.5 bg-emerald-500 hover:bg-emerald-600 text-white text-sm font-medium rounded-lg transition-colors"
        >
          <FontAwesomeIcon icon={faCheck} className="text-xs" />
          Save
        </button>
      </div>

      <div className="bg-white dark:bg-[#141414] rounded-xl border border-gray-200 dark:border-[#262626] divide-y divide-gray-100 dark:divide-[#262626]">
        <Dropdown
          icon={faClock}
          label="Timezone"
          value={timezone}
          options={timezones}
          isOpen={tzOpen}
          onToggle={() => { setTzOpen(!tzOpen); setCurrOpen(false); }}
          onSelect={(v) => { setTimezone(v); setTzOpen(false); }}
        />
        <Dropdown
          icon={faWallet}
          label="Currency"
          value={currency}
          options={currencies}
          isOpen={currOpen}
          onToggle={() => { setCurrOpen(!currOpen); setTzOpen(false); }}
          onSelect={(v) => { setCurrency(v); setCurrOpen(false); }}
        />
      </div>

      <div className="bg-white dark:bg-[#141414] rounded-xl border border-gray-200 dark:border-[#262626] p-4">
        <p className="text-sm font-medium text-gray-900 dark:text-white mb-3">Theme</p>
        <div className="flex gap-2">
          <button
            onClick={() => setTheme("light")}
            className={`flex-1 flex items-center justify-center gap-2 py-2 rounded-lg text-sm font-medium transition-colors ${
              theme === "light" 
                ? "bg-emerald-500/10 text-emerald-500 border border-emerald-500/30" 
                : "bg-gray-50 dark:bg-[#1a1a1a] text-gray-600 dark:text-gray-400"
            }`}
          >
            <FontAwesomeIcon icon={faSun} className="text-xs" />
            Light
          </button>
          <button
            onClick={() => setTheme("dark")}
            className={`flex-1 flex items-center justify-center gap-2 py-2 rounded-lg text-sm font-medium transition-colors ${
              theme === "dark" 
                ? "bg-emerald-500/10 text-emerald-500 border border-emerald-500/30" 
                : "bg-gray-50 dark:bg-[#1a1a1a] text-gray-600 dark:text-gray-400"
            }`}
          >
            <FontAwesomeIcon icon={faMoon} className="text-xs" />
            Dark
          </button>
        </div>
      </div>

      <div className="bg-white dark:bg-[#141414] rounded-xl border border-gray-200 dark:border-[#262626] divide-y divide-gray-100 dark:divide-[#262626]">
        <Toggle 
          label="Email notifications" 
          enabled={notifications.email} 
          onToggle={() => setNotifications({ ...notifications, email: !notifications.email })} 
        />
        <Toggle 
          label="Push notifications" 
          enabled={notifications.push} 
          onToggle={() => setNotifications({ ...notifications, push: !notifications.push })} 
        />
      </div>
    </div>
  );
};

const Dropdown = ({ icon, label, value, options, isOpen, onToggle, onSelect }: {
  icon: any;
  label: string;
  value: string;
  options: string[];
  isOpen: boolean;
  onToggle: () => void;
  onSelect: (v: string) => void;
}) => (
  <div className="relative p-4">
    <div className="flex items-center gap-3 mb-2">
      <FontAwesomeIcon icon={icon} className="text-gray-400 text-sm" />
      <span className="text-sm text-gray-500">{label}</span>
    </div>
    <button 
      onClick={onToggle}
      className="w-full flex items-center justify-between px-3 py-2 bg-gray-50 dark:bg-[#1a1a1a] rounded-lg text-sm text-gray-900 dark:text-white"
    >
      <span className="truncate">{value}</span>
      <FontAwesomeIcon icon={faChevronDown} className={`text-gray-400 text-xs transition-transform ${isOpen ? "rotate-180" : ""}`} />
    </button>
    {isOpen && (
      <div className="absolute left-4 right-4 top-full mt-1 bg-white dark:bg-[#1a1a1a] border border-gray-200 dark:border-[#262626] rounded-lg shadow-lg overflow-hidden z-10 max-h-48 overflow-y-auto">
        {options.map((opt) => (
          <button
            key={opt}
            onClick={() => onSelect(opt)}
            className={`w-full px-3 py-2 text-left text-sm transition-colors ${
              value === opt 
                ? "bg-emerald-500/10 text-emerald-500" 
                : "text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-[#252525]"
            }`}
          >
            {opt}
          </button>
        ))}
      </div>
    )}
  </div>
);

const Toggle = ({ label, enabled, onToggle }: { label: string; enabled: boolean; onToggle: () => void }) => (
  <div className="flex items-center justify-between px-4 py-3">
    <span className="text-sm text-gray-700 dark:text-gray-300">{label}</span>
    <button
      onClick={onToggle}
      className={`w-10 h-6 rounded-full transition-colors relative ${
        enabled ? "bg-emerald-500" : "bg-gray-300 dark:bg-[#262626]"
      }`}
    >
      <div className={`absolute top-1 w-4 h-4 rounded-full bg-white transition-transform ${
        enabled ? "right-1" : "left-1"
      }`} />
    </button>
  </div>
);

export default GlobalSettings;

