import { NextRequest, NextResponse } from 'next/server';
import { cookies } from 'next/headers';

// Import PUT handler functions
import { 
    updateStrategyHandler,
    updateStrategyNameHandler,
    setDefaultStrategyHandler
} from '../../../../lib/api-handlers/strategiesHandlers';

export async function PUT(req: NextRequest) {
    try {
        const cookieStore = await cookies();
        const token = cookieStore.get('authToken')?.value;
        const userId = cookieStore.get('userId')?.value;

        if (!token || !userId) {
            return NextResponse.json({ error: "Authentication required" }, { status: 401 });
        }

        const body = await req.json();
        const { apiName } = body;

        if (!apiName) {
            return NextResponse.json({ error: "API name is required" }, { status: 400 });
        }

        switch (apiName) {
            case "updateStrategy":
                return await updateStrategyHandler(body, userId, token);

            case "updateStrategyName":
                return await updateStrategyNameHandler(body, userId, token);

            case "setDefaultStrategy":
                return await setDefaultStrategyHandler(body, userId, token);

            default:
                return NextResponse.json({ error: "API endpoint not found" }, { status: 404 });
        }

    } catch (error) {
        console.error("PUT route error:", error);
        return NextResponse.json({ error: "Internal server error" }, { status: 500 });
    }
}

src/components/dashboard-components/dasb.content:
'use client';

import React, { useMemo, useState, useRef, useEffect } from "react";
import { AnimatePresence, motion } from "framer-motion";
import { Calendar, ChevronLeft, ChevronRight, ArrowRightLeft, TrendingUp, TrendingDown, Target, Flame, BarChart3 } from "lucide-react";
import { cn } from "@/lib/utils";

import DashWidgets from "../dashboard-widgets/DashboardWidget";
import PnLDailyChart from "./Graphs/PnLDailyChart";
import TradesWidget from "../TradesWidget";

import { useModeFilteredAccounts } from '@/hooks/useModeFilteredAccounts';
import useCurrencyStore, { formatCompactCurrency } from "@/store/currencyStore";
import { calculateProfitFactor, calculateRiskRewardRatio, calculateBalance } from '@/utils/dashboard-calculations/dashboardCalculations';

interface TradeData {
  date: string;
  Profit: number;
  time?: string;
  Item?: string;
  Type?: string;
  [key: string]: unknown;
}

interface Account {
  tradeData?: TradeData[];
}

interface ProcessedData {
  time: string;
  value: number;
}

const DashboardCustom: React.FC = () => {
  const { selectedAccounts } = useModeFilteredAccounts();
  const { currency, exchangeRate } = useCurrencyStore();

  const [showCalendar, setShowCalendar] = useState<boolean>(false);
  const [startDate, setStartDate] = useState<Date | null>(null);
  const [endDate, setEndDate] = useState<Date | null>(null);
  const [tempStart, setTempStart] = useState<Date | null>(null);
  const [tempEnd, setTempEnd] = useState<Date | null>(null);
  const [hoverDate, setHoverDate] = useState<Date | null>(null);
  const [leftYear, setLeftYear] = useState<number>(new Date().getFullYear());
  const [leftMonth, setLeftMonth] = useState<number>(new Date().getMonth() - 1 < 0 ? 11 : new Date().getMonth() - 1);
  const [rightYear, setRightYear] = useState<number>(new Date().getFullYear());
  const [rightMonth, setRightMonth] = useState<number>(new Date().getMonth());

  const calendarRef = useRef<HTMLDivElement>(null);
  const today = new Date();
  today.setHours(23, 59, 59, 999);

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (calendarRef.current && !calendarRef.current.contains(e.target as Node)) {
        setShowCalendar(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const allTrades = useMemo(() => {
    const trades = (selectedAccounts as Account[]).flatMap(account => account.tradeData || []);
    return trades.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  }, [selectedAccounts]);

  const displayTrades = useMemo(() => {
    if (!startDate || !endDate) return allTrades;
    const start = new Date(startDate);
    start.setHours(0, 0, 0, 0);
    const end = new Date(endDate);
    end.setHours(23, 59, 59, 999);
    return allTrades.filter(trade => {
      const tradeDate = new Date(trade.date);
      return tradeDate >= start && tradeDate <= end;
    });
  }, [startDate, endDate, allTrades]);

  const processedData = useMemo(() => {
    let cumulativeProfit = 0;
    const profitByDate: { [key: string]: number } = {};
    displayTrades.forEach(trade => {
      profitByDate[trade.date] = (profitByDate[trade.date] || 0) + (trade.Profit || 0);
    });
    const result: ProcessedData[] = [{ time: "", value: 0 }];
    Object.entries(profitByDate)
      .sort(([a], [b]) => new Date(a).getTime() - new Date(b).getTime())
      .forEach(([date, profit]) => {
        cumulativeProfit += profit;
        result.push({ time: date, value: parseFloat(cumulativeProfit.toFixed(2)) });
      });
    return result;
  }, [displayTrades]);

  const totalPnL = displayTrades.reduce((sum, t) => sum + (t.Profit || 0), 0);
  const winCount = displayTrades.filter(t => t.Profit > 0).length;
  const lossCount = displayTrades.filter(t => t.Profit < 0).length;
  const winrate = displayTrades.length > 0 ? (winCount / displayTrades.length) * 100 : 0;
  const metrics = calculateRiskRewardRatio(displayTrades);

  const bestTrade = displayTrades.length > 0 ? Math.max(...displayTrades.map(t => t.Profit)) : 0;
  const worstTrade = displayTrades.length > 0 ? Math.min(...displayTrades.map(t => t.Profit)) : 0;

  const tradingDays = useMemo(() => {
    const uniqueDates = new Set(displayTrades.map(t => t.date));
    return uniqueDates.size;
  }, [displayTrades]);

  const monthNames = ["January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December"];

  const generateCalendarDays = (year: number, month: number): (number | null)[] => {
    const firstDay = new Date(year, month, 1).getDay();
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const days: (number | null)[] = Array(firstDay).fill(null);
    for (let i = 1; i <= daysInMonth; i++) {
      days.push(i);
    }
    return days;
  };

  const handleDateClick = (day: number, month: number, year: number) => {
    const clickedDate = new Date(year, month, day);
    if (clickedDate > today) return;

    if (!tempStart || (tempStart && tempEnd)) {
      setTempStart(clickedDate);
      setTempEnd(null);
      setHoverDate(null);
    } else if (tempStart && !tempEnd) {
      if (clickedDate < tempStart) {
        setTempEnd(tempStart);
        setTempStart(clickedDate);
      } else {
        setTempEnd(clickedDate);
      }
    }
  };

  const isInRange = (day: number, month: number, year: number): boolean => {
    if (!tempStart) return false;
    const date = new Date(year, month, day);
    if (tempEnd) {
      return date > tempStart && date < tempEnd;
    }
    if (hoverDate && hoverDate > tempStart) {
      return date > tempStart && date <= hoverDate;
    }
    return false;
  };

  const isSelectedDate = (day: number, month: number, year: number): boolean => {
    const date = new Date(year, month, day);
    return (tempStart && date.getTime() === tempStart.getTime()) ||
           (tempEnd && date.getTime() === tempEnd.getTime()) || false;
  };

  const handleApply = () => {
    if (tempStart && tempEnd) {
      setStartDate(tempStart);
      setEndDate(tempEnd);
      setShowCalendar(false);
    }
  };

  const handleClear = () => {
    setTempStart(null);
    setTempEnd(null);
    setStartDate(null);
    setEndDate(null);
    setShowCalendar(false);
  };

  const handlePrevMonth = (side: 'left' | 'right') => {
    if (side === 'left') {
      if (leftMonth === 0) {
        setLeftMonth(11);
        setLeftYear(y => y - 1);
      } else {
        setLeftMonth(m => m - 1);
      }
    } else {
      if (rightMonth === 0) {
        setRightMonth(11);
        setRightYear(y => y - 1);
      } else {
        setRightMonth(m => m - 1);
      }
    }
  };

  const handleNextMonth = (side: 'left' | 'right') => {
    if (side === 'left') {
      if (leftMonth === 11) {
        setLeftMonth(0);
        setLeftYear(y => y + 1);
      } else {
        setLeftMonth(m => m + 1);
      }
    } else {
      if (rightMonth === 11) {
        setRightMonth(0);
        setRightYear(y => y + 1);
      } else {
        setRightMonth(m => m + 1);
      }
    }
  };

  const formatDateDisplay = (date: Date | null): string => {
    if (!date) return "Select";
    return date.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
  };

  const renderCalendarGrid = (year: number, month: number) => {
    const days = generateCalendarDays(year, month);
    return (
      <>
        <div className="grid grid-cols-7 gap-0.5 mb-1">
          {["S", "M", "T", "W", "T", "F", "S"].map((d, i) => (
            <div key={i} className="h-6 flex items-center justify-center text-[10px] font-medium text-muted-foreground">
              {d}
            </div>
          ))}
        </div>
        <div className="grid grid-cols-7 gap-0.5">
          {days.map((day, i) => {
            if (day === null) {
              return <div key={`empty-${i}`} className="h-7" />;
            }
            const dateObj = new Date(year, month, day);
            const isFuture = dateObj > today;
            const isRangeStart = tempStart && dateObj.getTime() === tempStart.getTime();
            const isRangeEnd = tempEnd && dateObj.getTime() === tempEnd.getTime();
            const inRange = isInRange(day, month, year);

            return (
              <button
                key={day}
                disabled={isFuture}
                onClick={() => handleDateClick(day, month, year)}
                onMouseEnter={() => {
                  if (tempStart && !tempEnd) {
                    setHoverDate(new Date(year, month, day));
                  }
                }}
                className={cn(
                  "h-7 w-7 rounded text-xs font-medium flex items-center justify-center transition-all",
                  isFuture && "text-muted-foreground/40 cursor-not-allowed",
                  !isFuture && !isRangeStart && !isRangeEnd && !inRange && "hover:bg-muted text-foreground",
                  isRangeStart && "bg-primary text-primary-foreground rounded-l-lg",
                  isRangeEnd && "bg-primary text-primary-foreground rounded-r-lg",
                  inRange && "bg-primary/20 text-foreground"
                )}
              >
                {day}
              </button>
            );
          })}
        </div>
      </>
    );
  };

  const dashWidgetProps = {
    data: processedData,
    pnl: parseFloat(totalPnL.toFixed(2)),
    winrate: parseFloat(winrate.toFixed(2)),
    winners: winCount,
    losers: lossCount,
    profitF: calculateProfitFactor(displayTrades),
    avgProfits: parseFloat(metrics.avgWin),
    avgLoses: parseFloat(metrics.avgLoss),
    rrRatio: metrics.rrRatio,
    accBal: parseFloat(calculateBalance(selectedAccounts).toFixed(2)),
    totalProfits: displayTrades.reduce((sum, trade) => trade.Profit > 0 ? sum + trade.Profit : sum, 0),
    totalLoses: displayTrades.reduce((sum, trade) => trade.Profit < 0 ? sum + trade.Profit : sum, 0),
  };

  return (
    <div className="space-y-4">
      <DashWidgets {...dashWidgetProps} />

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-4">
        {/* Left Column */}
        <div className="xl:col-span-2 space-y-4">
          {/* Date Range Picker Header */}
          <div className="bg-card/50 backdrop-blur-sm border border-border/50 rounded-2xl p-4 overflow-visible relative z-20">
            <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center">
                  <Calendar className="w-5 h-5 text-primary" />
                </div>
                <div>
                  <h2 className="text-base font-semibold text-foreground">Custom Date Range</h2>
                  <p className="text-sm text-muted-foreground">
                    {startDate && endDate
                      ? `${formatDateDisplay(startDate)} - ${formatDateDisplay(endDate)}`
                      : "Select a date range to analyze"}
                  </p>
                </div>
              </div>

              <div className="relative" ref={calendarRef}>
                <button
                  onClick={() => setShowCalendar(!showCalendar)}
                  className="flex items-center gap-2 px-3 py-2 rounded-lg bg-muted/50 hover:bg-muted border border-border transition-colors text-sm"
                >
                  <span className="font-medium text-foreground">
                    {formatDateDisplay(startDate)}
                  </span>
                  <ArrowRightLeft className="w-3.5 h-3.5 text-muted-foreground" />
                  <span className="font-medium text-foreground">
                    {formatDateDisplay(endDate)}
                  </span>
                </button>

                <AnimatePresence>
                  {showCalendar && (
                    <motion.div
                      initial={{ opacity: 0, y: 8 }}
                      animate={{ opacity: 1, y: 0 }}
                      exit={{ opacity: 0, y: 8 }}
                      className="fixed sm:absolute left-1/2 sm:left-auto sm:right-0 top-1/2 sm:top-full -translate-x-1/2 sm:translate-x-0 -translate-y-1/2 sm:translate-y-0 sm:mt-2 z-50 bg-card border border-border rounded-xl p-4 shadow-xl max-w-[calc(100vw-2rem)] max-h-[calc(100vh-2rem)] overflow-auto"
                    >
                      <div className="flex flex-col sm:flex-row gap-4">
                        {/* Left Calendar */}
                        <div className="min-w-[200px] sm:min-w-[220px]">
                          <div className="flex items-center justify-between mb-3">
                            <button
                              onClick={() => handlePrevMonth('left')}
                              className="p-1 rounded hover:bg-muted transition-colors"
                            >
                              <ChevronLeft className="w-4 h-4 text-muted-foreground" />
                            </button>
                            <span className="text-xs font-semibold text-foreground">
                              {monthNames[leftMonth]} {leftYear}
                            </span>
                            <button
                              onClick={() => handleNextMonth('left')}
                              className="p-1 rounded hover:bg-muted transition-colors"
                            >
                              <ChevronRight className="w-4 h-4 text-muted-foreground" />
                            </button>
                          </div>
                          {renderCalendarGrid(leftYear, leftMonth)}
                        </div>

                        <div className="hidden sm:block w-px bg-border" />

                        {/* Right Calendar */}
                        <div className="min-w-[200px] sm:min-w-[220px]">
                          <div className="flex items-center justify-between mb-3">
                            <button
                              onClick={() => handlePrevMonth('right')}
                              className="p-1 rounded hover:bg-muted transition-colors"
                            >
                              <ChevronLeft className="w-4 h-4 text-muted-foreground" />
                            </button>
                            <span className="text-xs font-semibold text-foreground">
                              {monthNames[rightMonth]} {rightYear}
                            </span>
                            <button
                              onClick={() => handleNextMonth('right')}
                              className="p-1 rounded hover:bg-muted transition-colors"
                            >
                              <ChevronRight className="w-4 h-4 text-muted-foreground" />
                            </button>
                          </div>
                          {renderCalendarGrid(rightYear, rightMonth)}
                        </div>
                      </div>

                      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between mt-4 pt-3 border-t border-border gap-3">
                        <div className="flex items-center gap-2 text-xs text-muted-foreground">
                          <span className="px-2 py-1 rounded bg-muted text-foreground font-medium">
                            {formatDateDisplay(tempStart)}
                          </span>
                          <span>to</span>
                          <span className="px-2 py-1 rounded bg-muted text-foreground font-medium">
                            {formatDateDisplay(tempEnd)}
                          </span>
                        </div>
                        <div className="flex items-center gap-2">
                          <button
                            onClick={handleClear}
                            className="px-3 py-1.5 text-xs font-medium text-muted-foreground hover:text-foreground transition-colors"
                          >
                            Clear
                          </button>
                          <button
                            onClick={handleApply}
                            disabled={!tempStart || !tempEnd}
                            className="px-3 py-1.5 rounded-lg bg-primary text-primary-foreground text-xs font-medium disabled:opacity-50 disabled:cursor-not-allowed"
                          >
                            Apply
                          </button>
                        </div>
                      </div>
                    </motion.div>
                  )}
                </AnimatePresence>
              </div>
            </div>
          </div>

          {/* Cumulative P&L Chart */}
          <PnLDailyChart data={processedData} />

          {/* Insight Tiles - Responsive Grid */}
          <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-2">
            <div className="bg-card/50 backdrop-blur-sm border border-border/50 rounded-xl p-3">
              <div className="flex items-center gap-2 mb-1">
                <div className="p-1 rounded-lg bg-profit/10">
                  <TrendingUp className="w-3 h-3 text-profit" />
                </div>
                <span className="text-[10px] text-muted-foreground font-medium">Avg Win</span>
              </div>
              <p className="text-sm font-bold text-profit">
                {formatCompactCurrency(parseFloat(metrics.avgWin) || 0, currency, exchangeRate)}
              </p>
            </div>

            <div className="bg-card/50 backdrop-blur-sm border border-border/50 rounded-xl p-3">
              <div className="flex items-center gap-2 mb-1">
                <div className="p-1 rounded-lg bg-loss/10">
                  <TrendingDown className="w-3 h-3 text-loss" />
                </div>
                <span className="text-[10px] text-muted-foreground font-medium">Avg Loss</span>
              </div>
              <p className="text-sm font-bold text-loss">
                {formatCompactCurrency(Math.abs(parseFloat(metrics.avgLoss)) || 0, currency, exchangeRate)}
              </p>
            </div>

            <div className="bg-card/50 backdrop-blur-sm border border-border/50 rounded-xl p-3">
              <div className="flex items-center gap-2 mb-1">
                <div className="p-1 rounded-lg bg-profit/10">
                  <Target className="w-3 h-3 text-profit" />
                </div>
                <span className="text-[10px] text-muted-foreground font-medium">Best</span>
              </div>
              <p className={cn("text-sm font-bold", bestTrade >= 0 ? "text-profit" : "text-loss")}>
                {formatCompactCurrency(bestTrade, currency, exchangeRate)}
              </p>
            </div>

            <div className="bg-card/50 backdrop-blur-sm border border-border/50 rounded-xl p-3">
              <div className="flex items-center gap-2 mb-1">
                <div className="p-1 rounded-lg bg-loss/10">
                  <Target className="w-3 h-3 text-loss" />
                </div>
                <span className="text-[10px] text-muted-foreground font-medium">Worst</span>
              </div>
              <p className={cn("text-sm font-bold", worstTrade >= 0 ? "text-profit" : "text-loss")}>
                {formatCompactCurrency(worstTrade, currency, exchangeRate)}
              </p>
            </div>

            <div className="bg-card/50 backdrop-blur-sm border border-border/50 rounded-xl p-3">
              <div className="flex items-center gap-2 mb-1">
                <div className="p-1 rounded-lg bg-primary/10">
                  <BarChart3 className="w-3 h-3 text-primary" />
                </div>
                <span className="text-[10px] text-muted-foreground font-medium">Days</span>
              </div>
              <p className="text-sm font-bold text-foreground">
                {tradingDays}
              </p>
            </div>

            <div className="bg-card/50 backdrop-blur-sm border border-border/50 rounded-xl p-3">
              <div className="flex items-center gap-2 mb-1">
                <div className={cn("p-1 rounded-lg", totalPnL >= 0 ? "bg-profit/10" : "bg-loss/10")}>
                  <Flame className={cn("w-3 h-3", totalPnL >= 0 ? "text-profit" : "text-loss")} />
                </div>
                <span className="text-[10px] text-muted-foreground font-medium">Trades</span>
              </div>
              <p className="text-sm font-bold text-foreground">
                {displayTrades.length}
              </p>
            </div>
          </div>
        </div>

        {/* Right Sidebar */}
        <div className="xl:col-span-1 flex flex-col gap-4">
          <TradesWidget data={displayTrades} />
        </div>
      </div>
    </div>
  );
};

export default DashboardCustom;

src/components/daily-journal/JRContent.t.content:
"use client";
import { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import Cookies from "js-cookie";
import html2canvas from "html2canvas";
import Image from "next/image";
import { 
  ChevronDown, 
  Share2, 
  Upload, 
  FileText,
  Save,
  ChevronLeft,
  ChevronRight,
  Check,
  Clock,
  Plus,
  Target,
  Search,
  Trash2,
  X,
  TrendingUp,
  TrendingDown,
  Zap,
  Eye,
  ImageIcon,
  ListChecks,
  Square,
  CheckSquare
} from "lucide-react";

import useAccountDetails from "@/store/accountdetails";
import { useDataStore } from "@/store/store";
import notebookStore from "@/store/notebookStore";
import notifications from "@/store/notifications";
import useCurrencyStore, { formatCurrencyValue } from "@/store/currencyStore";
import ShareTradeModal from "@/components/shared/ShareTradeModal";

interface Trade {
  id: string;
  date: string;
  Profit: number;
  noteName?: string;
  Item: string;
  time: string;
  accountType: string;
  strategy: string;
  Quality: Record<string, boolean>;
  beforeURL?: string;
  afterURL?: string;
  OpenTime: string;
  Type: string;
  Size: string;
  Commission?: string;
  rfe: string;
  btm: string;
  dtm: string;
  atm: string;
  jrData?: any;
}

interface JRContentProps {
  dailyData: any[];
}

const JRContent = ({ dailyData }: JRContentProps) => {
  const { currency, exchangeRate } = useCurrencyStore();
  const userId = Cookies.get("userId") || "";
  const tokenn = Cookies.get("Trace Your Trades") || "";

  const { setAccounts, profileData } = useAccountDetails();
  const { setCurrentUrl } = useDataStore();
  const { setFolder, setFile, setNotes } = notebookStore();
  const { setAlertBoxG } = notifications();

  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [activeDropdown, setActiveDropdown] = useState<string | null>(null);
  const [jrData, setJrData] = useState({ rfe: "", widw: "", wni: "", lfnt: "" });
  const [savingId, setSavingId] = useState<string | null>(null);
  const [strategySearch, setStrategySearch] = useState("");
  const [creatingStrategy, setCreatingStrategy] = useState(false);
  const [screenshotModal, setScreenshotModal] = useState<{
    isOpen: boolean;
    url: string;
    type: "before" | "after";
    tradeId: string;
    accountType: string;
    tradeName: string;
  } | null>(null);

  const [strategyRules, setStrategyRules] = useState<{id: string; text: string}[]>([]);
  const [rulesCompliance, setRulesCompliance] = useState<Record<string, boolean>>({});
  const [loadingRules, setLoadingRules] = useState(false);
  const [shareModal, setShareModal] = useState<{
    isOpen: boolean;
    tradeId: string;
    accountId: string;
    tradeSummary: { symbol?: string; pnl?: number; date?: string };
  } | null>(null);

  const itemsPerPage = 5;
  const totalPages = Math.ceil((dailyData?.length || 0) / itemsPerPage);
  const currentItems = dailyData?.slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage) || [];

  const existingStrategies: string[] = (profileData?.otherData?.strategy || []).filter((s: string) => s && s !== "Select");

  useEffect(() => {
    setAccounts();
  }, [setAccounts]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape" && screenshotModal) {
        closeScreenshotModal();
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [screenshotModal]);

  const updateTradeStrategy = async (tradeId: string, strategy: string, accountType: string) => {
    try {
      const res = await fetch(`/api/daily-journal/post`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ 
          id: tradeId, 
          type: "strategy", 
          value: strategy, 
          tokenn, 
          accountType, 
          apiName: "editDropdowns" 
        }),
      });
      if (res.ok) {
        setActiveDropdown(null);
        setAccounts();
        setAlertBoxG(`Strategy set to "${strategy}"`, "success");
      }
    } catch (error) {
      console.error(error);
      setAlertBoxG("Failed to update strategy", "error");
    }
  };

  const createAndApplyStrategy = async (tradeId: string, strategyName: string, accountType: string) => {
    if (!strategyName.trim()) return;

    setCreatingStrategy(true);
    try {
      const res = await fetch(`/api/strategy/post`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ 
          strategy: strategyName.trim(),
          tokenn,
          apiName: "addStrategy" 
        }),
      });

      const data = await res.json();

      if (res.ok) {
        await updateTradeStrategy(tradeId, strategyName.trim(), accountType);
        setStrategySearch("");
        setAlertBoxG(`Strategy "${strategyName}" created!`, "success");
      } else if (res.status === 409) {
        await updateTradeStrategy(tradeId, strategyName.trim(), accountType);
      } else {
        setAlertBoxG(data.error || "Failed to create strategy", "error");
      }
    } catch (error) {
      console.error(error);
      setAlertBoxG("Failed to create strategy", "error");
    } finally {
      setCreatingStrategy(false);
    }
  };

  const fetchStrategyRules = async (strategyName: string, existingCompliance?: Record<string, boolean>) => {
    if (!strategyName || strategyName === "Select") {
      setStrategyRules([]);
      setRulesCompliance({});
      return;
    }

    setLoadingRules(true);
    try {
      const res = await fetch(`/api/strategy/get?apiName=getStrategyRules&strategyName=${encodeURIComponent(strategyName)}`);
      if (res.ok) {
        const data = await res.json();
        setStrategyRules(data.rules || []);
        if (existingCompliance && Object.keys(existingCompliance).length > 0) {
          setRulesCompliance(existingCompliance);
        } else {
          const initialCompliance: Record<string, boolean> = {};
          (data.rules || []).forEach((rule: {id: string}) => {
            initialCompliance[rule.id] = false;
          });
          setRulesCompliance(initialCompliance);
        }
      }
    } catch (error) {
      console.error("Error fetching strategy rules:", error);
    } finally {
      setLoadingRules(false);
    }
  };

  const toggleRuleCompliance = (ruleId: string) => {
    setRulesCompliance(prev => ({
      ...prev,
      [ruleId]: !prev[ruleId]
    }));
  };

  const toggleExpand = (id: string, trade: Trade) => {
    if (expandedId === id) {
      setExpandedId(null);
      setStrategyRules([]);
      setRulesCompliance({});
    } else {
      setExpandedId(id);
      setJrData(trade.jrData || { rfe: "", widw: "", wni: "", lfnt: "" });
      if (trade.strategy && trade.strategy !== "Select") {
        fetchStrategyRules(trade.strategy, trade.jrData?.rulesCompliance);
      } else {
        setStrategyRules([]);
        setRulesCompliance({});
      }
    }
    setActiveDropdown(null);
  };

  const compressAndUploadImage = (file: File, id: string, imgType: string, accountType: string) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new window.Image();
      img.onload = () => {
        const canvas = document.createElement("canvas");
        const ctx = canvas.getContext("2d");
        let width = img.width;
        let height = img.height;
        const maxSize = 1024;

        if (width > height) {
          height = Math.round(height * (maxSize / width));
          width = maxSize;
        } else {
          width = Math.round(width * (maxSize / height));
          height = maxSize;
        }

        canvas.width = width;
        canvas.height = height;
        ctx?.drawImage(img, 0, 0, width, height);

        let quality = 0.9;
        let dataUrl;
        while ((dataUrl = canvas.toDataURL("image/jpeg", quality)).length > 100 * 1024 && quality > 0.2) {
          quality -= 0.1;
        }

        fetch(dataUrl)
          .then((res) => res.blob())
          .then((blob) => {
            const formData = new FormData();
            formData.append("image", blob, file.name);
            formData.append("id", id);
            formData.append("imgType", imgType);
            formData.append("tokenn", tokenn);
            formData.append("accountType", accountType);
            formData.append("apiName", "uploadImage");

            fetch(`/api/daily-journal/post`, { method: "POST", body: formData })
              .then((response) => {
                if (response.ok) setAccounts();
              })
              .catch(console.error);
          });
      };
      img.src = e.target?.result as string;
    };
    reader.readAsDataURL(file);
  };

  const handleFileSelect = (file: File, id: string, imgType: string, accountType: string) => {
    if (!file?.type.startsWith("image/")) return;
    compressAndUploadImage(file, id, imgType, accountType);
  };

  const deleteScreenshot = async (id: string, imgType: string, accountType: string) => {
    try {
      const res = await fetch(`/api/daily-journal/post`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ 
          id, 
          type: imgType, 
          value: "", 
          tokenn, 
          accountType, 
          apiName: "editDropdowns" 
        }),
      });
      if (res.ok) {
        setAccounts();
        setScreenshotModal(null);
        setAlertBoxG("Screenshot deleted", "success");
      }
    } catch (error) {
      console.error(error);
      setAlertBoxG("Failed to delete screenshot", "error");
    }
  };

  const openScreenshotModal = (url: string, type: "before" | "after", tradeId: string, accountType: string, tradeName: string) => {
    setScreenshotModal({ isOpen: true, url, type, tradeId, accountType, tradeName });
  };

  const closeScreenshotModal = () => {
    setScreenshotModal(null);
  };

  const postDropOptions = async (id: string, value: string, type: string, accountType: string) => {
    try {
      const res = await fetch(`/api/daily-journal/post`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ id, type, value, tokenn, accountType, apiName: "editDropdowns" }),
      });
      if (res.ok) {
        setActiveDropdown(null);
        setAccounts();
      }
    } catch (error) {
      console.error(error);
    }
  };

  const postSelect = async (id: string, option: string, accountType: string) => {
    try {
      const res = await fetch(`/api/daily-journal/post`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ id, option, tokenn, accountType, apiName: "changeSelectQuality" }),
      });
      if (res.ok) {
        setActiveDropdown(null);
        setAccounts();
      }
    } catch (error) {
      console.error(error);
    }
  };

  const submitJrData = async (id: string, accountType: string) => {
    setSavingId(id);
    try {
      const jrDataWithRules = {
        ...jrData,
        rulesCompliance: strategyRules.length > 0 ? rulesCompliance : undefined
      };
      const res = await fetch(`/api/daily-journal/post`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ id, tokenn, jrData: jrDataWithRules, accountType, apiName: "uploadJournalData" }),
      });
      if (res.ok) {
        setExpandedId(null);
        setStrategyRules([]);
        setRulesCompliance({});
        setAccounts();
        setAlertBoxG("Journal saved!", "success");
      }
    } catch (error) {
      console.error(error);
    } finally {
      setSavingId(null);
    }
  };

  const addNotes = async (tradeId: string, symbol: string, time: string, date: string, accountType: string, pnl?: number) => {
    try {
      const res = await fetch(`/api/notebook/post`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ tradeId, tokenn, userId, symbol, time, date, accountType, pnl, apiName: "addNotesFromDailyJournal" }),
      });
      const data = await res.json();
      if (res.ok) {
        setAccounts();
        setNotes();
        setCurrentUrl("Notebook");
        setFolder("Daily Journal");
        setFile(data.data.finalFileName);
      }
    } catch (error) {
      console.error(error);
    }
  };

  const handleShare = (trade: Trade) => {
    setShareModal({
      isOpen: true,
      tradeId: trade.id,
      accountId: trade.accountType,
      tradeSummary: {
        symbol: trade.Item,
        pnl: trade.Profit,
        date: new Date(trade.date).toLocaleDateString("en-US", {
          month: "short",
          day: "numeric",
          year: "numeric"
        })
      }
    });
  };

  const getQualityLabel = (quality: Record<string, boolean>) => {
    if (quality?.high) return { label: "High", icon: "star", style: "bg-profit/15 text-profit border-profit/20" };
    if (quality?.medium) return { label: "Medium", icon: "zap", style: "bg-yellow-500/15 text-yellow-500 border-yellow-500/20" };
    if (quality?.low) return { label: "Low", icon: "down", style: "bg-loss/15 text-loss border-loss/20" };
    return { label: "Rate", icon: "none", style: "bg-muted/50 text-muted-foreground border-border" };
  };

  if (!dailyData?.length) {
    return (
      <div className="flex flex-col items-center justify-center py-24">
        <div className="w-20 h-20 rounded-2xl bg-gradient-to-br from-muted/50 to-muted/30 flex items-center justify-center mb-6">
          <FileText className="w-10 h-10 text-muted-foreground/60" />
        </div>
        <h3 className="text-xl font-semibold text-foreground mb-2">No trades yet</h3>
        <p className="text-sm text-muted-foreground text-center max-w-sm mb-6">
          Start adding trades to build your journal and track your progress
        </p>
