                  </button>
                </div>

                <p className="text-[10px] text-muted-foreground/60 text-center mt-6">
                  Press <kbd className="px-1.5 py-0.5 bg-muted/50 rounded text-[10px] font-mono">ESC</kbd> to close
                </p>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Share Trade Modal */}
      {shareModal && (
        <ShareTradeModal
          isOpen={shareModal.isOpen}
          onClose={() => setShareModal(null)}
          tradeId={shareModal.tradeId}
          accountId={shareModal.accountId}
          tradeSummary={shareModal.tradeSummary}
        />
      )}
    </div>
  );
};

