src/components/reports/sub-report/DayTim.content:
// DayTimeReportPage.tsx
import React, { useMemo } from 'react';

import CrossAnalysisTable from './CrossAnalysisTable';
import { useModeFilteredAccounts } from '@/hooks/useModeFilteredAccounts';
import { calculatePerformanceMetrics } from '@/utils/reports/calculatePerformanceMetrics';
import SummaryTable from './SummaryTable';
import ChartContainer from './ChartContainer';
import PerformanceCards from './PerformanceCards';

interface Trade {
  date: string;
  Symbol: string;
  Profit: number;
  Commission?: number;
  Swap?: number;
  [key:string]:any
  // Add other trade properties as needed
}

interface PerformanceMetrics {
  netPnL: number;
  winPercentage: number;
  avgDailyVolume: number;
  avgTradeWinLoss: number;
  [key:string]:any
  // Add other metrics as needed
}

interface DayMetrics {
  day: string;
  trades: Trade[];
  metrics: PerformanceMetrics;
  [key:string]:any
}

interface PerformanceData {
  bestDay: { day: string; trades: number; pnl: string };
  leastDay: { day: string; trades: number; pnl: string };
  mostActiveDay: { day: string; trades: number };
  bestWinRateDay: { day: string; winRate: string; tradeCount: number };
}

const DayTimeReportPage: React.FC = () => {
  const { selectedAccounts } = useModeFilteredAccounts();
  const trades = selectedAccounts.flatMap(acc => acc.tradeData || []);

  // Group trades by day of week
  const dayMetrics = useMemo((): DayMetrics[] => {
    const daysOfWeek = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
    const tradesByDay = trades?.reduce((acc: Record<string, Trade[]>, trade: Trade) => {
      const date = new Date(trade.date);
      const dayOfWeek = daysOfWeek[date.getDay()];
      if (!acc[dayOfWeek]) {
        acc[dayOfWeek] = [];
      }
      acc[dayOfWeek].push(trade);
      return acc;
    }, {});

    const metrics = Object.entries(tradesByDay || {}).map(([day, dayTrades]) => {
      const dayMetrics = calculatePerformanceMetrics(dayTrades);
      return {
        day,
        trades: dayTrades,
        metrics: dayMetrics
      };
    });

    return metrics;
  }, [trades]);

  // Calculate performance data
  const performanceData = useMemo((): PerformanceData => {
    if (dayMetrics.length === 0) return {
      bestDay: { day: '-', trades: 0, pnl: '$0' },
      leastDay: { day: '-', trades: 0, pnl: '$0' },
      mostActiveDay: { day: '-', trades: 0 },
      bestWinRateDay: { day: '-', winRate: '0', tradeCount: 0 }
    };

    const bestDay = dayMetrics.reduce((best, day) => 
      !best || day.metrics.netPnL > best.metrics.netPnL ? day : best);

    const leastDay = dayMetrics.reduce((worst, day) => 
      !worst || day.metrics.netPnL < worst.metrics.netPnL ? day : worst);

    const mostActiveDay = dayMetrics.reduce((most, day) => 
      !most || day.trades.length > most.trades.length ? day : most);

    const bestWinRateDay = dayMetrics.reduce((best, day) => 
      !best || day.metrics.winPercentage > best.metrics.winPercentage ? day : best);

    return {
      bestDay: { 
        day: bestDay.day, 
        trades: bestDay.trades.length, 
        pnl: `$${bestDay.metrics.netPnL.toFixed(2)}` 
      },
      leastDay: { 
        day: leastDay.day, 
        trades: leastDay.trades.length, 
        pnl: `-$${Math.abs(leastDay.metrics.netPnL).toFixed(2)}` 
      },
      mostActiveDay: { 
        day: mostActiveDay.day, 
        trades: mostActiveDay.trades.length 
      },
      bestWinRateDay: { 
        day: bestWinRateDay.day, 
        winRate: bestWinRateDay.metrics.winPercentage.toFixed(2), 
        tradeCount: bestWinRateDay.trades.length 
      }
    };
  }, [dayMetrics]);

  // Calculate summary table data
  const summaryTableData = useMemo(() => dayMetrics.map(({ day, trades, metrics }) => ({
    day,
    winPercent: metrics.winPercentage.toFixed(2),
    netPnl: `$${metrics.netPnL.toFixed(2)}`,
    tradeCount: trades.length,
    avgDailyVolume: metrics.avgDailyVolume.toFixed(2),
    avgWin: `$${metrics.avgTradeWinLoss > 0 ? metrics.avgTradeWinLoss.toFixed(2) : 0}`,
    avgLoss: `-$${metrics.avgTradeWinLoss < 0 ? Math.abs(metrics.avgTradeWinLoss).toFixed(2) : 0}`
  })), [dayMetrics]);

  // Calculate cross analysis data
  const crossAnalysisData = useMemo(() => {
    const symbolsSet = new Set(trades.map(t => t.Symbol));
    const symbols = Array.from(symbolsSet);

    return dayMetrics.map(({ day, trades }) => {
      const symbolPnL = symbols.map(symbol => {
        const symbolTrades = trades.filter(t => t.Symbol === symbol);
        const pnl = symbolTrades.reduce((sum, t) => sum + (t.Profit + (t.Commission || 0) + (t.Swap || 0)), 0);
        return pnl;
      });

      return {
        day,
        values: symbolPnL.map(pnl => pnl > 0 ? `$${pnl.toFixed(2)}` : `-$${Math.abs(pnl).toFixed(2)}`)
      };
    });
  }, [dayMetrics, trades]);

  const symbols = useMemo(() => {
    const symbolsSet = new Set(trades.map(t => t.Symbol));
    return Array.from(symbolsSet);
  }, [trades]);

  return (
    <div className="bg-gray-950 text-white font-sans p-4 box-border">
      {/* Top row of performance cards */}
      <div className="flex gap-4 mb-6">
        <PerformanceCards data={performanceData} />
      </div>

      {/* Charts section */}
      <div className="flex gap-6 mb-6">
        <ChartContainer trades={trades} />
      </div>

      {/* Summary Table */}
      <div className="mb-6">
        <SummaryTable data={summaryTableData} />
      </div>

      {/* Cross Analysis Table */}
      <div className="mb-6">
        <CrossAnalysisTable data={crossAnalysisData} symbols={symbols} />
      </div>
    </div>
  );
};

export default DayTimeReportPage;

src/app/api/dashboard/delete/route.ts.content:
import { NextRequest, NextResponse } from 'next/server';
import { cookies } from 'next/headers';

// Import all DELETE handler functions
import { 
  deleteAsyncAccHandler,
  deleteFileManualHandler,
  deleteManualUploadHandler
} from '../../../../lib/api-handlers/dashboardHandlers';

export async function DELETE(req: NextRequest) {
    try {
        const cookieStore = await cookies();
        const token = cookieStore.get('authToken')?.value;
        const userId = cookieStore.get('userId')?.value;

        if (!token || !userId) {
            return NextResponse.json({ error: "Authentication required" }, { status: 401 });
        }

        const body = await req.json();
        const { apiName } = body;

        if (!apiName) {
            return NextResponse.json({ error: "API name is required" }, { status: 400 });
        }

        switch (apiName) {
            case "deleteAsyncAcc":
                return await deleteAsyncAccHandler(body, userId, token);

            case "deleteFileManual":
                return await deleteFileManualHandler(body, userId, token);

            case "deleteManualUpload":
                return await deleteManualUploadHandler(body, userId, token);

            default:
                return NextResponse.json({ error: "API endpoint not found" }, { status: 404 });
        }

    } catch (error) {
        console.error("DELETE route error:", error);
        return NextResponse.json({ error: "Internal server error" }, { status: 500 });
    }
}

src/lib/db/connect.ts.content:
import mongoose from "mongoose";

const options = {
  maxPoolSize: 20,
  socketTimeoutMS: 45000,
};

const connections: {
  main?: mongoose.Connection;
  accounts?: mongoose.Connection;
  backtest?: mongoose.Connection;
} = {};
console.log("🌐 DB Connect Module Loaded");
export const connectMainDB = async (): Promise<mongoose.Connection> => {
  if (connections.main) {
    console.log("ℹ️ Using existing Main DB connection");
    return connections.main;
  }

  const uri = process.env.DATABASE as string;
  if (!uri) throw new Error("❌ Missing DATABASE environment variable");

  console.log("🔌 Connecting to Main DB...");

  const conn = await mongoose.createConnection(uri, options);

  conn.on("connected", () => console.log("✅ Main DB: Connection Successful"));
  conn.on("error", (err) => console.error("❌ Main DB: Connection Error", err));
  conn.on("disconnected", () => console.warn("⚠️ Main DB: Disconnected"));

  connections.main = conn;
  return conn;
};

export const connectAccountsDB = async (): Promise<mongoose.Connection> => {
  if (connections.accounts) {
    console.log("ℹ️ Using existing Accounts DB connection");
    return connections.accounts;
  }

  const uri = process.env.DATABASE2 as string;
  if (!uri) throw new Error("❌ Missing DATABASE2 environment variable");

  console.log("🔌 Connecting to Accounts DB...");

  const conn = await mongoose.createConnection(uri, options);

  conn.on("connected", () => console.log("✅ Accounts DB: Connection Successful"));
  conn.on("error", (err) => console.error("❌ Accounts DB: Connection Error", err));
  conn.on("disconnected", () => console.warn("⚠️ Accounts DB: Disconnected"));

  connections.accounts = conn;
  return conn;
};

export const connectBacktestDB = async (): Promise<mongoose.Connection> => {
  if (connections.backtest) {
    console.log("ℹ️ Using existing Backtest DB connection");
    return connections.backtest;
  }

  const uri = process.env.DATABASE3 as string;
  if (!uri) throw new Error("❌ Missing DATABASE3 environment variable");

  console.log("🔌 Connecting to Backtest DB...");

  const conn = await mongoose.createConnection(uri, options);

  conn.on("connected", () => console.log("✅ Backtest DB: Connection Successful"));
  conn.on("error", (err) => console.error("❌ Backtest DB: Connection Error", err));
  conn.on("disconnected", () => console.warn("⚠️ Backtest DB: Disconnected"));

  connections.backtest = conn;
  return conn;
};

