// changed 12-13-25

"use client";
import { create } from "zustand";

interface Account {
  checked: boolean;
  accountName: string;
  accountId?: string;
  accountBalance?: number;
  accountType?: string;
  broker?: string;
  description?: string;
  isPropFirm?: boolean;
