}

const generateDemoTradeData = () => {
  const trades = [];
  const symbols = [
    "AAPL",
    "TSLA",
    "NVDA",
    "MSFT",
    "GOOGL",
    "AMZN",
    "META",
    "SPY",
    "QQQ",
  ];
  const strategies = ["Momentum", "Breakout", "Reversal", "Scalping", "Swing"];
  const tradingHours = ["09", "10", "11", "12", "13", "14", "15"];

  // Recent trading days (last 30 days from Dec 2024 - use past dates for API compatibility)
  // 20 trading days spread across Nov-Dec 2024
  const tradingDays = [
    "2024-11-11",
    "2024-11-12",
    "2024-11-13",
    "2024-11-14",
    "2024-11-15",
    "2024-11-18",
    "2024-11-19",
    "2024-11-20",
    "2024-11-21",
    "2024-11-22",
    "2024-11-25",
    "2024-11-26",
    "2024-11-27",
    "2024-11-29",
    "2024-12-02",
    "2024-12-03",
    "2024-12-04",
    "2024-12-05",
    "2024-12-06",
    "2024-12-09",
  ];

  // Target: $6,567 profit, 67% win rate over 20 trading days
  // ~30 trades total: 20 wins, 10 losses = 67% win rate
  const totalTrades = 30;
  const winCount = 20;
  const lossCount = 10;

  // Calculate average win/loss to hit $6,567 profit
  // If avg win = $450 and avg loss = $350: 20*450 - 10*350 = 9000 - 3500 = $5,500
  // Adjust: avg win = $480, avg loss = $330: 20*480 - 10*330 = 9600 - 3300 = $6,300 (close)
  const avgWin = 490;
  const avgLoss = 310;

  const winProfits = Array(winCount)
    .fill(0)
    .map(() => Math.floor(avgWin + (Math.random() - 0.5) * 300));
  const lossProfits = Array(lossCount)
    .fill(0)
    .map(() => -Math.floor(avgLoss + (Math.random() - 0.5) * 200));

  // Adjust last win to hit target of $6,567
  const currentTotal =
    winProfits.reduce((a, b) => a + b, 0) +
    lossProfits.reduce((a, b) => a + b, 0);
  const adjustment = 6567 - currentTotal;
  winProfits[winProfits.length - 1] += adjustment;

  const allProfits = [...winProfits, ...lossProfits];

  // Shuffle and distribute across trading days
  for (let i = allProfits.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [allProfits[i], allProfits[j]] = [allProfits[j], allProfits[i]];
  }

  for (let i = 0; i < totalTrades; i++) {
    const dateStr = tradingDays[i % tradingDays.length];
    const profit = allProfits[i];
    const symbol = symbols[Math.floor(Math.random() * symbols.length)];
    const hour = tradingHours[Math.floor(Math.random() * tradingHours.length)];
    const minute = Math.floor(Math.random() * 60)
      .toString()
      .padStart(2, "0");

    const durationMins = Math.floor(Math.random() * 120) + 5;
    const exitHour = parseInt(hour) + Math.floor((parseInt(minute) + durationMins) / 60);
    const exitMinute = ((parseInt(minute) + durationMins) % 60).toString().padStart(2, "0");

    trades.push({
      date: dateStr,
      symbol: symbol,
      Item: symbol,
      Profit: profit,
      strategy: strategies[Math.floor(Math.random() * strategies.length)],
      entryPrice: (Math.random() * 500 + 50).toFixed(2),
      exitPrice: (Math.random() * 500 + 50).toFixed(2),
      quantity: Math.floor(Math.random() * 100) + 10,
      side: Math.random() > 0.5 ? "Long" : "Short",
      Type: Math.random() > 0.5 ? "Long" : "Short",
      duration: `${durationMins}m`,
      EntryTime: `${hour}:${minute}:00`,
      ExitTime: `${Math.min(exitHour, 16)}:${exitMinute}:00`,
    });
  }
  return trades;
};

const demoAccounts: Account[] = [
  {
    checked: true,
    accountName: "Demo Trading Account",
    accountId: "demo-001",
    accountBalance: 17672,
    accountType: "Paper Trading",
    broker: "Demo Broker",
    description: "Demo account for UI preview",
    isPropFirm: false,
    tradeData: generateDemoTradeData(),
  },
  {
    checked: true,
    accountName: "FTMO Challenge",
    accountId: "demo-002",
    accountBalance: 50000,
    accountType: "Manual",
    broker: "FTMO",
    description: "Prop firm challenge account",
    isPropFirm: true,
    tradeData: generateDemoTradeData(),
  },
];

const demoProfileData = {
  uniqueId: "demo-user",
  fullName: "Demo Trader",
  email: "demo@example.com",
  accountValue: 17672,
};

const demoStrategies = [
  { name: "Momentum", winRate: 71, trades: 14, profit: 3200 },
  { name: "Breakout", winRate: 62, trades: 10, profit: 1850 },
  { name: "Reversal", winRate: 67, trades: 6, profit: 1517 },
];

interface ProfileData {
  uniqueId?: string;
  fullName?: string;
  email?: string;
  phone?: number;
  countryCode?: string;
  country?: string;
  bio?: string;
  profilePicture?: string;
  accountValue?: number;
  [key: string]: any;
}

interface Strategy {
  [key: string]: any;
}

interface AccountDetailsState {
  accounts: Account[];
  profileData: ProfileData;
  selectedAccounts: Account[];
  strategies: Strategy[];
  loading: boolean;
  error: string | null;

  // Actions
  setAccounts: () => Promise<void>;
  updateAccView: (accountName: string) => Promise<void>;
  checkAll: (newAllSelected: boolean) => Promise<void>;
  createAccount: (accountData: {
    accountName: string;
    accountBalance: number;
    accountType: string;
    broker: string;
    description: string;
  }) => Promise<{ success: boolean; message?: string; error?: string }>;
  createAutoSyncAccount: (accountData: {
    accountName: string;
    accountType: string;
    broker: string;
    investorId: string;
    password: string;
    serverName: string;
    description: string;
  }) => Promise<{ success: boolean; message?: string; error?: string }>;
  deleteAccount: (
    accountName: string,
    accountType: "filemanual" | "async",
  ) => Promise<{ success: boolean; message?: string; error?: string }>;
  setLoading: (loading: boolean) => void;
  setError: (error: string | null) => void;
  clearError: () => void;
}

// 🔹 API URLs - Updated for Next.js endpoints
const API_BASE_URL = "/api/dashboard";

const useAccountDetails = create<AccountDetailsState>((set, get) => ({
  accounts: [],
  profileData: {},
  selectedAccounts: [],
  strategies: [],
  loading: false,
  error: null,

  setLoading: (loading: boolean) => set({ loading }),

  setError: (error: string | null) => set({ error }),

  clearError: () => set({ error: null }),

  setAccounts: async () => {
    try {
      set({ loading: true, error: null });
      console.log("setAccounts: Fetching accounts with cookies");

      const res = await fetch(`${API_BASE_URL}/post`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          apiName: "getAccountDetails",
        }),
      });

      const data = await res.json();
      console.log("setAccounts: response", data, "status", res.status);

      if (!res.ok) {
        throw new Error(data.error || "Failed to fetch accounts");
      }

      if (data.error === "Fishy!") {
        set({ accounts: ["/logout"] as any, loading: false });
      } else if (res.status === 200) {
        const accounts = data.accounts || [];
        const selectedAccounts = accounts.filter(
          (account: Account) => account.checked === true,
        );

        console.log(
          "setAccounts: selectedAccounts (filtered):",
          selectedAccounts,
        );

        set({
          accounts: accounts,
          profileData: data.data || {},
          selectedAccounts: selectedAccounts,
          strategies: data.strategies || [],
          loading: false,
        });

        return accounts;
      } else {
        console.warn("setAccounts: unexpected response", res.status, data);
        set({ loading: false });
      }
    } catch (error) {
      console.error("setAccounts: Error fetching accounts:", error);

      // In development, load demo data for UI preview
      if (process.env.NODE_ENV === "development") {
        console.log("setAccounts: Loading demo data for development preview");
        set({
          accounts: demoAccounts,
          profileData: demoProfileData,
          selectedAccounts: demoAccounts,
          strategies: demoStrategies,
          error: null,
          loading: false,
        });
      } else {
        // In production, redirect to login on authentication failure
        console.error(
          "setAccounts: Authentication failed, redirecting to login",
        );
        set({
          accounts: [],
          profileData: {},
          selectedAccounts: [],
          strategies: [],
          error: "Session expired. Please login again.",
          loading: false,
        });

        // Redirect to login page
        if (typeof window !== "undefined") {
          window.location.href = "/login";
        }
      }
    }
  },

  updateAccView: async (accountName: string) => {
    try {
      set({ loading: true, error: null });
      console.log("updateAccView: sending accountName", accountName);

      const response = await fetch(`${API_BASE_URL}/post`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          apiName: "editAccCheck",
          accountName,
        }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || "Failed to update account view");
      }

      const data = await response.json();
      console.log("updateAccView: response", data);

      if (data.data && data.data.accounts) {
        const selectedAccounts = data.data.accounts.filter(
          (account: Account) => account.checked === true,
        );

        set({
          accounts: data.data.accounts,
          selectedAccounts: selectedAccounts,
          loading: false,
        });
      } else {
        set({ loading: false });
      }
    } catch (error) {
      console.error(
        "updateAccView: Error updating account view, toggling locally:",
        error,
      );
      // In demo mode or on API error, toggle locally
      const { accounts } = get();
      const updatedAccounts = accounts.map((acc) =>
        acc.accountName === accountName
          ? { ...acc, checked: !acc.checked }
          : acc,
      );
      const selectedAccounts = updatedAccounts.filter(
        (account: Account) => account.checked === true,
      );
      set({
        accounts: updatedAccounts,
        selectedAccounts: selectedAccounts,
        error: null,
        loading: false,
      });
    }
  },

  checkAll: async (newAllSelected: boolean) => {
    try {
      set({ loading: true, error: null });
      console.log("checkAll: value=", newAllSelected);

      const response = await fetch(`${API_BASE_URL}/post`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          apiName: "checkAll",
          value: newAllSelected,
        }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || "Failed to update all accounts");
      }

      const data = await response.json();
      console.log("checkAll: response", data);

      if (data.data && data.data.accounts) {
        const selectedAccounts = data.data.accounts.filter(
          (account: Account) => account.checked === true,
        );

        set({
          accounts: data.data.accounts,
          selectedAccounts: selectedAccounts,
          loading: false,
        });
      } else {
        set({ loading: false });
      }
    } catch (error) {
      console.error("checkAll: Error checking all accounts:", error);
      set({
        error:
          error instanceof Error
            ? error.message
            : "Failed to update all accounts",
        loading: false,
      });
    }
  },

  createAccount: async (accountData) => {
    try {
      set({ loading: true, error: null });
      console.log("createAccount: creating account", accountData);

      const response = await fetch(`${API_BASE_URL}/post`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          apiName: "createAccount",
          ...accountData,
        }),
      });

      const data = await response.json();
      console.log("createAccount: response", data);

      if (!response.ok) {
        throw new Error(data.error || "Failed to create account");
      }

      set({ loading: false });

      // Refresh accounts after successful creation
      if (response.ok && data.message) {
        await get().setAccounts(); // Refresh the accounts list
        return { success: true, message: data.message };
      }

      return { success: false, error: "Unexpected response" };
    } catch (error) {
      console.error("createAccount: Error creating account:", error);
      set({
        error:
          error instanceof Error ? error.message : "Failed to create account",
        loading: false,
      });
      return {
        success: false,
        error:
          error instanceof Error ? error.message : "Failed to create account",
      };
    }
  },

  createAutoSyncAccount: async (accountData) => {
    try {
      set({ loading: true, error: null });
      console.log(
        "createAutoSyncAccount: creating auto sync account",
        accountData,
      );

      const response = await fetch(`${API_BASE_URL}/post`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          apiName: "createAutoSyncAccount",
          ...accountData,
        }),
      });

      const data = await response.json();
      console.log("createAutoSyncAccount: response", data);

      if (!response.ok) {
        throw new Error(data.error || "Failed to create auto sync account");
      }

      set({ loading: false });

      // Refresh accounts after successful creation
      if (response.ok && data.message) {
        await get().setAccounts(); // Refresh the accounts list
        return { success: true, message: data.message };
      }

      return { success: false, error: "Unexpected response" };
    } catch (error) {
      console.error(
        "createAutoSyncAccount: Error creating auto sync account:",
        error,
      );
      set({
        error:
          error instanceof Error
            ? error.message
            : "Failed to create auto sync account",
        loading: false,
      });
      return {
        success: false,
        error:
          error instanceof Error
            ? error.message
            : "Failed to create auto sync account",
      };
    }
  },

  deleteAccount: async (
    accountName: string,
    accountType: "filemanual" | "async",
  ) => {
    try {
      set({ loading: true, error: null });
      console.log("deleteAccount: deleting account", accountName, accountType);

      const apiName =
        accountType === "async" ? "deleteAsyncAcc" : "deleteFileManual";

      const response = await fetch(`${API_BASE_URL}/delete`, {
        method: "DELETE",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          apiName: apiName,
          accountName: accountName,
        }),
      });

      const data = await response.json();
      console.log("deleteAccount: response", data);

      if (!response.ok) {
        throw new Error(data.error || "Failed to delete account");
      }

      set({ loading: false });

      // Refresh accounts after successful deletion
      if (response.ok && data.message) {
        await get().setAccounts(); // Refresh the accounts list
        return { success: true, message: data.message };
      }

      return { success: false, error: "Unexpected response" };
    } catch (error) {
      console.error("deleteAccount: Error deleting account:", error);
      set({
        error:
          error instanceof Error ? error.message : "Failed to delete account",
        loading: false,
      });
      return {
        success: false,
        error:
          error instanceof Error ? error.message : "Failed to delete account",
      };
    }
  },
}));

export default useAccountDetails;

src/app/(root)/notebook/page.tsx.content:
"use client"
import { useEffect, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { 
  Search, 
  Filter, 
  Menu, 
  X, 
  ChevronLeft, 
  BookOpen,
  PanelLeftClose,
  PanelLeft
} from "lucide-react";
import notebookStore from "@/store/notebookStore";
import Files from "@/components/notebook/Files";
import Folder from "@/components/notebook/Folder";
import ViewMode from "@/components/notebook/ViewMode";
import EditMode from "@/components/notebook/EditMode";

const Notebook = () => {
  const { notes, setNotes, selectedFolder, setFolder, selectedFile, setFile } = notebookStore();

  const [mode, setMode] = useState("VIEW");
  const [searchQuery, setSearchQuery] = useState("");
  const [mobilePanel, setMobilePanel] = useState<"folders" | "files" | "content">("folders");
  const [showMobileSidebar, setShowMobileSidebar] = useState(false);
  const [isFolderPanelOpen, setIsFolderPanelOpen] = useState(true);

  const changeMode = (mode: string) => {
    setMode(mode)
  }

  const [newFile, setNewFile] = useState("")
  const [newFolder, setNewFolder] = useState("")
  const [fileShow, setFileShow] = useState(false);

  useEffect(() => {
    setNotes();
  }, [setNotes])

  const handleFolderSelect = (folderName: string) => {
    setFolder(folderName);
    setMobilePanel("files");
  };

  const handleFileSelect = (fileName: string) => {
    setFile(fileName);
    setMobilePanel("content");
  };

  const handleBackToFolders = () => {
    setMobilePanel("folders");
  };

  const handleBackToFiles = () => {
    setMobilePanel("files");
  };

  const totalNotes = notes.reduce((acc, folder) => acc + (folder.files?.length || 0), 0);

  return (
    <div className="min-h-screen bg-background">
      {/* Premium Header */}
      <div className="sticky top-0 z-20 bg-card/80 backdrop-blur-xl border-b border-border">
        <div className="h-0.5 bg-gradient-to-r from-primary via-profit to-primary opacity-60" />

        <div className="px-3 md:px-6 py-2.5 md:py-4">
          <div className="flex items-center gap-2 md:gap-4">
            {/* Mobile Back Button */}
            {mobilePanel !== "folders" ? (
              <button 
                onClick={mobilePanel === "content" ? handleBackToFiles : handleBackToFolders}
                className="md:hidden p-2 -ml-1 rounded-lg hover:bg-muted transition-colors flex-shrink-0"
              >
                <ChevronLeft className="h-5 w-5 text-muted-foreground" />
              </button>
            ) : (
              <div className="md:hidden w-7 h-7 rounded-lg bg-gradient-to-br from-primary/20 to-profit/20 flex items-center justify-center flex-shrink-0">
                <BookOpen className="h-3.5 w-3.5 text-primary" />
              </div>
            )}

            {/* Mobile Title */}
            <div className="md:hidden flex-1 min-w-0">
              <h1 className="text-sm font-semibold text-foreground truncate">
                {mobilePanel === "folders" ? "Notebook" : mobilePanel === "files" ? selectedFolder : "Note"}
              </h1>
              {mobilePanel === "folders" && (
                <p className="text-[10px] text-muted-foreground">
                  {notes.length} folders · {totalNotes} notes
                </p>
              )}
            </div>

            {/* Desktop Folder Panel Toggle */}
            <button
              onClick={() => setIsFolderPanelOpen(!isFolderPanelOpen)}
              className="hidden md:flex items-center justify-center w-9 h-9 rounded-lg hover:bg-muted transition-colors flex-shrink-0"
              title={isFolderPanelOpen ? "Hide folders" : "Show folders"}
            >
              {isFolderPanelOpen ? (
                <PanelLeftClose className="h-4 w-4 text-muted-foreground" />
              ) : (
                <PanelLeft className="h-4 w-4 text-muted-foreground" />
              )}
            </button>

            {/* Desktop Title with Stats */}
            <div className="hidden md:flex items-center gap-3">
              <div className="flex items-center gap-2">
                <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-primary/20 to-profit/20 flex items-center justify-center flex-shrink-0">
                  <BookOpen className="h-4 w-4 text-primary" />
                </div>
                <div>
                  <h1 className="text-sm font-semibold text-foreground">Notebook</h1>
                  <p className="text-[10px] text-muted-foreground">
                    {notes.length} folders · {totalNotes} notes
                  </p>
                </div>
              </div>
            </div>

            {/* Search - Hidden on mobile folders view, show icon only */}
            <div className="hidden md:flex flex-1 max-w-md relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <input
                name="search"
                type="text"
                placeholder="Search notes..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full pl-10 pr-4 py-2.5 bg-background/50 border border-border rounded-lg text-sm text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary/50 transition-all"
              />
            </div>

            {/* Mobile Search Button */}
            <button className="md:hidden p-2 rounded-lg hover:bg-muted transition-colors flex-shrink-0">
              <Search className="h-5 w-5 text-muted-foreground" />
            </button>

            {/* Filter Button */}
            <button className="hidden md:flex items-center gap-2 px-3 py-2 bg-muted/50 border border-border rounded-lg hover:bg-muted hover:border-primary/30 transition-all group flex-shrink-0">
              <Filter className="h-4 w-4 text-muted-foreground group-hover:text-primary transition-colors" />
              <span className="text-sm font-medium text-muted-foreground group-hover:text-foreground transition-colors">Filter</span>
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Sidebar Overlay */}
      <AnimatePresence>
        {showMobileSidebar && (
          <div className="fixed inset-0 z-50 md:hidden">
            <motion.div 
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="absolute inset-0 bg-black/60 backdrop-blur-sm"
              onClick={() => setShowMobileSidebar(false)}
            />
            <motion.div 
              initial={{ x: -320 }}
              animate={{ x: 0 }}
              exit={{ x: -320 }}
              transition={{ type: "spring", damping: 25, stiffness: 300 }}
              className="absolute left-0 top-0 bottom-0 w-80 bg-card border-r border-border overflow-hidden"
            >
              <div className="flex items-center justify-between px-4 py-4 border-b border-border bg-muted/30">
                <div className="flex items-center gap-2">
                  <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-primary/20 to-profit/20 flex items-center justify-center">
                    <BookOpen className="h-4 w-4 text-primary" />
                  </div>
                  <h2 className="text-base font-semibold text-foreground">Notebooks</h2>
                </div>
                <button 
                  onClick={() => setShowMobileSidebar(false)}
                  className="p-2 rounded-lg hover:bg-muted transition-colors"
                >
                  <X className="h-5 w-5 text-muted-foreground" />
                </button>
              </div>

              <div className="p-4 overflow-y-auto h-[calc(100%-65px)]">
                <Folder
                  notes={notes}
                  setNotes={setNotes}
                  selectedFolder={selectedFolder}
                  changeMode={changeMode}
                  setFolder={(folder) => {
                    handleFolderSelect(folder);
                    setShowMobileSidebar(false);
                  }}
                  newFolder={newFolder}
                  setNewFolder={setNewFolder}
                  setNewFile={setNewFile}
                  setFileShow={setFileShow}
                  newFile={newFile}
                />
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      {/* Main Content - Desktop Three Column Layout */}
      <div className="flex h-[calc(100vh-65px)]">
        {/* Left Panel - Folders (Collapsible on Desktop) */}
        <AnimatePresence>
          {isFolderPanelOpen && (
            <motion.div
              initial={{ opacity: 0, width: 0 }}
              animate={{ opacity: 1, width: 240 }}
              exit={{ opacity: 0, width: 0 }}
              transition={{ type: "spring", damping: 25, stiffness: 300 }}
              className="hidden md:block flex-shrink-0 border-r border-border bg-card/30 overflow-hidden"
            >
              <div className="w-60 h-full overflow-y-auto p-4">
                <Folder
                  notes={notes}
                  setNotes={setNotes}
                  selectedFolder={selectedFolder}
                  changeMode={changeMode}
                  setFolder={setFolder}
                  newFolder={newFolder}
                  setNewFolder={setNewFolder}
                  setNewFile={setNewFile}
                  setFileShow={setFileShow}
                  newFile={newFile}
                />
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        {/* Middle Panel - Files (Always visible on Desktop) */}
        <div className="hidden md:flex w-72 lg:w-80 flex-shrink-0 border-r border-border bg-card/20 overflow-hidden flex-col">
          <div className="h-full overflow-y-auto p-4">
            <Files
              newFile={newFile}
              notes={notes}
              setNotes={setNotes}
              selectedFolder={selectedFolder}
              newFolder={newFolder}
              setNewFolder={setNewFolder}
              fileShow={fileShow}
              setNewFile={setNewFile}
              setFileShow={setFileShow}
              changeMode={changeMode}
              setFile={handleFileSelect}
            />
          </div>
        </div>

        {/* Mobile: Folders Panel */}
        {mobilePanel === "folders" && (
          <div className="flex md:hidden w-full flex-col overflow-hidden bg-card/30">
            <div className="h-full overflow-y-auto p-4">
              <Folder
                notes={notes}
                setNotes={setNotes}
                selectedFolder={selectedFolder}
                changeMode={changeMode}
                setFolder={handleFolderSelect}
                newFolder={newFolder}
                setNewFolder={setNewFolder}
                setNewFile={setNewFile}
                setFileShow={setFileShow}
                newFile={newFile}
              />
            </div>
          </div>
        )}

        {/* Mobile: Files Panel */}
        {mobilePanel === "files" && (
          <div className="flex md:hidden w-full flex-col overflow-hidden bg-card/30">
            <div className="h-full overflow-y-auto p-4">
              <Files
                newFile={newFile}
                notes={notes}
                setNotes={setNotes}
                selectedFolder={selectedFolder}
                newFolder={newFolder}
                setNewFolder={setNewFolder}
                fileShow={fileShow}
                setNewFile={setNewFile}
                setFileShow={setFileShow}
                changeMode={changeMode}
                setFile={handleFileSelect}
              />
            </div>
          </div>
        )}

        {/* Right Panel - Content (Focus Canvas) */}
        <div className={`${mobilePanel === "content" ? "flex" : "hidden"} md:flex flex-1 overflow-hidden flex-col bg-background`}>
          <div className="h-full overflow-y-auto">
            {mode === "VIEW" ? (
              <ViewMode
                notes={notes}
                selectedFolder={selectedFolder}
                selectedFile={selectedFile}
                changeMode={changeMode}
              />
            ) : mode === "EDIT" ? (
              <EditMode
                notes={notes}
                selectedFolder={selectedFolder}
                selectedFile={selectedFile}
                changeMode={changeMode}
                setNotes={setNotes}
              />
            ) : null}
          </div>
        </div>
      </div>
    </div>
  )
}

export default Notebook;

src/components/strategy/reports/Strategy.content:
"use client"
import { useState, useEffect } from "react";
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  Tooltip,
  CartesianGrid,
  ResponsiveContainer,
  BarChart,
  Bar,
  Legend,
} from "recharts";
import { FileText, TrendingUp, TrendingDown, Activity, Award, Calendar, Clock, Target, BarChart3 } from "lucide-react";

const formatINR = (n: number) =>
  `$${Math.abs(Number(n || 0)).toLocaleString("en-US")}`;

interface Trade {
  OpenTime?: string;
  CloseTime?: string;
  date?: string;
  Profit?: number;
  [key: string]: any;
}

const getDayName = (dateStr: string) => {
  const days = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
  const d = new Date(dateStr);
  return days[d.getUTCDay()] || "Unknown";
};

const calculateAvgDuration = (trades: Trade[]) => {
  const valid = trades.filter((t) => t.OpenTime && t.CloseTime);
  if (!valid.length) return "—";

  const totalMs = valid.reduce((sum, t) => {
    const open = new Date(t.OpenTime!.replace(/\./g, "-"));
    const close = new Date(t.CloseTime!.replace(/\./g, "-"));
    return sum + Math.abs(close.getTime() - open.getTime());
  }, 0);

  const avgMs = totalMs / valid.length;
  const mins = avgMs / (1000 * 60);
  const hours = mins / 60;
  const days = hours / 24;

  if (mins < 60) return `${mins.toFixed(1)} min`;
  if (hours < 24) return `${hours.toFixed(1)} hr`;
  return `${days.toFixed(2)} days`;
};

interface DayStat {
  day: string;
  trades: number;
  wins: number;
  pnl: number;
  winRate?: string;
}

interface Metric {
  label: string;
  value: string;
  negative: boolean;
}

interface ReportsProps {
  selected?: string[];
  strategiesDataObj?: { [key: string]: Trade[] };
}

const Reports = ({ selected = [], strategiesDataObj = {} }: ReportsProps) => {
  const [chartColors, setChartColors] = useState({
    primary: '',
    profit: '',
    loss: '',
    text: '',
    grid: '',
    cardBg: ''
  });

  useEffect(() => {
    if (typeof window !== 'undefined') {
      const style = getComputedStyle(document.documentElement);
      setChartColors({
        primary: style.getPropertyValue('--color-primary').trim() || '',
        profit: style.getPropertyValue('--color-profit').trim() || '',
        loss: style.getPropertyValue('--color-loss').trim() || '',
        text: style.getPropertyValue('--color-muted-foreground').trim() || '',
        grid: style.getPropertyValue('--color-border').trim() || '',
        cardBg: style.getPropertyValue('--color-card').trim() || ''
      });
    }
  }, []);

  const allTrades = selected
    .map((s) => strategiesDataObj[s])
    .filter(Boolean)
    .flat();

  if (!allTrades.length) {
    return (
      <div className="w-full min-h-[70vh] text-foreground flex flex-col gap-6">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center">
            <FileText className="h-5 w-5 text-primary" />
          </div>
          <div>
            <h2 className="text-xl font-semibold text-foreground">Performance Report</h2>
            <p className="text-sm text-muted-foreground">Detailed trading analytics</p>
          </div>
        </div>
        <div className="flex flex-col items-center justify-center py-16 text-center">
          <div className="w-16 h-16 rounded-2xl bg-muted flex items-center justify-center mb-4">
            <BarChart3 className="h-8 w-8 text-muted-foreground" />
          </div>
          <p className="text-muted-foreground">No trades found for selected strategies.</p>
        </div>
      </div>
    );
  }

  const dayStats: { [key: string]: DayStat } = {};
  allTrades.forEach((t) => {
    const day = getDayName(t.date || t.OpenTime!);
    if (!dayStats[day]) dayStats[day] = { day, trades: 0, wins: 0, pnl: 0 };

    dayStats[day].trades += 1;
    if ((t.Profit || 0) > 0) dayStats[day].wins += 1;
    dayStats[day].pnl += t.Profit || 0;
  });

  const orderedDays = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
  const dailyStats = orderedDays
    .map((day) => {
      const d = dayStats[day];
      if (!d) return null;
      return {
        ...d,
        winRate: d.trades ? ((d.wins / d.trades) * 100).toFixed(1) : "0",
      };
    })
    .filter(Boolean) as (DayStat & { winRate: string })[];

  const totalTrades = allTrades.length;
  const totalProfit = allTrades.reduce((s, t) => s + (t.Profit || 0), 0);
  const winTrades = allTrades.filter((t) => (t.Profit || 0) > 0);
  const lossTrades = allTrades.filter((t) => (t.Profit || 0) <= 0);
  const winRate = totalTrades ? (winTrades.length / totalTrades) * 100 : 0;
  const avgWin =
    winTrades.length > 0
      ? winTrades.reduce((s, t) => s + (t.Profit || 0), 0) / winTrades.length
      : 0;
  const avgLoss =
    lossTrades.length > 0
      ? lossTrades.reduce((s, t) => s + Math.abs(t.Profit || 0), 0) /
      lossTrades.length
      : 0;

  const profitFactor = avgLoss ? (avgWin / avgLoss).toFixed(2) : "—";
  const tradeExpectancy = totalTrades ? totalProfit / totalTrades : 0;
  const avgDurationFormatted = calculateAvgDuration(allTrades);

  const loggedDays = Object.keys(dayStats).length;
  const avgTradePnl = totalTrades ? totalProfit / totalTrades : 0;
  const avgDailyNetPnl = loggedDays ? totalProfit / loggedDays : 0;

  const maxDailyDrawdown =
    dailyStats.length > 0
      ? Math.min(...dailyStats.map((d) => d.pnl))
      : 0;

  const avgDailyDrawdown =
    dailyStats.length > 0 && dailyStats.filter((d) => d.pnl < 0).length > 0
      ? (
        dailyStats
          .filter((d) => d.pnl < 0)
          .reduce((sum, d) => sum + d.pnl, 0) /
        dailyStats.filter((d) => d.pnl < 0).length
      )
      : 0;

  const avgDailyWinRate =
    dailyStats.length > 0
      ? (
        dailyStats.reduce((s, d) => s + Number(d.winRate || 0), 0) /
        dailyStats.length
      )
      : 0;

  const bestDay = dailyStats.reduce((a, b) => (a.pnl > b.pnl ? a : b));
  const worstDay = dailyStats.reduce((a, b) => (a.pnl < b.pnl ? a : b));
  const activeDay = dailyStats.reduce((a, b) =>
    a.trades > b.trades ? a : b
  );
  const bestWinRateDay = dailyStats.reduce((a, b) =>
    parseFloat(a.winRate) > parseFloat(b.winRate) ? a : b
  );

  const metrics: Metric[] = [
    { label: "Net P&L", value: `${totalProfit < 0 ? "-" : ""}${formatINR(totalProfit)}`, negative: totalProfit < 0 },
    { label: "Win %", value: `${winRate.toFixed(2)}%`, negative: false },
    { label: "Avg daily win %", value: `${avgDailyWinRate.toFixed(2)}%`, negative: false },
    { label: "Profit factor", value: profitFactor, negative: false },
    { label: "Trade expectancy", value: `${tradeExpectancy < 0 ? "-" : ""}${formatINR(tradeExpectancy)}`, negative: tradeExpectancy < 0 },
    { label: "Avg daily win/loss", value: avgLoss && loggedDays ? (avgDailyNetPnl / avgLoss).toFixed(2) : "—", negative: false },
    { label: "Avg trade win/loss", value: avgLoss ? (avgWin / avgLoss).toFixed(2) : "—", negative: false },
    { label: "Avg hold time", value: avgDurationFormatted, negative: false },
    { label: "Avg net trade P&L", value: `${avgTradePnl < 0 ? "-" : ""}${formatINR(avgTradePnl)}`, negative: avgTradePnl < 0 },
    { label: "Avg daily net P&L", value: `${avgDailyNetPnl < 0 ? "-" : ""}${formatINR(avgDailyNetPnl)}`, negative: avgDailyNetPnl < 0 },
    { label: "Avg planned r-multiple", value: "—", negative: false },
    { label: "Avg realized r-multiple", value: "—", negative: false },
    { label: "Avg daily volume", value: (totalTrades / loggedDays).toFixed(1), negative: false },
    { label: "Logged days", value: loggedDays.toString(), negative: false },
    { label: "Max daily net drawdown", value: `${formatINR(maxDailyDrawdown)}`, negative: maxDailyDrawdown < 0 },
    { label: "Avg daily net drawdown", value: `${formatINR(avgDailyDrawdown)}`, negative: avgDailyDrawdown < 0 },
  ];

  const tooltipStyle = {
    background: chartColors.cardBg || 'var(--color-card)',
    border: `1px solid ${chartColors.grid || 'var(--color-border)'}`,
    borderRadius: '8px',
    color: 'var(--color-foreground)',
  };

  const dayHighlights = [
    { label: "Best performing day", day: bestDay.day, value: `$${bestDay.pnl.toLocaleString("en-US")}`, sub: `${bestDay.trades} trades`, type: "profit", icon: TrendingUp },
    { label: "Least performing day", day: worstDay.day, value: `$${worstDay.pnl.toLocaleString("en-US")}`, sub: `${worstDay.trades} trades`, type: "loss", icon: TrendingDown },
    { label: "Most active day", day: activeDay.day, value: `${activeDay.trades}`, sub: "trades", type: "primary", icon: Activity },
    { label: "Best win rate", day: bestWinRateDay.day, value: `${bestWinRateDay.winRate}%`, sub: `${bestWinRateDay.trades} trades`, type: "primary", icon: Award },
  ];

  return (
    <div className="w-full min-h-[70vh] text-foreground flex flex-col gap-6">
      {/* Header */}
      <div className="flex items-center gap-3">
        <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center">
          <FileText className="h-5 w-5 text-primary" />
        </div>
        <div>
          <h2 className="text-xl font-semibold text-foreground">Performance Report</h2>
          <p className="text-sm text-muted-foreground">Detailed trading analytics</p>
        </div>
      </div>

      {/* Metrics Grid */}
      <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-3">
        {metrics.map((m, i) => (
          <div 
            key={i} 
            className="bg-card border border-border rounded-xl p-4 transition-all duration-200 hover:shadow-lg hover:shadow-primary/5 hover:-translate-y-0.5"
          >
            <p className="text-muted-foreground text-xs font-medium">{m.label}</p>
            <h3 className={`text-lg font-bold mt-1 ${m.negative ? 'text-loss' : 'text-foreground'}`}>
              {m.value}
            </h3>
          </div>
        ))}
      </div>

      {/* Day Highlights */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {dayHighlights.map((highlight, i) => {
          const Icon = highlight.icon;
          const colorClass = highlight.type === "profit" ? "text-profit" : highlight.type === "loss" ? "text-loss" : "text-primary";
          const bgClass = highlight.type === "profit" ? "bg-profit/10" : highlight.type === "loss" ? "bg-loss/10" : "bg-primary/10";

          return (
            <div 
              key={i}
              className="bg-card border border-border rounded-xl p-4 transition-all duration-200 hover:shadow-lg hover:shadow-primary/5 hover:-translate-y-0.5"
            >
              <div className="flex items-center justify-between mb-2">
                <span className="text-muted-foreground text-xs font-medium">{highlight.label}</span>
                <div className={`w-7 h-7 rounded-lg ${bgClass} flex items-center justify-center`}>
                  <Icon className={`h-3.5 w-3.5 ${colorClass}`} />
                </div>
              </div>
              <h2 className={`text-xl font-bold ${colorClass}`}>{highlight.day}</h2>
              <p className={`text-sm ${colorClass} mt-1`}>
                <span className="font-semibold">{highlight.value}</span> {highlight.sub}
              </p>
            </div>
          );
        })}
      </div>

      {/* Charts Row */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        {/* Line Chart */}
        <div className="bg-card border border-border rounded-xl overflow-hidden transition-all duration-200 hover:shadow-lg hover:shadow-primary/5">
          <div className="flex items-center gap-3 p-4 border-b border-border">
            <div className="w-8 h-8 rounded-lg bg-primary/10 flex items-center justify-center">
              <TrendingUp className="h-4 w-4 text-primary" />
            </div>
            <div>
              <h3 className="text-sm font-semibold text-foreground">Trade Count by Day</h3>
              <span className="text-xs text-muted-foreground">Weekly distribution</span>
            </div>
          </div>
          <div className="p-4">
            <ResponsiveContainer width="100%" height={250}>
              <LineChart data={dailyStats}>
