                    isExpanded ? "w-8 h-8" : "w-7 h-7"
                  )}>
                    <span className={cn(
                      "font-bold text-[#4EBF94]",
                      isExpanded ? "text-xs" : "text-[10px]"
                    )}>
                      {userInitials}
                    </span>
                  </div>
                  <div className="absolute -bottom-0.5 -right-0.5 w-2.5 h-2.5 bg-[#4EBF94] rounded-full border-2 border-sidebar" />
                </div>

                {isExpanded && (
                  <div className="overflow-hidden flex-1 min-w-0">
                    <p className="text-[12px] font-semibold text-foreground truncate">
                      {profileData.fullName}
                    </p>
                    <p className="text-[10px] text-muted-foreground truncate">
                      {maskedEmail}
                    </p>
                  </div>
                )}
              </Link>
            </motion.div>
          )}

          {/* Logout button */}
          <motion.button
            className={cn(
              "group w-full flex items-center gap-2.5 rounded-md px-2.5 py-2 mt-1 text-[12px] font-medium transition-all duration-200",
              "text-muted-foreground hover:text-red-500 hover:bg-red-500/10",
              !isExpanded && "justify-center px-1.5"
            )}
            onClick={handleLogout}
            whileHover={{ x: isExpanded ? 2 : 0 }}
            whileTap={{ scale: 0.98 }}
          >
            <LogOut className="h-4 w-4 flex-shrink-0 transition-transform group-hover:scale-110" />
            {isExpanded && <span>Log out</span>}
          </motion.button>
        </div>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-background">
      {/* Page Loading Indicator */}
      <Suspense fallback={null}>
        <PageLoading />
      </Suspense>

      {/* Popups */}
      <AddtradesMain />
      <DeleteAccPopup />
      <EditAccPopup />
      <AddAccPopup />
      <EditTradePopUp />
      <CalendarPopup />
      <AlertBox />
      <DjImgPopup />

      {/* Search Modal */}
      <AnimatePresence>
        {searchOpen && (
          <>
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="fixed inset-0 bg-black/50 backdrop-blur-sm z-[100]"
              onClick={() => {
                setSearchOpen(false);
                setSearchQuery("");
              }}
            />
            <motion.div
              initial={{ opacity: 0, scale: 0.95, y: -20 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.95, y: -20 }}
              transition={{ duration: 0.15 }}
              className="fixed left-1/2 top-[20%] -translate-x-1/2 z-[101] w-full max-w-md"
            >
              <div className="bg-background border border-border rounded-xl shadow-2xl overflow-hidden">
                <div className="flex items-center gap-3 px-4 py-3 border-b border-border">
                  <Search className="h-4 w-4 text-muted-foreground" />
                  <input
                    type="text"
                    placeholder="Search pages..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="flex-1 bg-transparent text-sm outline-none placeholder:text-muted-foreground"
                    autoFocus
                  />
                  <span className="text-[10px] text-muted-foreground px-1.5 py-0.5 rounded bg-muted font-mono">ESC</span>
                </div>
                <div className="max-h-[300px] overflow-y-auto p-2">
                  {filteredNavItems.length > 0 ? (
                    filteredNavItems.map((item) => {
                      const Icon = item.icon;
                      return (
                        <Link
                          key={item.href}
                          href={item.href}
                          onClick={() => {
                            setSearchOpen(false);
                            setSearchQuery("");
                          }}
                          className="flex items-center gap-3 px-3 py-2.5 rounded-lg hover:bg-muted transition-colors"
                        >
                          <Icon className="h-4 w-4" style={{ color: item.color }} />
                          <span className="text-sm">{item.name}</span>
                          {item.badge && (
                            <span className="ml-auto text-[10px] px-1.5 py-0.5 rounded-full bg-primary/10 text-primary font-medium">
                              {item.badge}
                            </span>
                          )}
                        </Link>
                      );
                    })
                  ) : (
                    <div className="px-3 py-6 text-center text-sm text-muted-foreground">
                      No results found
                    </div>
                  )}
                </div>
              </div>
            </motion.div>
          </>
        )}
      </AnimatePresence>

      {/* Mobile Overlay */}
      {mobileOpen && (
        <div
          className="fixed inset-0 bg-black/60 backdrop-blur-sm z-40 lg:hidden"
          onClick={() => setMobileOpen(false)}
        />
      )}

      {/* Sidebar - Desktop (Floating Design) */}
      <aside
        className={cn(
          "fixed left-3 top-[25px] z-50 hidden lg:flex flex-col transition-all duration-300 ease-out",
          "h-[calc(100vh-50px)]",
          collapsed ? "w-[52px]" : "w-[220px]",
        )}
      >
        <div className={cn(
          "h-full rounded-2xl overflow-hidden relative",
          "bg-sidebar/95 backdrop-blur-2xl",
          "border border-sidebar-border",
          "shadow-2xl shadow-black/10 dark:shadow-black/40"
        )}>
          {/* Layered gradient overlays */}
          <div className="absolute inset-0 bg-gradient-to-b from-foreground/[0.02] via-transparent to-foreground/[0.02] dark:from-white/[0.04] dark:via-transparent dark:to-black/20 pointer-events-none" />
          <div className="absolute inset-0 bg-gradient-to-br from-[#4EBF94]/[0.01] via-transparent to-violet-500/[0.01] dark:from-[#4EBF94]/[0.02] dark:to-violet-500/[0.02] pointer-events-none" />

          {/* Inner glow */}
          <div className="absolute inset-0 rounded-2xl shadow-[inset_0_1px_1px_rgba(0,0,0,0.03)] dark:shadow-[inset_0_1px_1px_rgba(255,255,255,0.05)] pointer-events-none" />

          <SidebarContent />
        </div>
      </aside>

      {/* Sidebar - Mobile */}
      <aside
        className={cn(
          "fixed left-0 top-0 z-50 flex lg:hidden h-screen w-[264px] flex-col transition-transform duration-300 ease-out p-2",
          mobileOpen ? "translate-x-0" : "-translate-x-full",
        )}
      >
        <div className={cn(
          "h-full rounded-2xl overflow-hidden relative",
          "bg-sidebar/98 backdrop-blur-2xl",
          "border border-sidebar-border",
          "shadow-2xl shadow-black/10 dark:shadow-black/40"
        )}>
          <div className="absolute inset-0 bg-gradient-to-b from-foreground/[0.02] via-transparent to-foreground/[0.02] dark:from-white/[0.04] dark:via-transparent dark:to-black/20 pointer-events-none" />
          <div className="absolute inset-0 bg-gradient-to-br from-[#4EBF94]/[0.01] via-transparent to-violet-500/[0.01] dark:from-[#4EBF94]/[0.02] dark:to-violet-500/[0.02] pointer-events-none" />
          <div className="absolute inset-0 rounded-2xl shadow-[inset_0_1px_1px_rgba(0,0,0,0.03)] dark:shadow-[inset_0_1px_1px_rgba(255,255,255,0.05)] pointer-events-none" />

          <SidebarContent />
        </div>
      </aside>

      {/* Main Content Area */}
      <div
        className={cn(
          "min-h-screen transition-all duration-300",
          "lg:ml-[64px]",
          !collapsed && "lg:ml-[232px]",
        )}
      >
        {/* Top Bar */}
        <header className="sticky top-0 z-30 flex h-16 items-center justify-between gap-4 border-b border-border bg-background/95 backdrop-blur supports-[backdrop-filter]:bg-background/60 px-4 lg:px-6">
          {/* Left side */}
          <div className="flex items-center gap-3">
            {/* Mobile menu button */}
            <Button
              variant="ghost"
              size="icon"
              className="h-9 w-9 lg:hidden"
              onClick={() => setMobileOpen(true)}
            >
              <Menu className="h-5 w-5" />
            </Button>
            <h1 className="text-lg lg:text-xl font-semibold text-foreground">
              {getPageTitle()}
            </h1>
          </div>

          {/* Right side */}
          <div className="flex items-center gap-1 lg:gap-2">
            {/* Currency Dropdown */}
            <CurrencyDropdown />

            {/* Accounts Dropdown */}
            <div className="hidden sm:block">
              <AccountsDropdown />
            </div>

            {/* Date Range */}
            <Button
              variant="outline"
              size="sm"
              className="hidden md:flex gap-2"
            >
              <Calendar className="h-4 w-4" />
              <span>Last 30 days</span>
            </Button>

            {/* Notifications */}
            <Button variant="ghost" size="icon" className="h-9 w-9">
              <Bell className="h-5 w-5" />
            </Button>

            {/* Theme Toggle */}
            <Button
              variant="ghost"
              size="icon"
              className="h-9 w-9"
              onClick={toggleTheme}
            >
              {isDarkMode ? (
                <Sun className="h-5 w-5" />
              ) : (
                <Moon className="h-5 w-5" />
              )}
            </Button>
          </div>
        </header>

        {/* Page Content */}
        <main className="p-4 lg:p-6">{children}</main>
      </div>
    </div>
  );
}

src/components/dashboard-components/dasb.content:
'use client';

import { useState, useMemo, useRef, useEffect } from "react";
import React from "react";
import { createPortal } from "react-dom";
import { AnimatePresence, motion } from "framer-motion";
import { ChevronLeft, ChevronRight, Calendar, TrendingUp, TrendingDown, Clock, Target, Flame, BarChart3 } from "lucide-react";
import { cn } from "@/lib/utils";

import DashWidgets from "../dashboard-widgets/DashboardWidget";
import TradesWidget from "../TradesWidget";
import PnLchartDaily from "./Graphs/PnLDailyChart";
import VeriticalBarGraph from "./Graphs/VerticalBarGraph";

import { useModeFilteredAccounts } from '@/hooks/useModeFilteredAccounts';
import useCurrencyStore, { formatCurrencyValue, formatCompactCurrency } from "@/store/currencyStore";
import { calculateProfitFactor, calculateRiskRewardRatio, calculateBalance } from '@/utils/dashboard-calculations/dashboardCalculations';

interface TradeData {
  date: string;
  Profit: number;
  time?: string;
  Item?: string;
  OpenTime?: string;
  Type?: string;
  [key: string]: unknown;
}

interface Account {
  tradeData?: TradeData[];
}

interface GroupedTrade {
  date: string;
  trades: TradeData[];
  profit: number;
  tradeLength: number;
}

const DashboardDay: React.FC = () => {
  const { selectedAccounts } = useModeFilteredAccounts();
  const { currency, exchangeRate } = useCurrencyStore();

  const groupedTrades = (selectedAccounts as Account[]).flatMap((acc) => acc.tradeData || [])
    .reduce((acc: { [key: string]: GroupedTrade }, trade: TradeData) => {
      if (!acc[trade.date]) acc[trade.date] = { date: trade.date, trades: [], profit: 0, tradeLength: 0 };
      acc[trade.date].trades.push(trade);
      acc[trade.date].profit += trade.Profit;
      acc[trade.date].tradeLength += 1;
      return acc;
    }, {});

  const calendarData = Object.values(groupedTrades);

  const formatDate = (date: Date) => date.toISOString().split("T")[0];

  const [selectedDate, setSelectedDate] = useState<string>(formatDate(new Date()));
  const [showCalendar, setShowCalendar] = useState<boolean>(false);
  const [selectedYear, setSelectedYear] = useState<number>(new Date().getFullYear());
  const [selectedMonth, setSelectedMonth] = useState<number>(new Date().getMonth());

  const calendarRef = useRef<HTMLDivElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);
  const [dropdownPosition, setDropdownPosition] = useState({ top: 0, left: 0 });
  const today = formatDate(new Date());

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (calendarRef.current && !calendarRef.current.contains(e.target as Node) && 
          buttonRef.current && !buttonRef.current.contains(e.target as Node)) {
        setShowCalendar(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const updateDropdownPosition = () => {
    if (buttonRef.current) {
      const rect = buttonRef.current.getBoundingClientRect();
      const isMobile = window.innerWidth < 640;
      const padding = 16;
      const viewportWidth = window.innerWidth;
      const viewportHeight = window.innerHeight;
      const calendarWidth = Math.min(280, viewportWidth - padding * 2);
      const calendarHeight = 350;

      const desiredTop = rect.bottom + 8;
      const safeTop = Math.max(padding, Math.min(desiredTop, viewportHeight - calendarHeight - padding));

      if (isMobile) {
        const centeredLeft = (viewportWidth - calendarWidth) / 2;

        setDropdownPosition({
          top: safeTop,
          left: Math.max(padding, centeredLeft),
        });
      } else {
        const desiredLeft = rect.right - calendarWidth;
        const safeLeft = Math.max(padding, Math.min(desiredLeft, viewportWidth - calendarWidth - padding));

        setDropdownPosition({
          top: safeTop,
          left: safeLeft,
        });
      }
    }
  };

  useEffect(() => {
    if (showCalendar) {
      updateDropdownPosition();

      const handleScroll = () => {
        updateDropdownPosition();
      };

      const handleResize = () => {
        updateDropdownPosition();
      };

      window.addEventListener('scroll', handleScroll, true);
      window.addEventListener('resize', handleResize);
      window.addEventListener('orientationchange', handleResize);

      return () => {
        window.removeEventListener('scroll', handleScroll, true);
        window.removeEventListener('resize', handleResize);
        window.removeEventListener('orientationchange', handleResize);
      };
    }
  }, [showCalendar]);

  const changeDate = (days: number) => {
    const newDate = new Date(selectedDate);
    newDate.setDate(newDate.getDate() + days);
    const formattedDate = formatDate(newDate);
    if (days === 1 && formattedDate > today) return;
    setSelectedDate(formattedDate);
  };

  const todayData = useMemo(() => {
    return selectedAccounts.flatMap(acc =>
      acc.tradeData?.filter(trade => trade.date === selectedDate) || []
    );
  }, [selectedAccounts, selectedDate]);

  const data = useMemo(() => {
    let cumulativeProfit = 0;
    return [
      { time: "", value: 0, Item: "" },
      ...todayData.map(trade => {
        cumulativeProfit += trade.Profit;
        return {
          time: (trade.time || "00:00").slice(0, 5),
          value: parseFloat(cumulativeProfit.toFixed(2)),
          Item: trade.Item || "-"
        };
      })
    ];
  }, [todayData]);

  const nonCumulativeData = useMemo(() => [
    { time: "", value: 0, Item: "" },
    ...todayData.map(trade => ({
      time: (trade.time || "00:00").slice(0, 5),
      value: parseFloat(trade.Profit.toFixed(2)),
      Item: trade.Item || "-",
    })),
  ], [todayData]);

  const winrate = todayData.length ? ((todayData.filter(t => t.Profit > 0).length / todayData.length) * 100).toFixed(2) : "0.00";
  const metrics = calculateRiskRewardRatio(todayData);
  const totalPnL = todayData.reduce((total, { Profit }) => total + Profit, 0);
  const winCount = todayData.filter(t => t.Profit > 0).length;
  const lossCount = todayData.filter(t => t.Profit < 0).length;

  const bestTrade = todayData.length > 0 ? Math.max(...todayData.map(t => t.Profit)) : 0;
  const worstTrade = todayData.length > 0 ? Math.min(...todayData.map(t => t.Profit)) : 0;

  const daysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();

  const getDayProfit = (day: number): number | null => {
    const dateStr = `${selectedYear}-${(selectedMonth + 1).toString().padStart(2, "0")}-${day.toString().padStart(2, "0")}`;
    const dayData = calendarData.find((d) => d.date === dateStr);
    return dayData ? dayData.profit : null;
  };

  const renderCalendar = () => {
    const days = daysInMonth(selectedYear, selectedMonth);
    const firstDayIndex = new Date(selectedYear, selectedMonth, 1).getDay();
    const cells: React.ReactElement[] = [];

    for (let i = 0; i < firstDayIndex; i++) {
      cells.push(<div key={`empty-${i}`} className="h-8" />);
    }

    for (let day = 1; day <= days; day++) {
      const dateStr = `${selectedYear}-${(selectedMonth + 1).toString().padStart(2, "0")}-${day.toString().padStart(2, "0")}`;
      const profit = getDayProfit(day);
      const isSelected = dateStr === selectedDate;
      const isToday = dateStr === today;

      cells.push(
        <button
          key={day}
          onClick={() => {
            setSelectedDate(dateStr);
            setShowCalendar(false);
          }}
          className={`h-8 w-8 rounded-lg text-xs font-medium flex items-center justify-center transition-all ${
            isSelected
              ? "bg-primary text-primary-foreground"
              : profit !== null
                ? profit >= 0
                  ? "bg-profit/20 text-profit hover:bg-profit/30"
                  : "bg-loss/20 text-loss hover:bg-loss/30"
                : isToday
                  ? "bg-muted text-foreground"
                  : "text-muted-foreground hover:bg-muted/50"
          }`}
        >
          {day}
        </button>
      );
    }

    return cells;
  };

  const handlePrevMonth = () => {
    if (selectedMonth === 0) {
      setSelectedYear((prev) => prev - 1);
      setSelectedMonth(11);
    } else {
      setSelectedMonth((prev) => prev - 1);
    }
  };

  const handleNextMonth = () => {
    if (selectedMonth === 11) {
      setSelectedYear((prev) => prev + 1);
      setSelectedMonth(0);
    } else {
      setSelectedMonth((prev) => prev + 1);
    }
  };

  const selectedDateObj = new Date(selectedDate);
  const isWeekend = selectedDateObj.getDay() === 0 || selectedDateObj.getDay() === 6;

  const dashWidgetProps = {
    data,
    pnl: parseFloat(totalPnL.toFixed(2)),
    winrate: parseFloat(winrate),
    winners: winCount,
    losers: lossCount,
    profitF: calculateProfitFactor(todayData),
    avgProfits: parseFloat(metrics.avgWin),
    avgLoses: parseFloat(metrics.avgLoss),
    rrRatio: metrics.rrRatio,
    accBal: parseFloat(calculateBalance(selectedAccounts).toFixed(2)),
    totalProfits: todayData.reduce((sum, trade) => trade.Profit > 0 ? sum + trade.Profit : sum, 0),
    totalLoses: todayData.reduce((sum, trade) => trade.Profit < 0 ? sum + trade.Profit : sum, 0),
  };

  return (
    <div className="space-y-4">
      <DashWidgets {...dashWidgetProps} />

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-4">
        {/* Left Column - Date Picker + Trade History + Insight Tiles */}
        <div className="xl:col-span-2 space-y-4">
          {/* Date Navigation Header */}
          <div className="bg-card/50 backdrop-blur-sm border border-border/50 rounded-2xl p-4 overflow-visible">
            <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center">
                  <Calendar className="w-5 h-5 text-primary" />
                </div>
                <div>
                  <h2 className="text-base font-semibold text-foreground">
                    {selectedDateObj.toLocaleDateString("en-US", { weekday: "long" })}
                  </h2>
                  <p className="text-sm text-muted-foreground">
                    {selectedDateObj.toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" })}
                  </p>
                </div>
              </div>

              <div className="flex items-center gap-2">
                <button
                  onClick={() => changeDate(-1)}
                  className="w-8 h-8 rounded-lg bg-muted/50 flex items-center justify-center hover:bg-muted transition-colors"
                >
                  <ChevronLeft className="w-4 h-4 text-foreground" />
                </button>

                <div className="relative">
                  <button
                    ref={buttonRef}
                    onClick={() => setShowCalendar(!showCalendar)}
                    className="px-3 py-1.5 rounded-lg bg-primary/10 text-primary font-medium text-sm hover:bg-primary/15 transition-colors flex items-center gap-1"
                  >
                    <span>{selectedDateObj.toLocaleDateString("en-US", { month: "short", day: "numeric" })}</span>
                    <ChevronRight className={`w-4 h-4 transition-transform ${showCalendar ? "rotate-90" : ""}`} />
                  </button>

                  {showCalendar && typeof document !== 'undefined' && createPortal(
                    <AnimatePresence>
                      <motion.div
                        ref={calendarRef}
                        initial={{ opacity: 0, y: 8 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: 8 }}
                        style={{
                          position: 'fixed',
                          top: dropdownPosition.top,
                          left: dropdownPosition.left,
                          zIndex: 9999,
                        }}
                        className="bg-card border border-border rounded-xl p-4 shadow-2xl w-[280px] max-w-[calc(100vw-2rem)] max-h-[calc(100vh-2rem)] overflow-auto"
                      >
                        <div className="flex items-center justify-between mb-3">
                          <button
                            onClick={handlePrevMonth}
                            className="p-1 rounded hover:bg-muted transition-colors"
                          >
                            <ChevronLeft className="w-4 h-4 text-muted-foreground" />
                          </button>
                          <span className="text-sm font-semibold text-foreground">
                            {new Date(selectedYear, selectedMonth).toLocaleDateString("en-US", { month: "long", year: "numeric" })}
                          </span>
                          <button
                            onClick={handleNextMonth}
                            className="p-1 rounded hover:bg-muted transition-colors"
                          >
                            <ChevronRight className="w-4 h-4 text-muted-foreground" />
                          </button>
                        </div>

                        <div className="grid grid-cols-7 gap-1 mb-2">
                          {["S", "M", "T", "W", "T", "F", "S"].map((d, i) => (
                            <div key={i} className="h-6 flex items-center justify-center text-xs font-medium text-muted-foreground">
                              {d}
                            </div>
                          ))}
                        </div>

                        <div className="grid grid-cols-7 gap-1">
                          {renderCalendar()}
                        </div>

                        <div className="flex items-center justify-center gap-4 mt-3 pt-3 border-t border-border">
                          <div className="flex items-center gap-1">
                            <span className="w-2 h-2 rounded-sm bg-profit" />
                            <span className="text-xs text-muted-foreground">Profit</span>
                          </div>
                          <div className="flex items-center gap-1">
                            <span className="w-2 h-2 rounded-sm bg-loss" />
                            <span className="text-xs text-muted-foreground">Loss</span>
                          </div>
                        </div>
                      </motion.div>
                    </AnimatePresence>,
                    document.body
                  )}
                </div>

                <button
                  onClick={() => changeDate(1)}
                  disabled={selectedDate === today}
                  className={`w-8 h-8 rounded-lg bg-muted/50 flex items-center justify-center hover:bg-muted transition-colors ${selectedDate === today ? "opacity-40 cursor-not-allowed" : ""}`}
                >
                  <ChevronRight className="w-4 h-4 text-foreground" />
                </button>
              </div>
            </div>
          </div>

          {/* Trade History Table */}
          <div className="bg-card/50 backdrop-blur-sm border border-border/50 rounded-2xl p-4">
            <h3 className="text-sm font-semibold text-foreground mb-3 flex items-center gap-2">
              <Clock className="w-4 h-4 text-primary" />
              Trade History
            </h3>

            {todayData.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-8 text-center">
                <div className="w-12 h-12 rounded-xl bg-muted/50 flex items-center justify-center mb-3">
                  <Calendar className="w-5 h-5 text-muted-foreground" />
                </div>
                <p className="text-muted-foreground text-sm">No trades on this day</p>
              </div>
            ) : (
              <div className="overflow-x-auto -mx-4 px-4">
                <table className="w-full min-w-[400px]">
                  <thead>
                    <tr className="border-b border-border">
                      <th className="px-3 py-2 text-left text-xs font-semibold text-muted-foreground uppercase">Time</th>
                      <th className="px-3 py-2 text-left text-xs font-semibold text-muted-foreground uppercase">Symbol</th>
                      <th className="px-3 py-2 text-left text-xs font-semibold text-muted-foreground uppercase">Side</th>
