            await newAsAc.save();

            const sendReq = await fetch("http://auto-sync-backend-env.ap-south-1.elasticbeanstalk.com/tytusersasqwzxerdfcv/verify/syncAcc", {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
