    },
    { 
      label: 'Avg Daily Net P&L', 
      value: formatValue(calculations.avgDailyNetPnL, true),
      icon: DollarSign,
      category: 'pnl',
      variant: (calculations.avgDailyNetPnL || 0) >= 0 ? 'profit' : 'loss'
    },
    { 
      label: 'Planned R-Multiple', 
      value: `${calculations.avgPlannedRMultiple ?? 0}R`,
      icon: Target,
