              <XAxis
                type="number"
                stroke="var(--muted-foreground)"
                tick={{ fill: "var(--muted-foreground)", fontSize: 10 }}
                tickFormatter={formatCompact}
                tickLine={false}
                axisLine={false}
                opacity={0.6}
              />
              <YAxis
                type="category"
                dataKey="symbol"
                stroke="var(--muted-foreground)"
                tick={{ fill: "var(--muted-foreground)", fontSize: 10 }}
                tickLine={false}
                axisLine={false}
                width={60}
                opacity={0.6}
              />
              <Tooltip content={<CustomTooltip />} cursor={{ fill: 'var(--muted)', opacity: 0.1 }} />
