"use client"

import { cn } from "@/lib/utils"
import { TrendingUp, TrendingDown, AlertTriangle, Clock } from "lucide-react"

interface ProgressBarProps {
  label: string
  value: number
  maxValue: number
  type: "profit" | "drawdown" | "daily"
  targetLabel?: string
}

function ProgressBar({ label, value, maxValue, type, targetLabel }: ProgressBarProps) {
  const percentage = Math.min(Math.max((value / maxValue) * 100, 0), 100)

  const getBarColor = () => {
    if (type === "profit") {
      if (percentage >= 80) return "bg-profit"
      return "bg-primary"
    } else {
      if (percentage >= 85) return "bg-loss"
      if (percentage >= 60) return "bg-warning"
      return "bg-primary"
    }
  }

  const getBgColor = () => {
    if (type === "profit") {
      return "bg-primary/10"
    } else {
      if (percentage >= 85) return "bg-loss/10"
      if (percentage >= 60) return "bg-warning/10"
      return "bg-primary/10"
    }
  }

  const getTextColor = () => {
    if (type === "profit") {
      if (percentage >= 80) return "text-profit"
      return "text-primary"
    } else {
      if (percentage >= 85) return "text-loss"
      if (percentage >= 60) return "text-warning"
      return "text-foreground"
    }
  }

  const getIcon = () => {
    if (type === "profit") return TrendingUp
    if (type === "daily") return Clock
    return TrendingDown
  }

  const Icon = getIcon()

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Icon className={cn("w-4 h-4", getTextColor())} />
          <span className="text-sm font-medium text-foreground">{label}</span>
        </div>
        <div className="flex items-center gap-2">
          <span className={cn("text-lg font-bold tabular-nums", getTextColor())}>
            {percentage.toFixed(1)}%
          </span>
          {targetLabel && (
            <span className="text-xs text-muted-foreground">
              {targetLabel}
            </span>
          )}
        </div>
      </div>

      <div className={cn("h-3 rounded-full overflow-hidden", getBgColor())}>
        <div
          className={cn(
            "h-full rounded-full transition-all duration-500 ease-out",
            getBarColor()
          )}
          style={{ width: `${percentage}%` }}
        />
      </div>

      {(type === "drawdown" || type === "daily") && percentage >= 60 && (
        <div className={cn(
          "flex items-center gap-2 text-xs",
          percentage >= 85 ? "text-loss" : "text-warning"
        )}>
          <AlertTriangle className="w-3.5 h-3.5" />
          {percentage >= 85 
            ? `Critical: Approaching max ${type === "daily" ? "daily " : ""}drawdown limit!`
            : `Warning: ${type === "daily" ? "Daily d" : "D"}rawdown exceeds safe zone`
          }
        </div>
      )}
    </div>
  )
}

interface PropFirmProgressBarsProps {
  currentEquity: number
  startingBalance: number
  profitTarget: number
  maxDrawdown: number
  peakEquity: number
  dailyDrawdown?: number | null
  dailyLoss?: number
}

export default function PropFirmProgressBars({
  currentEquity,
  startingBalance,
  profitTarget,
  maxDrawdown,
  peakEquity,
  dailyDrawdown,
  dailyLoss = 0,
}: PropFirmProgressBarsProps) {
  const profitTargetValue = startingBalance * (profitTarget / 100)
  const currentProfit = currentEquity - startingBalance
  const profitProgress = Math.max(currentProfit, 0)

  const maxDrawdownValue = startingBalance * (maxDrawdown / 100)
  const drawdownFromPeak = peakEquity - currentEquity
  const drawdownUsed = Math.max(drawdownFromPeak, 0)

  const dailyDrawdownValue = dailyDrawdown ? startingBalance * (dailyDrawdown / 100) : null

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="bg-card border border-border/50 rounded-xl p-5">
          <ProgressBar
            label="Target Progress"
            value={profitProgress}
            maxValue={profitTargetValue}
            type="profit"
            targetLabel={`of ${profitTarget}% target`}
          />
          <div className="mt-4 pt-4 border-t border-border/30 flex justify-between text-sm">
            <div>
              <span className="text-muted-foreground">Current Profit</span>
              <p className={cn(
                "text-lg font-bold tabular-nums",
                currentProfit >= 0 ? "text-profit" : "text-loss"
              )}>
                {currentProfit >= 0 ? "+" : ""}{currentProfit.toLocaleString('en-US', { style: 'currency', currency: 'USD' })}
              </p>
            </div>
            <div className="text-right">
              <span className="text-muted-foreground">Target</span>
              <p className="text-lg font-bold tabular-nums text-foreground">
                {profitTargetValue.toLocaleString('en-US', { style: 'currency', currency: 'USD' })}
              </p>
            </div>
          </div>
        </div>

        <div className="bg-card border border-border/50 rounded-xl p-5">
          <ProgressBar
            label="Max Drawdown Used"
            value={drawdownUsed}
            maxValue={maxDrawdownValue}
            type="drawdown"
            targetLabel={`of ${maxDrawdown}% max`}
          />
          <div className="mt-4 pt-4 border-t border-border/30 flex justify-between text-sm">
            <div>
              <span className="text-muted-foreground">Drawdown Used</span>
              <p className={cn(
                "text-lg font-bold tabular-nums",
                drawdownUsed > 0 ? "text-loss" : "text-foreground"
              )}>
                {drawdownUsed > 0 ? "-" : ""}{drawdownUsed.toLocaleString('en-US', { style: 'currency', currency: 'USD' })}
              </p>
            </div>
            <div className="text-right">
              <span className="text-muted-foreground">Max Allowed</span>
              <p className="text-lg font-bold tabular-nums text-foreground">
                {maxDrawdownValue.toLocaleString('en-US', { style: 'currency', currency: 'USD' })}
              </p>
            </div>
          </div>
        </div>
      </div>

      {dailyDrawdownValue && (
        <div className="bg-card border border-border/50 rounded-xl p-5">
          <ProgressBar
            label="Daily Drawdown Used"
            value={dailyLoss}
            maxValue={dailyDrawdownValue}
            type="daily"
            targetLabel={`of ${dailyDrawdown}% daily limit`}
          />
          <div className="mt-4 pt-4 border-t border-border/30 flex justify-between text-sm">
            <div>
              <span className="text-muted-foreground">Today&apos;s Loss</span>
              <p className={cn(
                "text-lg font-bold tabular-nums",
                dailyLoss > 0 ? "text-loss" : "text-foreground"
              )}>
                {dailyLoss > 0 ? "-" : ""}{dailyLoss.toLocaleString('en-US', { style: 'currency', currency: 'USD' })}
              </p>
            </div>
            <div className="text-right">
              <span className="text-muted-foreground">Daily Limit</span>
              <p className="text-lg font-bold tabular-nums text-foreground">
                {dailyDrawdownValue.toLocaleString('en-US', { style: 'currency', currency: 'USD' })}
              </p>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

src/components/dashboard-components/Acco.content:
"use client";

import { useState, useRef, useEffect, useMemo } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { 
  DollarSign, 
  ChevronDown, 
  Check, 
  CheckSquare,
  Square,
  Plus,
  Building2,
  Wallet,
  Settings,
  Zap,
  Trash2
} from "lucide-react";
import { cn } from "@/lib/utils";
import useAccountDetails from "@/store/accountdetails";
import calendarPopUp from "@/store/calendarPopUp";
import usePropFirmStore from "@/store/propFirmStore";

const brokerIcons: Record<string, string> = {
  "MetaTrader 5": "MT5",
  "MetaTrader 4": "MT4",
  "Zerodha": "ZD",
  "Binance": "BN",
  "Upstox": "UP",
  "Angel One": "AO",
};

const AccountsDropdown = () => {
  const [isOpen, setIsOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const { accounts, updateAccView, checkAll } = useAccountDetails();
  const { setAddAcc, setDeleteAccData, setDeleteAcc } = calendarPopUp();
  const { isEnabled: isPropFirmMode } = usePropFirmStore();

  const filteredAccounts = useMemo(() => {
    return accounts.filter(acc => {
      const isAccountPropFirm = acc.isPropFirm === true;
      return isPropFirmMode ? isAccountPropFirm : !isAccountPropFirm;
    });
  }, [accounts, isPropFirmMode]);

  const selectedCount = filteredAccounts.filter(acc => acc.checked).length;
  const allSelected = filteredAccounts.length > 0 && selectedCount === filteredAccounts.length;
  const someSelected = selectedCount > 0 && selectedCount < filteredAccounts.length;

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const handleToggleAccount = async (accountName: string) => {
    await updateAccView(accountName);
  };

  const handleToggleAll = async () => {
    // For filtered accounts, we should only toggle accounts in the current mode
    // Since the API toggles all accounts, we handle this locally for better UX
    for (const account of filteredAccounts) {
      if (allSelected) {
        // Deselect all in current mode
        if (account.checked) {
          await updateAccView(account.accountName);
        }
      } else {
        // Select all in current mode
        if (!account.checked) {
          await updateAccView(account.accountName);
        }
      }
    }
  };

  const handleDeleteAccount = (e: React.MouseEvent, account: any) => {
    e.stopPropagation();
    setDeleteAccData(account);
    setDeleteAcc();
    setIsOpen(false);
  };

  const getDisplayText = () => {
    if (filteredAccounts.length === 0) return isPropFirmMode ? "No Prop Accounts" : "No Accounts";
    if (selectedCount === 0) return "No accounts";
    if (allSelected) return isPropFirmMode ? "All Prop Accounts" : "All Accounts";
    if (selectedCount === 1) {
      const selected = filteredAccounts.find(acc => acc.checked);
      return selected?.accountName || "1 Account";
    }
    return `${selectedCount} Accounts`;
  };

  return (
    <div className="relative" ref={dropdownRef}>
      <button
        onClick={() => setIsOpen(!isOpen)}
        className={cn(
          "flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-medium transition-all duration-200",
          "border border-border bg-card hover:bg-muted/50",
          isOpen && "border-primary/50 ring-2 ring-primary/20"
        )}
      >
        {isPropFirmMode ? (
          <Zap className="w-4 h-4 text-amber-500" />
        ) : (
          <DollarSign className="w-4 h-4 text-primary" />
        )}
        <span className="hidden sm:inline text-foreground">{getDisplayText()}</span>
        <ChevronDown className={cn(
          "w-3.5 h-3.5 text-muted-foreground transition-transform duration-200",
          isOpen && "rotate-180"
        )} />
      </button>

      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, y: -8, scale: 0.96 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: -8, scale: 0.96 }}
            transition={{ duration: 0.15, ease: "easeOut" }}
            className="absolute top-full right-0 mt-2 w-72 bg-card border border-border rounded-xl shadow-xl z-50 overflow-hidden"
          >
            {/* Header */}
            <div className="px-4 py-3 border-b border-border bg-muted/30">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  {isPropFirmMode ? (
                    <Zap className="w-4 h-4 text-amber-500" />
                  ) : (
                    <Wallet className="w-4 h-4 text-primary" />
                  )}
                  <span className="font-semibold text-foreground text-sm">
                    {isPropFirmMode ? "Prop Firm Accounts" : "Trading Accounts"}
                  </span>
                </div>
                <span className="text-xs text-muted-foreground px-2 py-0.5 bg-muted rounded-full">
                  {selectedCount}/{filteredAccounts.length}
                </span>
              </div>
            </div>

            {filteredAccounts.length === 0 ? (
              <div className="p-6 text-center">
                <div className="w-12 h-12 mx-auto mb-3 rounded-xl bg-muted/50 flex items-center justify-center">
                  {isPropFirmMode ? (
                    <Zap className="w-6 h-6 text-muted-foreground" />
                  ) : (
                    <Building2 className="w-6 h-6 text-muted-foreground" />
                  )}
                </div>
                <p className="text-sm text-muted-foreground mb-4">
                  {isPropFirmMode ? "No prop firm accounts yet" : "No accounts added yet"}
                </p>
                <button
                  onClick={() => {
                    setIsOpen(false);
                    setAddAcc();
                  }}
                  className="inline-flex items-center gap-2 px-4 py-2 rounded-lg bg-primary text-white text-sm font-medium hover:bg-primary-dark transition-colors"
                >
                  <Plus className="w-4 h-4" />
                  Add Account
                </button>
              </div>
            ) : (
              <>
                {/* Select All */}
                <div className="px-2 py-2 border-b border-border">
                  <button
                    onClick={handleToggleAll}
                    className="w-full flex items-center gap-3 px-3 py-2.5 rounded-lg hover:bg-muted/50 transition-colors group"
                  >
                    <div className={cn(
                      "w-5 h-5 rounded flex items-center justify-center transition-all",
                      allSelected 
                        ? "bg-primary text-white" 
                        : someSelected
                          ? "bg-primary/50 text-white"
                          : "border-2 border-border group-hover:border-primary/50"
                    )}>
                      {(allSelected || someSelected) && <Check className="w-3.5 h-3.5" />}
                    </div>
                    <span className="font-medium text-sm text-foreground">Select All</span>
                    <span className="ml-auto text-xs text-muted-foreground">
                      {allSelected ? "Deselect all" : "Select all"}
                    </span>
                  </button>
                </div>

                {/* Account List */}
                <div className="max-h-64 overflow-y-auto p-2 space-y-1">
                  {filteredAccounts.map((account) => (
                    <div
                      key={account._id || account.accountName}
                      className="w-full flex items-center gap-3 px-3 py-2.5 rounded-lg hover:bg-muted/50 transition-colors group"
                    >
                      {/* Checkbox */}
                      <button
                        onClick={() => handleToggleAccount(account.accountName)}
                        className={cn(
                          "w-5 h-5 rounded flex items-center justify-center transition-all flex-shrink-0 cursor-pointer",
                          account.checked 
                            ? "bg-primary text-white" 
                            : "border-2 border-border group-hover:border-primary/50"
                        )}
                      >
                        {account.checked && <Check className="w-3.5 h-3.5" />}
                      </button>

                      {/* Broker Icon */}
                      <div 
                        onClick={() => handleToggleAccount(account.accountName)}
                        className="w-8 h-8 rounded-lg bg-gradient-to-br from-blue-500/20 to-blue-600/20 flex items-center justify-center flex-shrink-0 cursor-pointer"
                      >
                        <span className="text-[10px] font-bold text-blue-400">
                          {brokerIcons[account.broker || ""] || "AC"}
                        </span>
                      </div>

                      {/* Account Info */}
                      <div 
                        onClick={() => handleToggleAccount(account.accountName)}
                        className="flex-1 min-w-0 text-left cursor-pointer"
                      >
                        <p className="text-sm font-medium text-foreground truncate">
                          {account.accountName}
                        </p>
                        <p className="text-xs text-muted-foreground truncate">
                          {account.broker || account.accountType || "Trading Account"}
                        </p>
                      </div>

                      {/* Balance */}
                      {account.accountBalance && (
                        <span 
                          onClick={() => handleToggleAccount(account.accountName)}
                          className="text-xs font-medium text-profit flex-shrink-0 cursor-pointer"
                        >
                          ${Number(account.accountBalance).toLocaleString()}
                        </span>
                      )}

                      {/* Delete Button */}
                      <button
                        onClick={(e) => handleDeleteAccount(e, account)}
                        className="p-1.5 rounded-lg opacity-0 group-hover:opacity-100 hover:bg-red-500/10 transition-all flex-shrink-0"
                        title="Delete account"
                      >
                        <Trash2 className="w-3.5 h-3.5 text-muted-foreground hover:text-red-500 transition-colors" />
                      </button>
                    </div>
                  ))}
                </div>

                {/* Footer */}
                <div className="px-2 py-2 border-t border-border">
                  <button
                    onClick={() => {
                      setIsOpen(false);
                      setAddAcc();
                    }}
                    className="w-full flex items-center justify-center gap-2 px-3 py-2.5 rounded-lg text-sm font-medium text-muted-foreground hover:text-foreground hover:bg-muted/50 transition-colors"
                  >
                    <Settings className="w-4 h-4" />
                    Manage Accounts
                  </button>
                </div>
              </>
            )}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default AccountsDropdown;

src/components/dashboard-components/Curr.content:
"use client";

import { useState, useRef, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { 
  ChevronDown, 
  Check,
  DollarSign,
  IndianRupee,
  Percent,
  Target
} from "lucide-react";
import { cn } from "@/lib/utils";
import useCurrencyStore, { CurrencyType, currencyLabels } from "@/store/currencyStore";

const currencyOptions: { id: CurrencyType; label: string; description: string; icon: React.ReactNode }[] = [
  { id: "USD", label: "Dollar", description: "US Dollar ($)", icon: <DollarSign className="w-4 h-4" /> },
  { id: "INR", label: "Rupees", description: "Indian Rupee (₹)", icon: <IndianRupee className="w-4 h-4" /> },
  { id: "PERCENT", label: "Percentage", description: "Show as %", icon: <Percent className="w-4 h-4" /> },
  { id: "R", label: "R Factor", description: "Risk multiple", icon: <Target className="w-4 h-4" /> },
];

const CurrencyDropdown = () => {
  const [isOpen, setIsOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const { currency, setCurrency } = useCurrencyStore();

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const handleSelectCurrency = (currencyId: CurrencyType) => {
    setCurrency(currencyId);
    setIsOpen(false);
  };

  const selectedOption = currencyOptions.find(opt => opt.id === currency);
  const getDisplayIcon = () => {
    switch (currency) {
      case "USD": return <DollarSign className="w-4 h-4" />;
      case "INR": return <IndianRupee className="w-4 h-4" />;
      case "PERCENT": return <Percent className="w-4 h-4" />;
      case "R": return <Target className="w-4 h-4" />;
      default: return <DollarSign className="w-4 h-4" />;
    }
  };

  return (
    <div className="relative" ref={dropdownRef}>
      <button
        onClick={() => setIsOpen(!isOpen)}
        className={cn(
          "flex items-center gap-1.5 px-2.5 py-2 rounded-lg text-sm font-medium transition-all duration-200",
          "border border-border bg-card hover:bg-muted/50",
          isOpen && "border-primary/50 ring-2 ring-primary/20"
        )}
      >
        <span className="text-primary">{getDisplayIcon()}</span>
        <ChevronDown className={cn(
          "w-3 h-3 text-muted-foreground transition-transform duration-200",
          isOpen && "rotate-180"
        )} />
      </button>

      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, y: -8, scale: 0.96 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: -8, scale: 0.96 }}
            transition={{ duration: 0.15, ease: "easeOut" }}
            className="absolute top-full right-0 mt-2 w-56 bg-card border border-border rounded-xl shadow-xl z-50 overflow-hidden"
          >
            {/* Header */}
            <div className="px-4 py-3 border-b border-border bg-muted/30">
              <span className="font-semibold text-foreground text-sm">Display Currency</span>
            </div>

            {/* Currency Options */}
            <div className="p-2 space-y-1">
              {currencyOptions.map((option) => (
                <button
                  key={option.id}
                  onClick={() => handleSelectCurrency(option.id)}
                  className={cn(
                    "w-full flex items-center gap-3 px-3 py-2.5 rounded-lg transition-colors group",
                    currency === option.id 
                      ? "bg-primary/10 text-primary" 
                      : "hover:bg-muted/50 text-foreground"
                  )}
                >
                  {/* Icon */}
                  <div className={cn(
                    "w-8 h-8 rounded-lg flex items-center justify-center transition-all",
                    currency === option.id 
                      ? "bg-primary text-white" 
                      : "bg-muted/50 text-muted-foreground group-hover:bg-muted"
                  )}>
                    {option.icon}
                  </div>

                  {/* Label & Description */}
                  <div className="flex-1 text-left">
                    <p className="text-sm font-medium">{option.label}</p>
                    <p className="text-xs text-muted-foreground">{option.description}</p>
                  </div>

                  {/* Checkmark */}
                  {currency === option.id && (
                    <Check className="w-4 h-4 text-primary" />
                  )}
                </button>
              ))}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default CurrencyDropdown;

