                    className="w-full px-4 py-3 bg-background/50 border border-border/50 rounded-xl text-foreground placeholder:text-muted-foreground/50 focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary/40 transition-all text-sm"
                  />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-[11px] font-medium text-muted-foreground uppercase tracking-wider mb-2">
                    <Receipt className="w-3 h-3 inline mr-1" />
                    Commission
                  </label>
                  <input
                    type="number"
                    step="any"
                    placeholder="0.00"
                    value={activeTrade.commission}
                    onChange={(e) => updateTrade(activeTrade.id, "commission", e.target.value)}
                    className="w-full px-4 py-3 bg-background/50 border border-border/50 rounded-xl text-foreground placeholder:text-muted-foreground/50 focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary/40 transition-all text-sm"
                  />
                </div>
                <div>
                  <label className="block text-[11px] font-medium text-muted-foreground uppercase tracking-wider mb-2">Other Charges</label>
                  <input
                    type="number"
                    step="any"
                    placeholder="0.00"
                    value={activeTrade.otherCharges}
                    onChange={(e) => updateTrade(activeTrade.id, "otherCharges", e.target.value)}
                    className="w-full px-4 py-3 bg-background/50 border border-border/50 rounded-xl text-foreground placeholder:text-muted-foreground/50 focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary/40 transition-all text-sm"
                  />
                </div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* Add Another Trade */}
      {trades.length === 1 && (
        <button
          onClick={addNewTrade}
          className="w-full flex items-center justify-center gap-2 py-3 border border-dashed border-border/50 rounded-xl text-sm text-muted-foreground hover:text-foreground hover:border-primary/50 hover:bg-primary/5 transition-all"
        >
          <Plus className="w-4 h-4" />
          Add another trade
        </button>
      )}

      {/* Date Pickers */}
      <CustomDateTimePicker
        isOpen={showDatePicker === `entry-${activeTrade.id}`}
        onClose={() => setShowDatePicker(null)}
        onApply={(value: Date) => updateTrade(activeTrade.id, "entryDate", value.toISOString().slice(0, 16))}
      />
      <CustomDateTimePicker
        isOpen={showDatePicker === `exit-${activeTrade.id}`}
        onClose={() => setShowDatePicker(null)}
        onApply={(value: Date) => updateTrade(activeTrade.id, "exitDate", value.toISOString().slice(0, 16))}
      />
    </div>
  );
}

src/store/propFirmStore.ts.content:
"use client"
import { create } from "zustand"
import { persist } from "zustand/middleware"

export interface PropFirmSettings {
  startingBalance: number
  profitTargetPercent: number
  maxDrawdownPercent: number
  dailyDrawdownPercent: number | null
  challengeStartDate: string | null
}

export interface PropFirmState {
  isEnabled: boolean
  settings: PropFirmSettings
  peakEquity: number
  challengeStatus: "active" | "at_risk" | "breached" | "completed"

  toggleMode: () => void
  setEnabled: (enabled: boolean) => void
  updateSettings: (settings: Partial<PropFirmSettings>) => void
  resetChallenge: () => void
  updatePeakEquity: (equity: number) => void
  setChallengeStatus: (status: "active" | "at_risk" | "breached" | "completed") => void
}

const defaultSettings: PropFirmSettings = {
  startingBalance: 100000,
  profitTargetPercent: 8,
  maxDrawdownPercent: 10,
  dailyDrawdownPercent: 5,
  challengeStartDate: null,
}

const usePropFirmStore = create<PropFirmState>()(
  persist(
    (set, get) => ({
      isEnabled: false,
      settings: defaultSettings,
      peakEquity: defaultSettings.startingBalance,
      challengeStatus: "active",

      toggleMode: () => {
        const { isEnabled, settings } = get()
        if (!isEnabled) {
          set({ 
            isEnabled: true,
            peakEquity: settings.startingBalance,
            challengeStatus: "active",
            settings: {
              ...settings,
              challengeStartDate: settings.challengeStartDate || new Date().toISOString().split('T')[0]
            }
          })
        } else {
          set({ isEnabled: false })
        }
      },

      setEnabled: (enabled: boolean) => {
        const { settings } = get()
        if (enabled) {
          set({ 
            isEnabled: true,
            peakEquity: settings.startingBalance,
            challengeStatus: "active",
            settings: {
              ...settings,
              challengeStartDate: settings.challengeStartDate || new Date().toISOString().split('T')[0]
            }
          })
        } else {
          set({ isEnabled: false })
        }
      },

      updateSettings: (newSettings: Partial<PropFirmSettings>) => {
        const { settings, peakEquity } = get()
        const updatedSettings = { ...settings, ...newSettings }

        const startingBalanceChanged = newSettings.startingBalance !== undefined && 
                                        newSettings.startingBalance !== settings.startingBalance

        set({ 
          settings: updatedSettings,
          peakEquity: startingBalanceChanged ? updatedSettings.startingBalance : peakEquity
        })
      },

      resetChallenge: () => {
        const { settings } = get()
        set({
          peakEquity: settings.startingBalance,
          challengeStatus: "active",
          settings: {
            ...settings,
            challengeStartDate: new Date().toISOString().split('T')[0]
          }
        })
      },

      updatePeakEquity: (equity: number) => {
        const { peakEquity } = get()
        if (equity > peakEquity) {
          set({ peakEquity: equity })
        }
      },

      setChallengeStatus: (status) => set({ challengeStatus: status }),
    }),
    {
      name: "prop-firm-storage",
    }
  )
)

export default usePropFirmStore

