interface PropFirmSuggestionsProps {
  isCollapsed?: boolean
  onToggleCollapse?: () => void
}

export default function PropFirmSuggestions({ 
  isCollapsed: controlledCollapsed, 
  onToggleCollapse 
}: PropFirmSuggestionsProps = {}) {
  const [copied, setCopied] = useState(false)
  const [internalCollapsed, setInternalCollapsed] = useState(false)

  const isCollapsed = controlledCollapsed !== undefined ? controlledCollapsed : internalCollapsed
  const toggleCollapse = onToggleCollapse || (() => setInternalCollapsed(!internalCollapsed))

  const handleCopy = async () => {
    await navigator.clipboard.writeText(COUPON_CODE)
    setCopied(true)
    setTimeout(() => setCopied(false), 2000)
  }

  return (
    <div className="relative flex items-start gap-1">
      <button
        onClick={toggleCollapse}
        className={cn(
          "mt-3 z-10",
          "w-5 h-10 rounded-md",
          "bg-gray-100 dark:bg-white/10 border border-gray-200 dark:border-white/10",
          "hover:bg-blue-50 dark:hover:bg-blue-500/20 hover:border-blue-300 dark:hover:border-blue-500/30",
          "flex items-center justify-center",
          "transition-all duration-200",
          "shadow-sm"
        )}
        title={isCollapsed ? "Expand" : "Collapse"}
      >
        {isCollapsed ? (
          <ChevronLeft className="w-3 h-3 text-gray-500 dark:text-white/60" />
        ) : (
          <ChevronRight className="w-3 h-3 text-gray-500 dark:text-white/60" />
        )}
      </button>

      <AnimatePresence initial={false} mode="wait">
        {isCollapsed ? (
          <motion.div
            key="collapsed"
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: 20 }}
            transition={{ duration: 0.2, ease: "easeInOut" }}
            className={cn(
              "w-10 overflow-hidden rounded-xl border backdrop-blur-sm",
              "bg-white dark:bg-[#141414]",
              "border-gray-200 dark:border-white/10",
              "flex flex-col items-center justify-center py-4 cursor-pointer",
              "hover:bg-gray-50 dark:hover:bg-white/5"
            )}
            onClick={toggleCollapse}
          >
            <Award className="w-4 h-4 text-gray-600 dark:text-white/70 mb-2" />
            <span 
              className="text-[9px] font-bold text-gray-600 dark:text-white/70 whitespace-nowrap" 
              style={{ writingMode: 'vertical-lr' }}
            >
              Prop Firms
            </span>
          </motion.div>
        ) : (
          <motion.div
            key="expanded"
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: 20 }}
            transition={{ duration: 0.2, ease: "easeInOut" }}
            className={cn(
              "relative overflow-hidden rounded-xl border backdrop-blur-sm",
              "bg-white dark:bg-[#141414]",
              "border-gray-200 dark:border-white/10",
              "p-4"
            )}
          >
            <div className="absolute inset-0 bg-[url('data:image/svg+xml;base64,')] dark:bg-[url('data:image/svg+xml;base64,')] opacity-50" />

            <div className="relative min-w-[280px]">
              <div className="flex items-center gap-2 mb-4">
                <div className="w-8 h-8 rounded-lg bg-gray-100 dark:bg-white/10 border border-gray-200 dark:border-white/10 flex items-center justify-center">
                  <Award className="w-4 h-4 text-gray-600 dark:text-white/70" />
                </div>
                <div>
                  <h3 className="text-sm font-bold text-gray-900 dark:text-white">Prop Firms We Suggest</h3>
                  <p className="text-[10px] text-gray-500 dark:text-white/40">Top rated & trusted</p>
                </div>
              </div>

              <div className={cn(
                "mb-4 p-3 rounded-xl",
                "bg-gradient-to-r from-blue-500/10 to-blue-600/5 dark:from-blue-500/15 dark:to-blue-600/5",
                "border border-blue-500/20"
              )}>
                <div className="flex items-center gap-2 mb-2">
                  <Sparkles className="w-4 h-4 text-blue-600 dark:text-blue-400" />
                  <span className="text-xs font-bold text-blue-600 dark:text-blue-400">
                    {DISCOUNT}% OFF with our code!
                  </span>
                </div>
                <div className="flex items-center gap-2">
                  <code className="flex-1 px-3 py-2 bg-white dark:bg-black/30 border border-gray-200 dark:border-white/10 rounded-lg text-sm font-mono font-bold text-gray-900 dark:text-white tracking-wider">
                    {COUPON_CODE.toUpperCase()}
                  </code>
                  <button
                    onClick={handleCopy}
                    className={cn(
                      "p-2 rounded-lg border transition-all",
                      copied 
                        ? "bg-emerald-500 border-emerald-500 text-white" 
                        : "bg-blue-500 hover:bg-blue-600 border-blue-500 text-white"
                    )}
                  >
                    {copied ? <Check className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
                  </button>
                </div>
              </div>

              <div className="space-y-2">
                {PROP_FIRMS.map((firm) => (
                  <PropFirmCard key={firm.name} firm={firm} />
                ))}
              </div>

              <p className="mt-4 text-[10px] text-center text-gray-400 dark:text-white/30">
                We may earn a commission from these links
              </p>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  )
}

