                    )}
                    {playbook.preferredSymbols && playbook.preferredSymbols.length > 0 && (
                      <span className="px-2.5 py-1 rounded-lg bg-emerald-500/10 text-emerald-500 text-xs font-medium border border-emerald-500/20">
