    description: "Understanding how markets move in trends and ranges to trade with the flow.",
    category: "technical",
    readTime: "6 min",
    icon: Layers,
    content: [
      "Markets move in trends (uptrend, downtrend) or consolidation (range-bound). Understanding this is crucial.",
      "Uptrend: Higher highs and higher lows. Downtrend: Lower highs and lower lows.",
      "Trade with the trend on higher timeframes, and look for entries on lower timeframes.",
    ],
  },
  {
    id: "5",
    title: "Building a Trading Plan",
    description: "Create a comprehensive trading plan that defines your rules, strategies, and goals.",
    category: "strategy",
    readTime: "12 min",
    icon: BookOpen,
    content: [
      "A trading plan removes emotion and provides a clear roadmap for your trading activities.",
      "Key components: Trading goals, risk parameters, entry/exit rules, position sizing, and review process.",
      "Review and update your plan regularly based on performance and market conditions.",
    ],
  },
  {
    id: "6",
    title: "Stop Loss Strategies",
    description: "Different approaches to placing and managing stop losses effectively.",
    category: "risk",
    readTime: "7 min",
    icon: Target,
    content: [
      "Fixed stops: Set at a specific pip distance or percentage from entry.",
      "Technical stops: Placed below/above key support/resistance levels or swing points.",
      "Trailing stops: Move your stop loss to lock in profits as the trade moves in your favor.",
    ],
  },
  {
    id: "7",
    title: "Reading Candlestick Patterns",
    description: "Master the art of interpreting candlestick patterns for better trade entries.",
    category: "technical",
    readTime: "9 min",
    icon: Zap,
    content: [
      "Candlesticks show the open, high, low, and close of a time period at a glance.",
      "Reversal patterns: Hammer, shooting star, doji, engulfing patterns signal potential trend changes.",
      "Continuation patterns: Three white soldiers, three black crows, and marubozu confirm trend continuation.",
    ],
  },
  {
    id: "8",
    title: "Economic Calendar Trading",
    description: "How to use economic events and news releases in your trading strategy.",
    category: "fundamentals",
    readTime: "6 min",
    icon: BookOpen,
    content: [
      "High-impact news events can cause significant volatility and price movements.",
      "Key events: Interest rate decisions, employment data, GDP reports, and inflation figures.",
      "Consider staying flat during major news or use wider stops to avoid being stopped out by volatility.",
    ],
  },
];

const categories = [
  { id: "all" as Category, label: "All Topics", count: articles.length },
  { id: "technical" as Category, label: "Technical Analysis", count: articles.filter(a => a.category === "technical").length },
  { id: "risk" as Category, label: "Risk Management", count: articles.filter(a => a.category === "risk").length },
  { id: "strategy" as Category, label: "Strategy", count: articles.filter(a => a.category === "strategy").length },
  { id: "fundamentals" as Category, label: "Fundamentals", count: articles.filter(a => a.category === "fundamentals").length },
];

const KnowledgeHub = () => {
  const [selectedCategory, setSelectedCategory] = useState<Category>("all");
  const [searchQuery, setSearchQuery] = useState("");
  const [expandedArticle, setExpandedArticle] = useState<string | null>(null);

  const filteredArticles = articles.filter((article) => {
    const matchesCategory = selectedCategory === "all" || article.category === selectedCategory;
    const matchesSearch = article.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
      article.description.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  return (
    <div className="space-y-6">
      {/* Search and Filter */}
      <div className="flex flex-col sm:flex-row gap-4">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <input
            type="text"
            placeholder="Search articles..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-2.5 bg-card border border-border rounded-xl text-sm text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/50"
          />
        </div>
      </div>

      {/* Category Pills */}
      <div className="flex flex-wrap gap-2">
        {categories.map((cat) => (
          <button
            key={cat.id}
            onClick={() => setSelectedCategory(cat.id)}
            className={`px-4 py-2 rounded-xl text-sm font-medium transition-all ${
              selectedCategory === cat.id
                ? "bg-primary text-primary-foreground"
                : "bg-card border border-border text-muted-foreground hover:text-foreground hover:bg-muted"
            }`}
          >
            {cat.label}
            <span className={`ml-2 text-xs ${selectedCategory === cat.id ? "text-primary-foreground/70" : "text-muted-foreground"}`}>
              ({cat.count})
            </span>
          </button>
        ))}
      </div>

      {/* Articles Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {filteredArticles.map((article) => {
          const Icon = article.icon;
          const isExpanded = expandedArticle === article.id;

          return (
            <motion.div
              key={article.id}
              layout
              className="bg-card border border-border rounded-xl overflow-hidden hover:border-primary/30 transition-colors"
            >
              <button
                onClick={() => setExpandedArticle(isExpanded ? null : article.id)}
                className="w-full p-4 text-left"
              >
                <div className="flex items-start gap-4">
                  <div className="p-2.5 rounded-xl bg-primary/10 text-primary flex-shrink-0">
                    <Icon className="h-5 w-5" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center justify-between gap-2">
                      <h3 className="font-semibold text-foreground truncate">{article.title}</h3>
                      <ChevronRight className={`h-4 w-4 text-muted-foreground transition-transform flex-shrink-0 ${isExpanded ? "rotate-90" : ""}`} />
                    </div>
                    <p className="text-sm text-muted-foreground mt-1 line-clamp-2">{article.description}</p>
                    <div className="flex items-center gap-3 mt-3">
                      <span className="text-xs px-2 py-1 bg-muted rounded-md text-muted-foreground capitalize">
                        {article.category}
                      </span>
                      <span className="text-xs text-muted-foreground">{article.readTime} read</span>
                    </div>
                  </div>
                </div>
              </button>

              {/* Expanded Content */}
              {isExpanded && (
                <motion.div
                  initial={{ opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: "auto" }}
                  exit={{ opacity: 0, height: 0 }}
                  className="border-t border-border"
                >
                  <div className="p-4 space-y-3">
                    {article.content.map((paragraph, idx) => (
                      <p key={idx} className="text-sm text-muted-foreground leading-relaxed">
                        {paragraph}
                      </p>
                    ))}
                  </div>
                </motion.div>
              )}
            </motion.div>
          );
        })}
      </div>

      {filteredArticles.length === 0 && (
        <div className="text-center py-12">
          <BookOpen className="h-12 w-12 text-muted-foreground mx-auto mb-3" />
          <p className="text-muted-foreground">No articles found matching your search.</p>
        </div>
      )}
    </div>
  );
};

export default KnowledgeHub;

src/components/resources/RoutinesTab.tsx.content:
"use client";

import React, { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
  Sun,
  Activity,
  Moon,
  Plus,
  Check,
  X,
  ChevronRight,
  Flame,
  Calendar,
  Clock,
  Edit2,
  Trash2,
  GripVertical,
  RotateCcw,
  type LucideIcon,
} from "lucide-react";

const iconMap: Record<string, LucideIcon> = {
  Sun,
  Activity,
  Moon,
  Plus,
  Calendar,
  Clock,
};

interface RoutineItem {
  id: string;
  text: string;
  completed: boolean;
}

interface Routine {
  id: string;
  name: string;
  iconName: string;
  color: string;
  items: RoutineItem[];
  isCustom?: boolean;
}

const getIcon = (iconName: string): LucideIcon => {
  return iconMap[iconName] || Plus;
};

const defaultRoutines: Routine[] = [
  {
    id: "pre-market",
    name: "Pre-Market Checklist",
    iconName: "Sun",
    color: "text-amber-500",
    items: [
      { id: "pm1", text: "Check economic calendar for high-impact news", completed: false },
      { id: "pm2", text: "Review overnight market moves and gaps", completed: false },
      { id: "pm3", text: "Mark key support/resistance levels on charts", completed: false },
      { id: "pm4", text: "Set up watchlist with potential trades", completed: false },
      { id: "pm5", text: "Review trading plan and daily goals", completed: false },
      { id: "pm6", text: "Check mental state - am I clear-headed?", completed: false },
      { id: "pm7", text: "Ensure risk parameters are set correctly", completed: false },
    ],
  },
  {
    id: "during-trade",
    name: "During Trade Reminders",
    iconName: "Activity",
    color: "text-blue-500",
    items: [
      { id: "dt1", text: "Is this trade part of my plan?", completed: false },
      { id: "dt2", text: "Is my position size appropriate for risk?", completed: false },
      { id: "dt3", text: "Have I set my stop loss correctly?", completed: false },
      { id: "dt4", text: "Am I trading with the trend?", completed: false },
      { id: "dt5", text: "Am I feeling emotional? If yes, step back.", completed: false },
      { id: "dt6", text: "Is my take profit at a logical level?", completed: false },
    ],
  },
  {
    id: "post-market",
    name: "Post-Market Review",
    iconName: "Moon",
    color: "text-purple-500",
    items: [
      { id: "pm1", text: "Record all trades in journal with screenshots", completed: false },
      { id: "pm2", text: "Calculate daily P&L and update statistics", completed: false },
      { id: "pm3", text: "Review what went well today", completed: false },
      { id: "pm4", text: "Identify areas for improvement", completed: false },
      { id: "pm5", text: "Note any patterns or lessons learned", completed: false },
      { id: "pm6", text: "Prepare for tomorrow - mark key levels", completed: false },
      { id: "pm7", text: "Close trading platform and disconnect mentally", completed: false },
    ],
  },
];

interface StreakData {
  count: number;
  lastCompletedDate: string;
  streakIncrementedToday: boolean;
}

interface RoutineCompletionData {
  routines: Routine[];
  lastResetDate: string;
}

const RoutinesTab = () => {
  const [routines, setRoutines] = useState<Routine[]>([]);
  const [expandedRoutine, setExpandedRoutine] = useState<string | null>("pre-market");
  const [streak, setStreak] = useState(0);
  const [streakIncrementedToday, setStreakIncrementedToday] = useState(false);
  const [showAddModal, setShowAddModal] = useState(false);
  const [newRoutineName, setNewRoutineName] = useState("");
  const [editingItem, setEditingItem] = useState<{ routineId: string; itemId: string } | null>(null);
  const [editText, setEditText] = useState("");

  const getTodayString = () => new Date().toDateString();

  const isYesterday = (dateString: string) => {
    const yesterday = new Date();
    yesterday.setDate(yesterday.getDate() - 1);
    return new Date(dateString).toDateString() === yesterday.toDateString();
  };

  const migrateRoutineData = (routines: Routine[]): Routine[] => {
    return routines.map((routine) => {
      if (!routine.iconName) {
        const iconNameMap: Record<string, string> = {
          "pre-market": "Sun",
          "during-trade": "Activity",
          "post-market": "Moon",
        };
        return {
          ...routine,
          iconName: iconNameMap[routine.id] || (routine.isCustom ? "Calendar" : "Plus"),
        };
      }
      return routine;
    });
  };

  useEffect(() => {
    const today = getTodayString();

    const savedData = localStorage.getItem("tradingRoutinesData");
    if (savedData) {
      const data = JSON.parse(savedData);
      const migratedRoutines = migrateRoutineData(data.routines);

      if (data.lastResetDate !== today) {
        const resetRoutines = migratedRoutines.map((routine) => ({
          ...routine,
          items: routine.items.map((item) => ({ ...item, completed: false })),
        }));
        setRoutines(resetRoutines);
        saveRoutinesToStorage(resetRoutines, today);
      } else {
        setRoutines(migratedRoutines);
        if (migratedRoutines !== data.routines) {
          saveRoutinesToStorage(migratedRoutines, data.lastResetDate);
        }
      }
    } else {
      setRoutines(defaultRoutines);
      saveRoutinesToStorage(defaultRoutines, today);
    }

    const savedStreak = localStorage.getItem("routineStreak");
    if (savedStreak) {
      const streakData: StreakData = JSON.parse(savedStreak);

      if (streakData.lastCompletedDate === today) {
        setStreak(streakData.count);
        setStreakIncrementedToday(true);
      } else if (isYesterday(streakData.lastCompletedDate)) {
        setStreak(streakData.count);
        setStreakIncrementedToday(false);
      } else {
        setStreak(0);
        setStreakIncrementedToday(false);
      }
    }
  }, []);

  const saveRoutinesToStorage = (newRoutines: Routine[], date?: string) => {
    const data: RoutineCompletionData = {
      routines: newRoutines,
      lastResetDate: date || getTodayString(),
    };
    localStorage.setItem("tradingRoutinesData", JSON.stringify(data));
  };

  const saveRoutines = (newRoutines: Routine[]) => {
    setRoutines(newRoutines);
    saveRoutinesToStorage(newRoutines);
  };

  const checkAndUpdateStreak = (newRoutines: Routine[]) => {
    if (streakIncrementedToday) return;

    const allCompleted = newRoutines.every((r) =>
      r.items.length > 0 && r.items.every((i) => i.completed)
    );

    if (allCompleted) {
      const today = getTodayString();
      const newStreak = streak + 1;
      const streakData: StreakData = {
        count: newStreak,
        lastCompletedDate: today,
        streakIncrementedToday: true,
      };
      setStreak(newStreak);
      setStreakIncrementedToday(true);
      localStorage.setItem("routineStreak", JSON.stringify(streakData));
    }
  };

  const toggleItem = (routineId: string, itemId: string) => {
    const newRoutines = routines.map((routine) => {
      if (routine.id === routineId) {
        const newItems = routine.items.map((item) =>
          item.id === itemId ? { ...item, completed: !item.completed } : item
        );
        return { ...routine, items: newItems };
      }
      return routine;
    });
    saveRoutines(newRoutines);
    checkAndUpdateStreak(newRoutines);
  };

  const resetRoutine = (routineId: string) => {
    const newRoutines = routines.map((routine) => {
      if (routine.id === routineId) {
        return {
          ...routine,
          items: routine.items.map((item) => ({ ...item, completed: false })),
        };
      }
      return routine;
    });
    saveRoutines(newRoutines);
  };

  const addCustomRoutine = () => {
    if (!newRoutineName.trim()) return;

    const newRoutine: Routine = {
      id: `custom-${Date.now()}`,
      name: newRoutineName,
      iconName: "Calendar",
      color: "text-emerald-500",
      items: [],
      isCustom: true,
    };

    saveRoutines([...routines, newRoutine]);
    setNewRoutineName("");
    setShowAddModal(false);
    setExpandedRoutine(newRoutine.id);
  };

  const addItemToRoutine = (routineId: string) => {
    const newRoutines = routines.map((routine) => {
      if (routine.id === routineId) {
        return {
          ...routine,
          items: [
            ...routine.items,
            { id: `item-${Date.now()}`, text: "New item - click to edit", completed: false },
          ],
        };
      }
      return routine;
    });
    saveRoutines(newRoutines);
  };

  const updateItem = (routineId: string, itemId: string, newText: string) => {
    if (!newText.trim()) return;

    const newRoutines = routines.map((routine) => {
      if (routine.id === routineId) {
        return {
          ...routine,
          items: routine.items.map((item) =>
            item.id === itemId ? { ...item, text: newText } : item
          ),
        };
      }
      return routine;
    });
    saveRoutines(newRoutines);
    setEditingItem(null);
    setEditText("");
  };

  const deleteItem = (routineId: string, itemId: string) => {
    const newRoutines = routines.map((routine) => {
      if (routine.id === routineId) {
        return {
          ...routine,
          items: routine.items.filter((item) => item.id !== itemId),
        };
      }
      return routine;
    });
    saveRoutines(newRoutines);
  };

  const deleteRoutine = (routineId: string) => {
    const newRoutines = routines.filter((r) => r.id !== routineId);
    saveRoutines(newRoutines);
  };

  const getCompletionPercentage = (routine: Routine) => {
    if (routine.items.length === 0) return 0;
    return Math.round(
      (routine.items.filter((i) => i.completed).length / routine.items.length) * 100
    );
  };

  return (
    <div className="space-y-6">
      {/* Streak Banner */}
      <motion.div
        className="bg-gradient-to-r from-orange-500/10 via-amber-500/10 to-yellow-500/10 border border-amber-500/20 rounded-2xl p-4 flex items-center justify-between"
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
      >
        <div className="flex items-center gap-4">
          <div className="p-3 rounded-xl bg-amber-500/20">
            <Flame className="h-6 w-6 text-amber-500" />
          </div>
          <div>
            <p className="text-sm text-muted-foreground">Current Streak</p>
            <p className="text-2xl font-bold text-foreground">{streak} days</p>
          </div>
        </div>
        <div className="text-right">
          <p className="text-xs text-muted-foreground">Complete all routines daily</p>
          <p className="text-xs text-muted-foreground">to build your streak!</p>
        </div>
      </motion.div>

      {/* Routines List */}
      <div className="space-y-4">
        {routines.map((routine) => {
          const Icon = getIcon(routine.iconName);
          const isExpanded = expandedRoutine === routine.id;
          const completionPct = getCompletionPercentage(routine);
          const completedCount = routine.items.filter((i) => i.completed).length;

          return (
            <motion.div
              key={routine.id}
              layout
              className="bg-card border border-border rounded-xl overflow-hidden"
            >
              {/* Routine Header */}
              <button
                onClick={() => setExpandedRoutine(isExpanded ? null : routine.id)}
                className="w-full p-4 flex items-center justify-between"
              >
                <div className="flex items-center gap-3">
                  <div className={`p-2 rounded-lg bg-muted ${routine.color}`}>
                    <Icon className="h-5 w-5" />
                  </div>
                  <div className="text-left">
                    <h3 className="font-medium text-foreground">{routine.name}</h3>
                    <p className="text-xs text-muted-foreground">
                      {completedCount}/{routine.items.length} completed
                    </p>
                  </div>
                </div>

                <div className="flex items-center gap-3">
                  {/* Progress Circle */}
                  <div className="relative w-10 h-10">
                    <svg className="w-10 h-10 -rotate-90">
                      <circle
                        cx="20"
                        cy="20"
                        r="16"
                        stroke="currentColor"
                        strokeWidth="3"
                        fill="none"
                        className="text-muted"
                      />
                      <circle
                        cx="20"
                        cy="20"
                        r="16"
                        stroke="currentColor"
                        strokeWidth="3"
                        fill="none"
                        strokeDasharray={100}
                        strokeDashoffset={100 - completionPct}
                        className={completionPct === 100 ? "text-profit" : "text-primary"}
                        strokeLinecap="round"
                      />
                    </svg>
                    <span className="absolute inset-0 flex items-center justify-center text-xs font-medium">
                      {completionPct}%
                    </span>
                  </div>

                  <ChevronRight
                    className={`h-5 w-5 text-muted-foreground transition-transform ${
                      isExpanded ? "rotate-90" : ""
                    }`}
                  />
                </div>
              </button>

              {/* Expanded Content */}
              <AnimatePresence>
                {isExpanded && (
                  <motion.div
                    initial={{ opacity: 0, height: 0 }}
                    animate={{ opacity: 1, height: "auto" }}
                    exit={{ opacity: 0, height: 0 }}
                    className="border-t border-border"
                  >
                    <div className="p-4 space-y-2">
                      {routine.items.map((item) => (
                        <div
                          key={item.id}
                          className={`flex items-center gap-3 p-3 rounded-lg transition-colors ${
                            item.completed ? "bg-profit/10" : "bg-muted/50 hover:bg-muted"
                          }`}
                        >
                          <button
                            onClick={() => toggleItem(routine.id, item.id)}
                            className={`w-5 h-5 rounded-md border-2 flex items-center justify-center transition-all ${
                              item.completed
                                ? "bg-profit border-profit text-white"
                                : "border-muted-foreground/50 hover:border-primary"
                            }`}
                          >
                            {item.completed && <Check className="h-3 w-3" />}
                          </button>

                          {editingItem?.routineId === routine.id && editingItem?.itemId === item.id ? (
                            <input
                              type="text"
                              value={editText}
                              onChange={(e) => setEditText(e.target.value)}
                              onBlur={() => updateItem(routine.id, item.id, editText)}
                              onKeyDown={(e) => {
                                if (e.key === "Enter") updateItem(routine.id, item.id, editText);
                                if (e.key === "Escape") {
                                  setEditingItem(null);
                                  setEditText("");
                                }
                              }}
                              autoFocus
                              className="flex-1 bg-transparent border-b border-primary text-sm text-foreground focus:outline-none"
                            />
                          ) : (
                            <span
                              className={`flex-1 text-sm ${
                                item.completed ? "text-muted-foreground line-through" : "text-foreground"
                              }`}
                            >
                              {item.text}
                            </span>
                          )}

                          <div className="flex items-center gap-1">
                            <button
                              onClick={() => {
                                setEditingItem({ routineId: routine.id, itemId: item.id });
                                setEditText(item.text);
                              }}
                              className="p-1.5 rounded hover:bg-muted transition-colors"
                            >
                              <Edit2 className="h-3.5 w-3.5 text-muted-foreground" />
                            </button>
                            <button
                              onClick={() => deleteItem(routine.id, item.id)}
                              className="p-1.5 rounded hover:bg-loss/10 transition-colors"
                            >
                              <Trash2 className="h-3.5 w-3.5 text-muted-foreground hover:text-loss" />
                            </button>
                          </div>
                        </div>
                      ))}

                      {/* Add Item Button */}
                      <button
                        onClick={() => addItemToRoutine(routine.id)}
                        className="w-full flex items-center justify-center gap-2 p-3 rounded-lg border border-dashed border-border hover:border-primary hover:bg-primary/5 transition-colors text-sm text-muted-foreground hover:text-primary"
                      >
                        <Plus className="h-4 w-4" />
                        Add Item
                      </button>

                      {/* Routine Actions */}
                      <div className="flex items-center justify-between pt-2">
                        <button
                          onClick={() => resetRoutine(routine.id)}
                          className="flex items-center gap-2 px-3 py-1.5 text-xs text-muted-foreground hover:text-foreground transition-colors"
                        >
                          <RotateCcw className="h-3.5 w-3.5" />
                          Reset
                        </button>

                        {routine.isCustom && (
                          <button
                            onClick={() => deleteRoutine(routine.id)}
                            className="flex items-center gap-2 px-3 py-1.5 text-xs text-loss/70 hover:text-loss transition-colors"
                          >
                            <Trash2 className="h-3.5 w-3.5" />
                            Delete Routine
                          </button>
                        )}
                      </div>
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>
            </motion.div>
          );
        })}
      </div>

      {/* Add Custom Routine Button */}
      <button
        onClick={() => setShowAddModal(true)}
        className="w-full flex items-center justify-center gap-2 p-4 rounded-xl border border-dashed border-border hover:border-primary hover:bg-primary/5 transition-colors text-muted-foreground hover:text-primary"
      >
        <Plus className="h-5 w-5" />
        Create Custom Routine
      </button>

      {/* Add Routine Modal */}
      <AnimatePresence>
        {showAddModal && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4"
            onClick={() => setShowAddModal(false)}
          >
            <motion.div
              initial={{ scale: 0.95, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.95, opacity: 0 }}
              onClick={(e) => e.stopPropagation()}
              className="bg-card border border-border rounded-2xl p-6 w-full max-w-md"
            >
              <h3 className="text-lg font-semibold text-foreground mb-4">Create Custom Routine</h3>

              <input
                type="text"
                value={newRoutineName}
                onChange={(e) => setNewRoutineName(e.target.value)}
                placeholder="Routine name (e.g., Weekly Review)"
                className="w-full px-4 py-3 bg-muted border border-border rounded-xl text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/50"
                autoFocus
              />

              <div className="flex gap-3 mt-6">
                <button
                  onClick={() => setShowAddModal(false)}
                  className="flex-1 px-4 py-2.5 rounded-xl border border-border text-muted-foreground hover:text-foreground transition-colors"
                >
                  Cancel
                </button>
                <button
                  onClick={addCustomRoutine}
                  disabled={!newRoutineName.trim()}
                  className="flex-1 px-4 py-2.5 rounded-xl bg-primary text-primary-foreground font-medium disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  Create
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default RoutinesTab;

src/components/resources/PsychologyCorne.content:
"use client";

import React, { useState, useEffect } from "react";
import { motion } from "framer-motion";
import {
  Brain,
  Lightbulb,
  Heart,
  AlertTriangle,
  RefreshCw,
  Quote,
  ChevronRight,
  Sparkles,
  Shield,
  Target,
  Zap,
} from "lucide-react";

interface Tip {
  id: string;
  title: string;
  content: string;
  category: "discipline" | "mindset" | "emotions" | "pitfalls";
  icon: React.ElementType;
}

interface Affirmation {
  text: string;
  author?: string;
}

const dailyTips: Tip[] = [
  {
    id: "1",
    title: "Stick to Your Plan",
    content: "Your trading plan was made with a clear head. Trust it. Deviating during market hours often leads to impulsive decisions.",
    category: "discipline",
    icon: Shield,
  },
  {
    id: "2",
    title: "Accept Losses Gracefully",
    content: "Losses are tuition fees in the market. Learn from them, but don't let them affect your next trade emotionally.",
    category: "emotions",
    icon: Heart,
  },
  {
    id: "3",
    title: "Quality Over Quantity",
    content: "One well-planned trade is worth more than ten impulsive ones. Wait for your setup.",
    category: "discipline",
    icon: Target,
  },
  {
    id: "4",
    title: "Avoid Revenge Trading",
    content: "After a loss, take a break. The urge to 'win it back' leads to poor decisions and larger losses.",
    category: "pitfalls",
    icon: AlertTriangle,
  },
  {
    id: "5",
    title: "Stay Present",
    content: "Focus on executing the current trade well. Don't think about past losses or potential future gains.",
    category: "mindset",
    icon: Brain,
  },
  {
    id: "6",
    title: "Manage Expectations",
    content: "Consistent small wins compound over time. Don't chase home runs - they often lead to strikeouts.",
    category: "mindset",
    icon: Lightbulb,
  },
  {
    id: "7",
    title: "Know When to Stop",
    content: "Set daily loss limits and profit targets. When you hit either, walk away and live to trade another day.",
    category: "discipline",
    icon: Shield,
  },
  {
    id: "8",
    title: "Beware of FOMO",
    content: "Fear of missing out causes rushed entries. There will always be another opportunity. Let trades come to you.",
    category: "pitfalls",
    icon: AlertTriangle,
  },
];

const affirmations: Affirmation[] = [
  { text: "I am disciplined and patient. I wait for my setups.", author: "Trading Mantra" },
  { text: "I accept that losses are part of the game. I learn and move forward." },
  { text: "I trade my plan, not my emotions." },
  { text: "Every trade is an opportunity to improve, regardless of outcome." },
  { text: "I am not my last trade. Each new trade is a fresh start." },
  { text: "The market doesn't owe me anything. I earn my profits through discipline." },
  { text: "I focus on the process, not the profits. Profits follow good process." },
  { text: "I cut losses quickly and let winners run." },
  { text: "I am grateful for every lesson the market teaches me." },
  { text: "Patience and discipline are my competitive advantages." },
];

const commonPitfalls = [
  {
    title: "Overtrading",
    description: "Taking too many trades, often from boredom or the desire for action. Solution: Set a maximum number of trades per day.",
    icon: Zap,
  },
  {
    title: "Revenge Trading",
    description: "Trying to quickly recover losses with larger positions or impulsive trades. Solution: Take a break after losses.",
    icon: AlertTriangle,
  },
  {
    title: "Moving Stop Losses",
    description: "Moving your stop loss further away to avoid being stopped out. Solution: Accept the loss as planned.",
    icon: Shield,
  },
  {
    title: "FOMO (Fear of Missing Out)",
    description: "Entering trades late or without proper analysis because of fear. Solution: Trust that better setups will come.",
    icon: Target,
  },
  {
    title: "Overconfidence After Wins",
    description: "Taking larger positions or ignoring rules after a winning streak. Solution: Stick to your position sizing rules.",
    icon: Sparkles,
  },
];

const PsychologyCorner = () => {
  const [currentAffirmation, setCurrentAffirmation] = useState(0);
  const [expandedTip, setExpandedTip] = useState<string | null>(null);

  const rotateAffirmation = () => {
    setCurrentAffirmation((prev) => (prev + 1) % affirmations.length);
  };

  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentAffirmation((prev) => (prev + 1) % affirmations.length);
    }, 10000);
    return () => clearInterval(interval);
  }, []);

  const categories = [
    { id: "discipline", label: "Discipline", icon: Shield, color: "text-blue-500" },
    { id: "mindset", label: "Mindset", icon: Brain, color: "text-purple-500" },
    { id: "emotions", label: "Emotions", icon: Heart, color: "text-rose-500" },
    { id: "pitfalls", label: "Pitfalls", icon: AlertTriangle, color: "text-amber-500" },
  ];

  return (
    <div className="space-y-8">
      {/* Daily Affirmation Card */}
      <motion.div
        className="relative bg-gradient-to-br from-primary/10 via-card to-card border border-primary/20 rounded-2xl p-6 overflow-hidden"
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
      >
        <div className="absolute top-0 right-0 w-32 h-32 bg-primary/5 rounded-full -translate-y-1/2 translate-x-1/2" />
        <div className="absolute bottom-0 left-0 w-24 h-24 bg-primary/5 rounded-full translate-y-1/2 -translate-x-1/2" />

        <div className="relative">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-2">
              <Quote className="h-5 w-5 text-primary" />
              <span className="text-sm font-medium text-primary">Daily Affirmation</span>
            </div>
            <button
              onClick={rotateAffirmation}
              className="p-2 rounded-lg hover:bg-muted transition-colors"
            >
              <RefreshCw className="h-4 w-4 text-muted-foreground" />
            </button>
          </div>

          <motion.div
            key={currentAffirmation}
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -20 }}
          >
            <p className="text-lg md:text-xl font-medium text-foreground leading-relaxed">
              "{affirmations[currentAffirmation].text}"
            </p>
            {affirmations[currentAffirmation].author && (
              <p className="text-sm text-muted-foreground mt-2">
                — {affirmations[currentAffirmation].author}
              </p>
            )}
          </motion.div>

          <div className="flex gap-1 mt-4">
            {affirmations.map((_, idx) => (
              <button
                key={idx}
                onClick={() => setCurrentAffirmation(idx)}
                className={`w-2 h-2 rounded-full transition-colors ${
                  idx === currentAffirmation ? "bg-primary" : "bg-muted-foreground/30"
                }`}
              />
            ))}
          </div>
        </div>
      </motion.div>

      {/* Psychology Tips Grid */}
      <div>
        <h2 className="text-lg font-semibold text-foreground mb-4">Psychology Tips</h2>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {dailyTips.map((tip) => {
            const Icon = tip.icon;
            const category = categories.find((c) => c.id === tip.category);
            const isExpanded = expandedTip === tip.id;

            return (
              <motion.div
                key={tip.id}
                layout
                className="bg-card border border-border rounded-xl overflow-hidden hover:border-primary/30 transition-colors"
              >
                <button
                  onClick={() => setExpandedTip(isExpanded ? null : tip.id)}
                  className="w-full p-4 text-left"
                >
                  <div className="flex items-start gap-3">
                    <div className={`p-2 rounded-lg bg-muted ${category?.color}`}>
                      <Icon className="h-4 w-4" />
                    </div>
                    <div className="flex-1">
                      <div className="flex items-center justify-between">
                        <h3 className="font-medium text-foreground">{tip.title}</h3>
                        <ChevronRight className={`h-4 w-4 text-muted-foreground transition-transform ${isExpanded ? "rotate-90" : ""}`} />
                      </div>
                      <span className="text-xs text-muted-foreground capitalize">{tip.category}</span>
                    </div>
                  </div>
                </button>

                {isExpanded && (
                  <motion.div
                    initial={{ opacity: 0, height: 0 }}
                    animate={{ opacity: 1, height: "auto" }}
                    className="border-t border-border"
                  >
                    <p className="p-4 text-sm text-muted-foreground leading-relaxed">
                      {tip.content}
                    </p>
                  </motion.div>
                )}
              </motion.div>
            );
          })}
        </div>
      </div>

      {/* Common Pitfalls */}
      <div>
        <h2 className="text-lg font-semibold text-foreground mb-4">Common Trading Pitfalls</h2>
        <div className="space-y-3">
          {commonPitfalls.map((pitfall, idx) => {
            const Icon = pitfall.icon;
            return (
              <div
                key={idx}
                className="bg-card border border-border rounded-xl p-4 flex items-start gap-4"
              >
                <div className="p-2 rounded-lg bg-amber-500/10 text-amber-500 flex-shrink-0">
                  <Icon className="h-4 w-4" />
                </div>
                <div>
                  <h3 className="font-medium text-foreground">{pitfall.title}</h3>
                  <p className="text-sm text-muted-foreground mt-1">{pitfall.description}</p>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default PsychologyCorner;

