'use client';

import { useState, useEffect } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { 
  faTrash,
  faChevronLeft,
  faChevronRight,
  faTimes,
  faSearch,
  faArrowUp,
  faArrowDown,
  faPlus,
} from '@fortawesome/free-solid-svg-icons';
import { ChartCard, FilterButton, Skeleton } from '@/components/backtesting';

interface Trade {
  id: number;
  sessionId?: number;
  name?: string;
  date?: string;
  symbol?: string;
  position?: string;
  type?: string;
  entry?: number;
  exit?: number;
  entryPrice?: number;
  stopPrice?: number;
  lotSize?: number;
  pnl?: number;
  roi?: number;
  reason?: string;
  status?: string;
  timestamp?: string;
}

interface MongoSession {
  _id: string;
  uniqueId: string;
  sessionId: number;
  sessionInfo: {
    name: string;
    symbol: string;
    currentBalance: string;
    startDate: string;
    endDate: string;
    daysRemaining: number;
    totalPnl: number;
    winRate: number;
    riskReward: number;
  };
  trades: Trade[];
}

export default function JournalMain() {
  const [trades, setTrades] = useState<Trade[]>([]);
  const [sessions, setSessions] = useState<MongoSession[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedType, setSelectedType] = useState<string | null>(null);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [currentPage, setCurrentPage] = useState(1);

  useEffect(() => {
    async function fetchData() {
      try {
        const res = await fetch('/api/backtest-sessions');

        if (!res.ok) throw new Error('Failed to fetch sessions');

        const data = await res.json();

        if (data.success && data.data) {
          setSessions(data.data);

          const allTrades: Trade[] = [];
          data.data.forEach((session: MongoSession) => {
            if (session.trades && Array.isArray(session.trades)) {
              session.trades.forEach((trade: Trade) => {
                allTrades.push({
                  ...trade,
                  sessionId: session.sessionId,
                  symbol: trade.symbol || session.sessionInfo.symbol
                });
              });
            }
          });
          setTrades(allTrades);
        }
      } catch (err: any) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    }
    fetchData();
  }, []);

  const getSessionName = (sessionId: number | undefined) => {
    if (!sessionId) return 'Unknown Session';
    const session = sessions.find(s => s.sessionId === sessionId);
    return session?.sessionInfo.name || `Session #${sessionId}`;
  };

  const getSessionSymbol = (sessionId: number | undefined) => {
    if (!sessionId) return 'EUR/USD';
    const session = sessions.find(s => s.sessionId === sessionId);
    return session?.sessionInfo.symbol || 'EUR/USD';
  };

  const filteredTrades = trades.filter(trade => {
    const tradeType = trade.type || trade.position || 'long';
    const matchesSearch = searchTerm === '' || 
      getSessionName(trade.sessionId).toLowerCase().includes(searchTerm.toLowerCase()) ||
      getSessionSymbol(trade.sessionId).toLowerCase().includes(searchTerm.toLowerCase()) ||
      tradeType.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesType = selectedType === null || tradeType === selectedType;

    return matchesSearch && matchesType;
  });

  const totalPages = Math.ceil(filteredTrades.length / rowsPerPage);
  const paginatedTrades = filteredTrades.slice(
    (currentPage - 1) * rowsPerPage,
    currentPage * rowsPerPage
  );

  const clearFilters = () => {
    setSelectedType(null);
    setSearchTerm('');
  };

  if (loading) {
    return (
      <div className="space-y-5">
        <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4">
          <div>
            <h2 className="text-xl font-semibold text-[var(--foreground)]">Trade Journal</h2>
            <p className="text-sm text-[var(--foreground-muted)] mt-1">Loading your trade history...</p>
          </div>
        </div>
        <Skeleton className="h-16" />
        <Skeleton className="h-96" />
      </div>
    );
  }

  if (error) {
    return (
      <div className="space-y-5">
        <div className="bg-red-500/10 border border-red-500/30 rounded-lg p-4">
          <p className="text-red-400">Error loading trades: {error}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-5">
      <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4">
        <div>
          <h2 className="text-xl font-semibold text-[var(--foreground)]">Trade Journal</h2>
          <p className="text-sm text-[var(--foreground-muted)] mt-1">
            {trades.length} total trades recorded
          </p>
        </div>

        <div className="flex items-center gap-3">
          <div className="relative flex items-center">
            <FontAwesomeIcon icon={faSearch} className="absolute left-3 h-3.5 w-3.5 text-[var(--foreground-muted)]" />
            <input
              type="text"
              placeholder="Search trades..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="input pl-9 pr-4 py-2 text-sm w-56"
            />
          </div>
        </div>
      </div>

      <div className="card p-4">
        <div className="flex flex-wrap items-center gap-2 mb-3">
          <FilterButton 
            active={selectedType === null}
            onClick={() => setSelectedType(null)}
          >
            All ({trades.length})
          </FilterButton>
          <FilterButton 
            active={selectedType === 'long'}
            onClick={() => setSelectedType('long')}
          >
            Long ({trades.filter(t => (t.type || t.position || 'long') === 'long').length})
          </FilterButton>
          <FilterButton 
            active={selectedType === 'short'}
            onClick={() => setSelectedType('short')}
          >
            Short ({trades.filter(t => (t.type || t.position || '') === 'short').length})
          </FilterButton>
          <FilterButton 
            active={false}
            onClick={() => {}}
          >
            Winners ({trades.filter(t => (t.pnl || t.roi || 0) > 0).length})
          </FilterButton>
          <FilterButton 
            active={false}
            onClick={() => {}}
          >
            Losers ({trades.filter(t => (t.pnl || t.roi || 0) < 0).length})
          </FilterButton>
        </div>

        {(selectedType !== null || searchTerm !== '') && (
          <div className="flex flex-wrap items-center gap-2 pt-3 border-t border-[var(--border-light)]">
            {selectedType && (
              <div className="flex items-center gap-2 px-2.5 py-1 rounded-md bg-[var(--background-elevated)] text-xs">
                <span className="text-[var(--foreground-secondary)]">{selectedType.toUpperCase()}</span>
                <button 
                  onClick={() => setSelectedType(null)}
                  className="text-[var(--foreground-muted)] hover:text-[var(--foreground)] transition-colors"
                >
                  <FontAwesomeIcon icon={faTimes} className="h-2.5 w-2.5" />
                </button>
              </div>
            )}
            {searchTerm && (
              <div className="flex items-center gap-2 px-2.5 py-1 rounded-md bg-[var(--background-elevated)] text-xs">
                <span className="text-[var(--foreground-secondary)]">Search: {searchTerm}</span>
                <button 
                  onClick={() => setSearchTerm('')}
                  className="text-[var(--foreground-muted)] hover:text-[var(--foreground)] transition-colors"
                >
                  <FontAwesomeIcon icon={faTimes} className="h-2.5 w-2.5" />
                </button>
              </div>
            )}

            <button 
              onClick={clearFilters}
              className="flex items-center gap-1.5 text-[var(--foreground-muted)] hover:text-[var(--loss)] text-xs ml-auto transition-colors"
            >
              <FontAwesomeIcon icon={faTrash} className="h-3 w-3" />
              Clear all
            </button>
          </div>
        )}
      </div>

      <ChartCard title="Trade Entries">
        <div className="overflow-x-auto -mx-6 px-6">
          <table className="w-full min-w-[800px]">
            <thead>
              <tr className="border-b border-[var(--border-light)]">
                <th className="text-left py-3 px-3 text-xs font-medium text-[var(--foreground-muted)] uppercase tracking-wide">Trade</th>
                <th className="text-left py-3 px-3 text-xs font-medium text-[var(--foreground-muted)] uppercase tracking-wide">Date</th>
                <th className="text-left py-3 px-3 text-xs font-medium text-[var(--foreground-muted)] uppercase tracking-wide">Session</th>
                <th className="text-left py-3 px-3 text-xs font-medium text-[var(--foreground-muted)] uppercase tracking-wide">Symbol</th>
                <th className="text-left py-3 px-3 text-xs font-medium text-[var(--foreground-muted)] uppercase tracking-wide">Side</th>
                <th className="text-right py-3 px-3 text-xs font-medium text-[var(--foreground-muted)] uppercase tracking-wide">Entry</th>
                <th className="text-right py-3 px-3 text-xs font-medium text-[var(--foreground-muted)] uppercase tracking-wide">Exit</th>
                <th className="text-right py-3 px-3 text-xs font-medium text-[var(--foreground-muted)] uppercase tracking-wide">Lot Size</th>
                <th className="text-right py-3 px-3 text-xs font-medium text-[var(--foreground-muted)] uppercase tracking-wide">P&L</th>
              </tr>
            </thead>
            <tbody>
              {paginatedTrades.length === 0 ? (
                <tr>
                  <td colSpan={9} className="py-12 text-center">
                    <div className="text-[var(--foreground-muted)]">
                      {trades.length === 0 
                        ? 'No trades recorded yet. Start a backtesting session to add trades.'
                        : 'No trades match your filters.'
                      }
                    </div>
                  </td>
                </tr>
              ) : (
                paginatedTrades.map((trade) => {
                  const tradeType = trade.type || trade.position || 'long';
                  const isLong = tradeType.toLowerCase() === 'long' || tradeType.toLowerCase() === 'buy';
                  const tradePnl = trade.pnl || trade.roi || 0;
                  const tradeDate = trade.timestamp || trade.date || new Date().toISOString();
                  const entryPrice = trade.entry || trade.entryPrice || 0;
                  const exitPrice = trade.exit || trade.stopPrice || 0;

                  return (
                    <tr 
                      key={trade.id} 
                      className="border-b border-[var(--border-light)] hover:bg-[var(--background-hover)] transition-colors cursor-pointer"
                    >
                      <td className="py-3 px-3">
                        <div className="flex items-center gap-2">
                          <div className={`w-7 h-7 rounded-lg flex items-center justify-center ${
                            isLong ? 'bg-[var(--profit-bg)]' : 'bg-[var(--loss-bg)]'
                          }`}>
                            <FontAwesomeIcon 
                              icon={isLong ? faArrowUp : faArrowDown} 
                              className={`h-3 w-3 ${isLong ? 'text-[var(--profit)]' : 'text-[var(--loss)]'}`}
                            />
                          </div>
                          <span className="text-sm font-medium text-[var(--foreground)]">#{trade.id}</span>
                        </div>
                      </td>
                      <td className="py-3 px-3 text-sm text-[var(--foreground-muted)]">
                        {new Date(tradeDate).toLocaleDateString()}
                      </td>
                      <td className="py-3 px-3 text-sm text-[var(--foreground)]">
                        {getSessionName(trade.sessionId)}
                      </td>
                      <td className="py-3 px-3">
                        <span className="text-sm font-medium text-[var(--foreground)]">
                          {trade.symbol || getSessionSymbol(trade.sessionId)}
                        </span>
                      </td>
                      <td className="py-3 px-3">
                        <span className={`px-2 py-0.5 rounded text-xs font-medium ${
                          isLong 
                            ? 'bg-[var(--profit-bg)] text-[var(--profit)]' 
                            : 'bg-[var(--loss-bg)] text-[var(--loss)]'
                        }`}>
                          {tradeType.toUpperCase()}
                        </span>
                      </td>
                      <td className="py-3 px-3 text-right text-sm tabular-nums text-[var(--foreground)]">
                        {entryPrice.toFixed(5)}
                      </td>
                      <td className="py-3 px-3 text-right text-sm tabular-nums text-[var(--foreground-muted)]">
                        {exitPrice.toFixed(5)}
                      </td>
                      <td className="py-3 px-3 text-right text-sm tabular-nums text-[var(--foreground)]">
                        {trade.lotSize || '-'}
                      </td>
                      <td className={`py-3 px-3 text-right text-sm font-medium tabular-nums ${
                        tradePnl >= 0 ? 'text-[var(--profit)]' : 'text-[var(--loss)]'
                      }`}>
                        {tradePnl >= 0 ? '+' : ''}${tradePnl.toFixed(2)}
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>

        {filteredTrades.length > 0 && (
          <div className="flex flex-col sm:flex-row justify-between items-center gap-4 mt-4 pt-4 border-t border-[var(--border-light)]">
            <div className="flex items-center gap-2">
              <span className="text-xs text-[var(--foreground-muted)]">Rows per page</span>
              <select 
                className="bg-[var(--background-hover)] text-[var(--foreground)] px-2 py-1 rounded text-xs border border-[var(--border-light)] focus:outline-none"
                value={rowsPerPage}
                onChange={(e) => {
                  setRowsPerPage(Number(e.target.value));
                  setCurrentPage(1);
                }}
              >
                <option value={5}>5</option>
                <option value={10}>10</option>
                <option value={20}>20</option>
                <option value={50}>50</option>
              </select>
            </div>
            <div className="flex items-center gap-1">
              <button 
                className="p-1.5 rounded bg-[var(--background-hover)] hover:bg-[var(--background-elevated)] disabled:opacity-50 transition-colors"
                onClick={() => setCurrentPage(Math.max(currentPage - 1, 1))}
                disabled={currentPage === 1}
              >
                <FontAwesomeIcon icon={faChevronLeft} className="h-3 w-3 text-[var(--foreground-muted)]" />
              </button>
              <span className="px-3 py-1 rounded bg-[var(--primary-muted)] text-xs font-medium text-[var(--primary)]">
                {currentPage}
              </span>
              <button 
                className="p-1.5 rounded bg-[var(--background-hover)] hover:bg-[var(--background-elevated)] disabled:opacity-50 transition-colors"
                onClick={() => setCurrentPage(Math.min(currentPage + 1, totalPages))}
                disabled={currentPage >= totalPages}
              >
                <FontAwesomeIcon icon={faChevronRight} className="h-3 w-3 text-[var(--foreground-muted)]" />
              </button>
              <span className="text-xs text-[var(--foreground-muted)] ml-1">of {totalPages || 1}</span>
            </div>
          </div>
        )}
      </ChartCard>
    </div>
  );
}

src/app/api/user/delete/route.ts.content:
import { NextResponse } from "next/server";
import { cookies } from "next/headers";
import { getUserModel } from "@/models/main/user.model";
import { getStrategyModel } from "@/models/main/strategy.model";
import { getNoteModel } from "@/models/main/notes.model";
import { getPlaybookModel } from "@/models/main/playbook.model";
import { getJournalTemplateModel } from "@/models/main/journalTemplate.model";
import { getSharedTradeModel } from "@/models/main/sharedTrade.model";
import { getLeaderboardEntryModel, getLeaderboardSettingsModel } from "@/models/main/leaderboard.model";
import { getManualModel } from "@/models/accounts/manual.model";
import { getAutoSyncModel } from "@/models/accounts/autoSync.model";
import { getOpenTradeModel } from "@/models/accounts/openTrades.model";
import { getASAccountModel } from "@/models/accounts/asAccounts.model";
import { getFileUploadModel } from "@/models/accounts/fileUploadSchema.model";

async function getUserFromToken(token: string) {
  const User = await getUserModel();
  return await User.findOne({ "tokens.token": token });
}

export async function DELETE() {
  try {
    const cookieStore = await cookies();
    const token = cookieStore.get("authToken")?.value;

    if (!token) {
      return NextResponse.json(
        { error: "Unauthorized" },
        { status: 401 }
      );
    }

    const user = await getUserFromToken(token);

    if (!user) {
      return NextResponse.json(
        { error: "User not found" },
        { status: 401 }
      );
    }

    const uniqueId = user.uniqueId;
    const userMongoId = user._id;

    const [
      User,
      Strategy,
      Notes,
      Playbook,
      JournalTemplate,
      SharedTrade,
      LeaderboardEntry,
      LeaderboardSettings,
      ManualAccount,
      AutoSyncAccount,
      OpenTrades,
      AsAccounts,
      FileUpload,
    ] = await Promise.all([
      getUserModel(),
      getStrategyModel(),
      getNoteModel(),
      getPlaybookModel(),
      getJournalTemplateModel(),
      getSharedTradeModel(),
      getLeaderboardEntryModel(),
      getLeaderboardSettingsModel(),
      getManualModel(),
      getAutoSyncModel(),
      getOpenTradeModel(),
      getASAccountModel(),
      getFileUploadModel(),
    ]);

    await Promise.all([
      User.findByIdAndDelete(userMongoId),
      Strategy.deleteMany({ uniqueId }),
      Notes.deleteMany({ uniqueId }),
      Playbook.deleteMany({ uniqueId }),
      JournalTemplate.deleteMany({ uniqueId }),
      SharedTrade.deleteMany({ uniqueId }),
      LeaderboardEntry.deleteMany({ uniqueId }),
      LeaderboardSettings.deleteMany({ uniqueId }),
    ]);

    await Promise.all([
      ManualAccount.deleteMany({ uniqueId }),
      AutoSyncAccount.deleteMany({ uniqueId }),
      OpenTrades.deleteMany({ uniqueId }),
      AsAccounts.deleteMany({ uniqueId }),
      FileUpload.deleteMany({ uniqueId }),
    ]);

    const response = NextResponse.json(
      { message: "Account deleted successfully" },
      { status: 200 }
    );

    response.cookies.delete("authToken");
    response.cookies.delete("userId");

    return response;
  } catch (error: any) {
    console.error("Error deleting account:", error);
    return NextResponse.json(
      { error: "Failed to delete account" },
      { status: 500 }
    );
  }
}

src/components/backtesting-testing/Testi.content:
'use client';

import { useState, useEffect } from 'react';
import { usePathname } from 'next/navigation';
import { useTestingStore } from '@/store/backtestingStore';
import { Plus, Search, Bell, Flame } from 'lucide-react';
import DashboardMain from './dashboard/DashboardMain';
import SessionsMain from './sessions/SessionsMain';
import JournalMain from './journal/JournalMain';
import AnalyticsMain from './analytics/AnalyticsMain';
import SessionCreationDialog from './SessionCreationDialog';

export default function TestingMain() {
  const pathname = usePathname();
  const { activeTab, setActiveTab, loadUserSessions } = useTestingStore();
  const [isSessionDialogOpen, setIsSessionDialogOpen] = useState(false);

  useEffect(() => {
    const path = pathname.split('/').pop();
    if (path === 'dashboard' || path === 'sessions' || path === 'journal' || path === 'analytics') {
      setActiveTab(path.charAt(0).toUpperCase() + path.slice(1));
    } else {
      setActiveTab('Dashboard');
    }
  }, [pathname, setActiveTab]);

  const handleNewSessionClick = () => {
    setIsSessionDialogOpen(true);
  };

  const handleCloseSessionDialog = () => {
    setIsSessionDialogOpen(false);
  };

  useEffect(() => {
    loadUserSessions();
  }, []);

  const getPageTitle = () => {
    switch (activeTab) {
      case 'Dashboard': return 'Backtesting Dashboard';
      case 'Sessions': return 'Sessions';
      case 'Journal': return 'Journal';
      case 'Analytics': return 'Analytics';
      default: return 'Backtesting Dashboard';
    }
  };

  const getPageSubtitle = () => {
    switch (activeTab) {
      case 'Dashboard': return 'Track your backtesting progress and key metrics';
      case 'Sessions': return 'Manage your backtesting sessions';
      case 'Journal': return 'Document your trading insights';
      case 'Analytics': return 'Analyze your performance data';
      default: return 'Track your backtesting progress and key metrics';
    }
  };

  return (
    <div className="bg-background text-foreground min-h-screen flex flex-col">
      <header className="sticky top-0 z-40 bg-background/95 backdrop-blur-md border-b border-border">
        <div className="px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div>
              <h1 className="text-xl font-semibold text-foreground">
                {getPageTitle()}
              </h1>
              <p className="text-sm text-muted-foreground hidden sm:block">
                {getPageSubtitle()}
              </p>
            </div>

            <div className="flex items-center gap-3">
              <div className="hidden md:flex items-center gap-2 px-3 py-2 bg-card border border-border rounded-lg">
                <Search className="h-4 w-4 text-muted-foreground" />
                <input
                  type="text"
                  placeholder="Search sessions..."
                  className="bg-transparent text-sm text-foreground placeholder:text-muted-foreground focus:outline-none w-40"
                />
                <kbd className="text-[10px] px-1.5 py-0.5 bg-muted rounded text-muted-foreground border border-border">
                  ⌘K
                </kbd>
              </div>

              <div className="hidden lg:flex items-center gap-2 px-3 py-2 bg-card border border-border rounded-lg">
                <Flame className="h-4 w-4 text-orange-500" />
                <span className="text-sm font-medium text-foreground">3 day streak</span>
              </div>

              <button className="relative p-2.5 rounded-lg bg-card border border-border hover:bg-accent transition-colors">
                <Bell className="h-4 w-4 text-muted-foreground" />
                <span className="absolute top-2 right-2 w-1.5 h-1.5 bg-primary rounded-full" />
              </button>
            </div>
          </div>
        </div>
      </header>

      <main className="flex-1 px-6 lg:px-8 py-6">
        <div className="animate-in fade-in duration-300">
          {activeTab === 'Dashboard' && <DashboardMain handleNewSessionClick={handleNewSessionClick} />}
          {activeTab === 'Sessions' && <SessionsMain />}
          {activeTab === 'Journal' && <JournalMain />}
          {activeTab === 'Analytics' && <AnalyticsMain />}
        </div>
      </main>

      <button 
        onClick={handleNewSessionClick}
        className="fixed bottom-6 right-6 flex items-center gap-2 rounded-xl px-5 py-3 shadow-lg bg-primary text-primary-foreground hover:bg-primary/90 transition-colors"
      >
        <Plus className="h-4 w-4" />
        <span className="font-medium">New Session</span>
      </button>

      <SessionCreationDialog 
        isOpen={isSessionDialogOpen} 
        onClose={handleCloseSessionDialog} 
      />
    </div>
  );
}

