      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
        <ChartCard title="Performance by Side">
          <div className="h-48 flex items-center justify-center">
            {totalRecentTrades > 0 ? (
              <PieChart width={180} height={180}>
                <Pie
                  data={performanceBySideData}
                  cx="50%"
                  cy="50%"
                  innerRadius={50}
                  outerRadius={75}
                  paddingAngle={4}
