        clearInterval(autoPlayIntervalRef.current);
      }
    }
    return () => {
      if (autoPlayIntervalRef.current) {
        clearInterval(autoPlayIntervalRef.current);
      }
    };
  }, [isPlaying, isEndReached, handleNext, playbackSpeed]);

  // Function to sync TP/SL line positions from chart before hit detection
  const syncLinesToTradeState = useCallback(() => {
    const storedLines = tradeLinesRef.current;
    const hasActiveTrade = !!activeTradesRef.current;
    const hasWidget = !!tvWidgetRef.current;

    // Debug log to see what's available
    console.log("syncLinesToTradeState called:", {
      hasWidget,
      hasActiveTrade,
      storedTP: storedLines.tp,
      storedSL: storedLines.sl,
      currentTarget: activeTradesRef.current?.target,
      currentSL: activeTradesRef.current?.stopLoss
    });

    if (!tvWidgetRef.current || !activeTradesRef.current) return;
    if (!storedLines.tp && !storedLines.sl) return;

    try {
      const chart = tvWidgetRef.current.activeChart();
      if (!chart) return;

      const currentTrade = activeTradesRef.current;
      let updated = false;
      const precision = decimalPlaces || 5;
      const updatedTrade = { ...currentTrade };

      // Check TP line position (only if TP is defined)
      if (storedLines.tp && currentTrade.target !== undefined) {
        try {
          const tpShape = chart.getShapeById(storedLines.tp);
          console.log("TP shape lookup:", { id: storedLines.tp, found: !!tpShape });
          if (tpShape) {
            const tpPoints = tpShape.getPoints();
            const tpPrice = tpPoints[0]?.price;
            console.log("TP line price:", tpPrice, "current target:", currentTrade.target);
            if (tpPrice && Math.abs(tpPrice - currentTrade.target) > 0.00001) {
              updatedTrade.target = parseFloat(tpPrice.toFixed(precision));
              updated = true;
              console.log("Synced TP from chart line:", updatedTrade.target);
            }
          }
        } catch (e) { 
          console.log("TP shape error:", e);
        }
      }

      // Check SL line position (only if SL is defined)
      if (storedLines.sl && currentTrade.stopLoss !== undefined) {
        try {
          const slShape = chart.getShapeById(storedLines.sl);
          console.log("SL shape lookup:", { id: storedLines.sl, found: !!slShape });
          if (slShape) {
            const slPoints = slShape.getPoints();
            const slPrice = slPoints[0]?.price;
            console.log("SL line price:", slPrice, "current stopLoss:", currentTrade.stopLoss);
            if (slPrice && Math.abs(slPrice - currentTrade.stopLoss) > 0.00001) {
              updatedTrade.stopLoss = parseFloat(slPrice.toFixed(precision));
              updated = true;
              console.log("Synced SL from chart line:", updatedTrade.stopLoss);
            }
          }
        } catch (e) { 
          console.log("SL shape error:", e);
        }
      }

      if (updated) {
        activeTradesRef.current = updatedTrade;
        dispatch({ type: "SET_ACTIVE_TRADE", payload: updatedTrade });
      }
    } catch (e) {
      console.error("Error syncing lines:", e);
    }
  }, [decimalPlaces]);

  useEffect(() => {
    // Sync line positions from chart before checking TP/SL hits
    syncLinesToTradeState();

    // Use ref for immediate access to latest trade values (including after dragging TP/SL)
    const trade = activeTradesRef.current;
    if (trade && allBars[currentBarIndex]) {
      const currentBar = allBars[currentBarIndex];
      const currentHigh = currentBar.high;
      const currentLow = currentBar.low;
      const currentClose = currentBar.close;
      let pnl = 0;

      if (trade.type === "long") {
        pnl = (currentClose - trade.entry) * lotSize * 100000;
        // Check if wick touched TP (high >= target) or SL (low <= stopLoss)
        if (trade.target !== undefined && currentHigh >= trade.target) {
          closeTrade(trade.target, "TP Hit", trade);
        } else if (trade.stopLoss !== undefined && currentLow <= trade.stopLoss) {
          closeTrade(trade.stopLoss, "SL Hit", trade);
        }
      } else {
        pnl = (trade.entry - currentClose) * lotSize * 100000;
        // Check if wick touched TP (low <= target) or SL (high >= stopLoss)
        if (trade.target !== undefined && currentLow <= trade.target) {
          closeTrade(trade.target, "TP Hit", trade);
        } else if (trade.stopLoss !== undefined && currentHigh >= trade.stopLoss) {
          closeTrade(trade.stopLoss, "SL Hit", trade);
        }
      }
      dispatch({ type: "SET_UNREALISED_PL", payload: pnl });

      // Update entry line label with current unrealized P&L
      updateEntryLineLabel(trade, pnl);
    }
  }, [currentBarIndex, allBars, tradingState.activeTrades, lotSize, closeTrade, syncLinesToTradeState, updateEntryLineLabel]);

  useEffect(() => {
    if (!tradingState.activeTrades && tradingState.limitOrders.length > 0 && allBars[currentBarIndex]) {
      const currentBar = allBars[currentBarIndex];
      const currentHigh = currentBar.high;
      const currentLow = currentBar.low;
      const openedAt = currentBar.time || Date.now();

      for (const order of tradingState.limitOrders) {
        let triggered = false;

        if (order.type === "long" && currentLow <= order.entryPrice && order.entryPrice <= currentHigh) {
          triggered = true;
        } else if (order.type === "short" && currentLow <= order.entryPrice && order.entryPrice <= currentHigh) {
          triggered = true;
        }

        if (triggered) {
          const trade = {
            type: order.type,
            entry: order.entryPrice,
            target: order.target,
            stopLoss: order.stopLoss,
            dbId: null as string | null,
          };
          drawTradeLines(trade);
          dispatch({ type: "REMOVE_LIMIT_ORDER", payload: order.id });
          setShowPanel(true);

          // Save to DB asynchronously
          const parsedSessionId = parseInt(sessionId);
          if (!isNaN(parsedSessionId)) {
            fetch("/api/trades", {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({
                sessionId: parsedSessionId,
                side: order.type === 'long' ? 'buy' : 'sell',
                entryPrice: order.entryPrice,
                sl: order.stopLoss,
                tp: order.target,
                size: order.lotSize || lotSize,
                openedAt: openedAt,
              }),
            })
            .then(res => res.json())
            .then(result => {
              if (result.success && result.trade?.id) {
                dispatch({ type: "SET_ACTIVE_TRADE", payload: { ...trade, dbId: result.trade.id } });
              } else {
                dispatch({ type: "SET_ACTIVE_TRADE", payload: trade });
              }
            })
            .catch(() => {
              dispatch({ type: "SET_ACTIVE_TRADE", payload: trade });
            });
          } else {
            dispatch({ type: "SET_ACTIVE_TRADE", payload: trade });
          }
          break;
        }
      }
    }
  }, [currentBarIndex, allBars, tradingState.limitOrders, tradingState.activeTrades, drawTradeLines, sessionId, lotSize]);

  const handlePlaybackSpeedChange = (speed: number) => {
    setPlaybackSpeed(500 / speed);
  };

  const handlePlaceTrade = async (type: string) => {
    if (!allBars[currentBarIndex]) return;
    const currentPrice = allBars[currentBarIndex].close;
    const openedAt = allBars[currentBarIndex]?.time || Date.now();
    const tp = currentPrice + (type === "long" ? 0.0100 : -0.0100);
    const sl = currentPrice - (type === "long" ? 0.0050 : -0.0050);

    const trade = {
      type: type,
      entry: currentPrice,
      target: tp,
      stopLoss: sl,
      dbId: null as string | null,
    };
    drawTradeLines(trade);
    setShowPanel(true);

    // Save to DB and update with dbId
    const dbId = await saveTradeToDb({
      side: type === 'long' ? 'buy' : 'sell',
      entryPrice: currentPrice,
      sl: sl,
      tp: tp,
      size: lotSize,
      openedAt: openedAt,
    });

    dispatch({ type: "SET_ACTIVE_TRADE", payload: { ...trade, dbId } });
  };

  const handlePlaceOrderFromDrawing = () => {
    if (tradingState.potentialTrade) {
      setShowOrderDialog(true);
    }
  };

  const handleMarketOrder = async () => {
    if (!tradingState.potentialTrade || !allBars[currentBarIndex]) return;
    const currentPrice = allBars[currentBarIndex].close;
    const openedAt = allBars[currentBarIndex]?.time || Date.now();
    const trade = {
      type: tradingState.potentialTrade.type,
      entry: currentPrice,
      target: tradingState.potentialTrade.target,
      stopLoss: tradingState.potentialTrade.stopLoss,
      dbId: null as string | null,
    };
    // Draw lines FIRST before any state updates to ensure immediate visibility
    drawTradeLines(trade);
    setShowOrderDialog(false);
    dispatch({ type: "SET_POTENTIAL_TRADE", payload: null });
    setShowPanel(true);

    // Save to DB and update with dbId
    const dbId = await saveTradeToDb({
      side: tradingState.potentialTrade.type === 'long' ? 'buy' : 'sell',
      entryPrice: currentPrice,
      sl: tradingState.potentialTrade.stopLoss,
      tp: tradingState.potentialTrade.target,
      size: lotSize,
      openedAt: openedAt,
    });

    dispatch({ type: "SET_ACTIVE_TRADE", payload: { ...trade, dbId } });
  };

  const handleLimitOrder = () => {
    if (!tradingState.potentialTrade) return;
    const limitOrder = {
      id: Date.now(),
      type: tradingState.potentialTrade.type,
      entryPrice: tradingState.potentialTrade.entry,
      target: tradingState.potentialTrade.target,
      stopLoss: tradingState.potentialTrade.stopLoss,
      lotSize: lotSize,
    };
    const pendingTrade = {
      entry: tradingState.potentialTrade.entry,
      target: tradingState.potentialTrade.target,
      stopLoss: tradingState.potentialTrade.stopLoss,
    };
    drawTradeLines(pendingTrade);
    setShowOrderDialog(false);
    dispatch({ type: "ADD_LIMIT_ORDER", payload: limitOrder });
    dispatch({ type: "SET_POTENTIAL_TRADE", payload: null });
  };

  const initializeOrderForm = useCallback(() => {
    if (!allBars[currentBarIndex]) return;
    const currentPrice = allBars[currentBarIndex].close;
    const pipValue = Math.pow(10, -decimalPlaces);
    const defaultSLPips = 50;
    const defaultTPPips = 100;

    setOrderFormData(prev => ({
      ...prev,
      entryPrice: currentPrice.toFixed(decimalPlaces),
      stopLoss: (prev.side === 'buy' 
        ? currentPrice - (defaultSLPips * pipValue)
        : currentPrice + (defaultSLPips * pipValue)).toFixed(decimalPlaces),
      stopLossTicks: defaultSLPips.toString(),
      takeProfit: (prev.side === 'buy'
        ? currentPrice + (defaultTPPips * pipValue)
        : currentPrice - (defaultTPPips * pipValue)).toFixed(decimalPlaces),
      takeProfitTicks: defaultTPPips.toString(),
    }));
  }, [allBars, currentBarIndex, decimalPlaces]);

  useEffect(() => {
    if (showOrderDialog) {
      if (tradingState.potentialTrade) {
        setOrderFormData(prev => ({
          ...prev,
          side: tradingState.potentialTrade.type === 'long' ? 'buy' : 'sell',
          entryPrice: tradingState.potentialTrade.entry.toFixed(decimalPlaces),
          takeProfit: tradingState.potentialTrade.target.toFixed(decimalPlaces),
          stopLoss: tradingState.potentialTrade.stopLoss.toFixed(decimalPlaces),
          stopLossTicks: Math.abs(Math.round((tradingState.potentialTrade.entry - tradingState.potentialTrade.stopLoss) / Math.pow(10, -decimalPlaces))).toString(),
          takeProfitTicks: Math.abs(Math.round((tradingState.potentialTrade.target - tradingState.potentialTrade.entry) / Math.pow(10, -decimalPlaces))).toString(),
        }));
      } else {
        initializeOrderForm();
      }
    }
  }, [showOrderDialog, initializeOrderForm, tradingState.potentialTrade, decimalPlaces]);

  const calculateRiskAmount = () => {
    const balance = orderFormData.balanceType === 'initial' ? initialBalance : totalBalance;
    return (balance * orderFormData.riskPercent) / 100;
  };

  const calculateEstimatedLoss = () => {
    const riskAmount = calculateRiskAmount();
    return -riskAmount;
  };

  const calculateEstimatedProfit = () => {
    if (!orderFormData.entryPrice || !orderFormData.takeProfit || !orderFormData.stopLoss) return 0;
    const entry = parseFloat(orderFormData.entryPrice);
    const tp = parseFloat(orderFormData.takeProfit);
    const sl = parseFloat(orderFormData.stopLoss);

    const tpDistance = Math.abs(tp - entry);
    const slDistance = Math.abs(entry - sl);

    if (slDistance === 0) return 0;
    const riskRewardRatio = tpDistance / slDistance;
    return calculateRiskAmount() * riskRewardRatio;
  };

  const calculatePositionSize = () => {
    if (!orderFormData.entryPrice || !orderFormData.stopLoss) return 0;
    const entry = parseFloat(orderFormData.entryPrice);
    const sl = parseFloat(orderFormData.stopLoss);
    const slDistance = Math.abs(entry - sl);

    if (slDistance === 0) return 0;
    const riskAmount = calculateRiskAmount();
    // Position size formula derived from P&L formula:
    // P&L = priceChange * lotSize * 100000
    // To risk exactly riskAmount at SL: lotSize = riskAmount / (slDistance * 100000)
    return riskAmount / (slDistance * 100000);
  };

  const saveTradeToDb = async (tradeData: {
    side: string;
    entryPrice: number;
    sl: number;
    tp: number;
    size: number;
    openedAt: number;
  }): Promise<string | null> => {
    const parsedSessionId = parseInt(sessionId);
    if (isNaN(parsedSessionId)) return null;

    try {
      const res = await fetch("/api/trades", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          sessionId: parsedSessionId,
          ...tradeData,
        }),
      });
      const result = await res.json();
      if (result.success && result.trade?.id) {
        return result.trade.id;
      }
    } catch (error) {
      console.error("Failed to save trade to DB:", error);
    }
    return null;
  };

  const handleOrderFormSubmit = async (action: 'save' | 'save_journal') => {
    if (!allBars[currentBarIndex]) return;

    const entry = orderFormData.orderType === 'market' 
      ? allBars[currentBarIndex].close 
      : parseFloat(orderFormData.entryPrice);
    const tp = orderFormData.takeProfitEnabled 
      ? (parseFloat(orderFormData.takeProfit) || entry + (orderFormData.side === 'buy' ? 0.01 : -0.01))
      : undefined;
    const sl = orderFormData.stopLossEnabled 
      ? (parseFloat(orderFormData.stopLoss) || entry - (orderFormData.side === 'buy' ? 0.005 : -0.005))
      : undefined;
    const posSize = parseFloat(orderFormData.positionSize) || calculatePositionSize();

    const tradeType = orderFormData.side === 'buy' ? 'long' : 'short';
    const openedAt = allBars[currentBarIndex]?.time || Date.now();

    if (orderFormData.orderType === 'market') {
      const trade = {
        type: tradeType,
        entry: entry,
        target: tp,
        stopLoss: sl,
        dbId: null as string | null,
      };
      drawTradeLines(trade);
      setShowOrderDialog(false);
      setLotSize(posSize);
      setShowPanel(true);

      // Save to DB and update with dbId
      const dbId = await saveTradeToDb({
        side: orderFormData.side,
        entryPrice: entry,
        sl: sl,
        tp: tp,
        size: posSize,
        openedAt: openedAt,
      });

      dispatch({ type: "SET_ACTIVE_TRADE", payload: { ...trade, dbId } });
    } else {
      const limitOrder = {
        id: Date.now(),
        type: tradeType,
        entryPrice: entry,
        target: tp,
        stopLoss: sl,
        lotSize: posSize,
      };
      const pendingTrade = { entry, target: tp, stopLoss: sl };
      drawTradeLines(pendingTrade);
      setShowOrderDialog(false);
      dispatch({ type: "ADD_LIMIT_ORDER", payload: limitOrder });
    }

    setOrderFormData(prev => ({ ...prev, side: 'buy' }));
  };

  const updateStopLossFromTicks = (ticks: string) => {
    const ticksNum = parseInt(ticks) || 0;
    const pipValue = Math.pow(10, -decimalPlaces);
    const entry = parseFloat(orderFormData.entryPrice) || 0;
    const newSL = orderFormData.side === 'buy'
      ? entry - (ticksNum * pipValue)
      : entry + (ticksNum * pipValue);
    setOrderFormData(prev => ({
      ...prev,
      stopLossTicks: ticks,
      stopLoss: newSL.toFixed(decimalPlaces),
    }));
  };

  const updateTakeProfitFromTicks = (ticks: string) => {
    const ticksNum = parseInt(ticks) || 0;
    const pipValue = Math.pow(10, -decimalPlaces);
    const entry = parseFloat(orderFormData.entryPrice) || 0;
    const newTP = orderFormData.side === 'buy'
      ? entry + (ticksNum * pipValue)
      : entry - (ticksNum * pipValue);
    setOrderFormData(prev => ({
      ...prev,
      takeProfitTicks: ticks,
      takeProfit: newTP.toFixed(decimalPlaces),
    }));
  };

  const handleManualClose = () => {
    if (tradingState.activeTrades && allBars[currentBarIndex]) {
      closeTrade(allBars[currentBarIndex].close, "Manual Close", tradingState.activeTrades);
    }
  };

  const handleModifyTrade = () => {
    if (tradingState.activeTrades) {
      setModifyTradeData({
        newTP: tradingState.activeTrades.target.toString(),
        newSL: tradingState.activeTrades.stopLoss.toString(),
      });
      setShowModifyTradePopup(true);
    }
  };

  const executeModifyTrade = () => {
    if (tradingState.activeTrades) {
      dispatch({
        type: "SET_ACTIVE_TRADE",
        payload: {
          ...tradingState.activeTrades,
          target: parseFloat(modifyTradeData.newTP),
          stopLoss: parseFloat(modifyTradeData.newSL),
        },
      });
      setShowModifyTradePopup(false);
    }
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.target as HTMLElement).tagName === "INPUT") return;

      // Ctrl + Space = advance one candle
      if (e.ctrlKey && e.code === "Space") {
        e.preventDefault();
        if (!isEndReached) handleNext();
        return;
      }

      switch (e.code) {
        case "Space":
          e.preventDefault();
          if (!isEndReached) togglePlayPause();
          break;
        case "ArrowRight":
          e.preventDefault();
          if (!isEndReached) handleNext();
          break;
        case "KeyB":
          if (!tradingState.activeTrades && !tradingState.potentialTrade) handlePlaceTrade("long");
          break;
        case "KeyS":
          if (!tradingState.activeTrades && !tradingState.potentialTrade) handlePlaceTrade("short");
          break;
        case "KeyP":
          if (tradingState.potentialTrade && !tradingState.activeTrades) handlePlaceOrderFromDrawing();
          break;
        case "Escape":
          setShowPanel(false);
          setShowModifyTradePopup(false);
          setShowOrderDialog(false);
          break;
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [isEndReached, handleNext, tradingState.activeTrades, tradingState.potentialTrade]);

  const speedOptions = [
    { value: 0.25, label: "0.25x" },
    { value: 0.5, label: "0.5x" },
    { value: 1, label: "1x" },
    { value: 2, label: "2x" },
    { value: 4, label: "4x" },
    { value: 8, label: "8x" },
  ];
  const currentSpeed = 500 / playbackSpeed;

  const currentBar = allBars[currentBarIndex];
  const currentTime = currentBar
    ? new Date(currentBar.time).toLocaleString("en-US", {
        month: "short",
        day: "numeric",
        hour: "2-digit",
        minute: "2-digit",
        hour12: false,
        timeZone: "UTC",
      })
    : "...";

  if (sessionLoading) {
    return (
      <div className="bt-container">
        <div className="bt-loading">
          <div className="bt-spinner"></div>
          <span>Loading session...</span>
        </div>
      </div>
    );
  }

  return (
    <div className="bt-container">
      <header className="bt-header-modern">
        <div className="bt-header-section">
          <button className="bt-back-btn" onClick={() => router.push("/backtesting/dashboard")}>
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
              <path d="M19 12H5M12 19l-7-7 7-7"/>
            </svg>
          </button>

          <div className="bt-session-pill">
            <span className="bt-session-name-text">{sessionData?.name || 'Session'}</span>
            <span className="bt-symbol-badge">{sessionData?.symbol || '...'}</span>
            <span className="bt-tf-badge">{currentInterval === "60" ? "1H" : currentInterval}</span>
          </div>

          <div className="bt-meta-pill">
            <span className="bt-meta-time">{currentTime}</span>
            <span className="bt-meta-divider">•</span>
            <span className="bt-meta-progress">{currentBarIndex + 1} / {allBars.length}</span>
          </div>
        </div>

        <div className="bt-header-section bt-stats-row">
        </div>

        <div className="bt-header-section">
          <button 
            className="bt-analytics-btn" 
            onClick={() => router.push('/backtesting/sessions')}
          >
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <path d="M18 20V10M12 20V4M6 20v-6"/>
            </svg>
            Analytics
          </button>
        </div>
      </header>

      <main className="bt-chart-area" style={{ marginBottom: isDrawerCollapsed ? drawerCollapsedHeight : drawerHeight }}>
        {/* Floating Replay Control Bar */}
        <div 
          className={`bt-floating-bar ${isDragging ? 'dragging' : ''}`}
          style={barPosition ? { 
            position: 'fixed',
            left: barPosition.x, 
            top: barPosition.y, 
            transform: 'none' 
          } : undefined}
        >
          {/* Drag Handle */}
          <div className="bt-float-drag" onMouseDown={handleBarDragStart}>
            <svg width="8" height="14" viewBox="0 0 8 14" fill="currentColor">
              <circle cx="2" cy="2" r="1.5"/>
              <circle cx="6" cy="2" r="1.5"/>
              <circle cx="2" cy="7" r="1.5"/>
              <circle cx="6" cy="7" r="1.5"/>
              <circle cx="2" cy="12" r="1.5"/>
              <circle cx="6" cy="12" r="1.5"/>
            </svg>
          </div>

          {/* Navigation Group */}
          <div className="bt-float-group">
            <button onClick={togglePlayPause} disabled={isEndReached} className="bt-float-btn play" title={isPlaying ? "Pause" : "Play"}>
              {isPlaying ? (
                <svg width="12" height="12" viewBox="0 0 24 24" fill="currentColor">
                  <path d="M6 4h4v16H6V4zm8 0h4v16h-4V4z"/>
                </svg>
              ) : (
                <svg width="12" height="12" viewBox="0 0 24 24" fill="currentColor">
                  <path d="M8 5v14l11-7L8 5z"/>
                </svg>
              )}
            </button>
            <button onClick={handleNext} disabled={isEndReached} className="bt-float-btn" title="Next">
              <svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor">
                <path d="M9 5v14l10-7L9 5z"/>
              </svg>
            </button>
          </div>

          <div className="bt-float-divider"></div>

          {/* Speed Slider Group */}
          <div className="bt-float-group speed-group">
            <span className="bt-float-label">Speed</span>
            <input
              type="range"
              min="1"
              max="10"
              value={speedMultiplier}
              onChange={(e) => handleSpeedSliderChange(parseInt(e.target.value))}
              className="bt-float-range"
            />
            <span className="bt-float-speed-value">{speedMultiplier}x</span>
          </div>

          <div className="bt-float-divider"></div>

          {/* Timeframe Dropdown */}
          <div className="bt-float-timeframe">
            <button 
              className="bt-float-tf-btn" 
              onClick={() => setShowTimeframeDropdown(!showTimeframeDropdown)}
            >
              {timeframeOptions.find(tf => tf.value === currentInterval)?.label || '1H'}
              <svg width="10" height="10" viewBox="0 0 24 24" fill="currentColor">
                <path d="M7 10l5 5 5-5H7z"/>
              </svg>
            </button>
            {showTimeframeDropdown && (
              <div className="bt-float-tf-dropdown">
                {timeframeOptions.map((tf) => (
                  <button
                    key={tf.value}
                    className={`bt-float-tf-option ${currentInterval === tf.value ? 'active' : ''}`}
                    onClick={() => handleTimeframeChange(tf.value)}
                  >
                    {tf.label}
                  </button>
                ))}
                <div className="bt-float-tf-divider"></div>
                {showCustomTfInput ? (
                  <div className="bt-float-tf-custom-input">
                    <input
                      type="number"
                      placeholder="e.g. 69"
                      value={customTfInput}
                      onChange={(e) => setCustomTfInput(e.target.value)}
                      onKeyDown={(e) => e.key === 'Enter' && handleCustomTf()}
                      autoFocus
                    />
                    <button onClick={handleCustomTf}>Go</button>
                  </div>
                ) : (
                  <button
                    className="bt-float-tf-option custom"
                    onClick={() => setShowCustomTfInput(true)}
                  >
                    Custom...
                  </button>
                )}
              </div>
            )}
          </div>

          <div className="bt-float-divider"></div>

          {/* Trade Buttons */}
          <div className="bt-float-group trade-group">
            {tradingState.potentialTrade ? (
              <button
                onClick={handlePlaceOrderFromDrawing}
                disabled={!!tradingState.activeTrades}
                className="bt-float-trade-btn place"
              >
                Place {tradingState.potentialTrade.type === 'long' ? 'Long' : 'Short'}
              </button>
            ) : (
              <>
                <button
                  onClick={() => setShowOrderDialog(true)}
                  disabled={!!tradingState.activeTrades}
                  className="bt-float-trade-btn buy"
                >
                  Buy
                </button>
                <button
                  onClick={() => { setOrderFormData(prev => ({ ...prev, side: 'sell' })); setShowOrderDialog(true); }}
                  disabled={!!tradingState.activeTrades}
                  className="bt-float-trade-btn sell"
                >
                  Sell
                </button>
              </>
            )}
          </div>
        </div>

        {/* Chart Container */}
        <div className="bt-chart-wrapper">
          {isLoading && (
            <div className="bt-chart-loading">
              <div className="bt-spinner"></div>
              <span>Loading chart data...</span>
            </div>
          )}
          <div className="bt-chart" ref={chartContainerRef}></div>
        </div>
      </main>

      <footer className="bt-status-bar">
        <div className="bt-status-left">
          <div className="bt-status-drag">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor">
              <circle cx="8" cy="6" r="2"/>
              <circle cx="16" cy="6" r="2"/>
              <circle cx="8" cy="12" r="2"/>
              <circle cx="16" cy="12" r="2"/>
              <circle cx="8" cy="18" r="2"/>
              <circle cx="16" cy="18" r="2"/>
            </svg>
          </div>
          <button className="bt-status-analytics">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <path d="M3 3v18h18"/>
              <path d="M18 9l-5 5-4-4-3 3"/>
            </svg>
            Analytics
          </button>
        </div>

        <div className="bt-status-center">
          <div className="bt-status-item">
            <span className="bt-status-label">Account Balance:</span>
            <span className="bt-status-value">${totalBalance.toFixed(2)}</span>
          </div>
          <div className="bt-status-item">
            <span className="bt-status-label">Realized PnL:</span>
            <span className={`bt-status-value ${tradingState.realisedPL >= 0 ? 'profit' : 'loss'}`}>
              {tradingState.realisedPL >= 0 ? '' : '-'}${Math.abs(tradingState.realisedPL).toFixed(2)}
            </span>
          </div>
          <div className="bt-status-item">
            <span className="bt-status-label">Unrealized PnL:</span>
            <span className={`bt-status-value ${tradingState.unrealisedPL >= 0 ? 'profit' : 'loss'}`}>
              ${tradingState.unrealisedPL.toFixed(2)}
            </span>
          </div>
        </div>

        <div className="bt-status-right">
          <button className="bt-status-icon" onClick={() => router.push("/backtesting/dashboard")} title="Exit to Dashboard">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <path d="M9 21H5a2 2 0 01-2-2V5a2 2 0 012-2h4"/>
              <polyline points="16 17 21 12 16 7"/>
              <line x1="21" y1="12" x2="9" y2="12"/>
            </svg>
          </button>
          <button 
            className="bt-status-icon" 
            onClick={() => {
              if (document.fullscreenElement) {
                document.exitFullscreen();
              } else {
                document.documentElement.requestFullscreen();
              }
            }}
            title="Toggle Fullscreen"
          >
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <path d="M8 3H5a2 2 0 00-2 2v3m18 0V5a2 2 0 00-2-2h-3m0 18h3a2 2 0 002-2v-3M3 16v3a2 2 0 002 2h3"/>
            </svg>
          </button>
        </div>
      </footer>

      {/* Bottom Drawer Panel */}
      <div 
        className={`bt-bottom-drawer ${isDrawerResizing ? 'resizing' : ''} ${isDrawerCollapsed ? 'collapsed' : ''}`}
        style={{ height: isDrawerCollapsed ? drawerCollapsedHeight : drawerHeight }}
      >
        {!isDrawerCollapsed && (
          <div 
            className="bt-drawer-resize-handle" 
            onMouseDown={handleDrawerResizeStart}
          />
        )}
        <div className="bt-drawer-header">
          <div className="bt-drawer-tabs">
            <button 
              className={`bt-drawer-tab ${activeDrawerTab === 'open' ? 'active' : ''}`}
              onClick={() => { setActiveDrawerTab('open'); if (isDrawerCollapsed) setIsDrawerCollapsed(false); }}
            >
              Open Positions
              <span className="bt-drawer-tab-count">
                {tradingState.activeTrades ? 1 : 0}
              </span>
            </button>
            <button 
              className={`bt-drawer-tab ${activeDrawerTab === 'pending' ? 'active' : ''}`}
              onClick={() => { setActiveDrawerTab('pending'); if (isDrawerCollapsed) setIsDrawerCollapsed(false); }}
            >
              Pending Orders
              <span className="bt-drawer-tab-count">
                {tradingState.limitOrders?.length || 0}
              </span>
            </button>
            <button 
              className={`bt-drawer-tab ${activeDrawerTab === 'closed' ? 'active' : ''}`}
              onClick={() => { setActiveDrawerTab('closed'); if (isDrawerCollapsed) setIsDrawerCollapsed(false); }}
            >
              Closed Positions
              <span className="bt-drawer-tab-count">
                {tradingState.tradeHistory.length}
              </span>
            </button>
          </div>

          <div className="bt-drawer-stats">
            <div className="bt-drawer-stat">
              <span className="bt-drawer-stat-label">Balance:</span>
              <span className="bt-drawer-stat-value">${totalBalance.toFixed(2)}</span>
            </div>
            <div className="bt-drawer-stat">
              <span className="bt-drawer-stat-label">Realized:</span>
              <span className={`bt-drawer-stat-value ${tradingState.realisedPL >= 0 ? 'profit' : 'loss'}`}>
                ${tradingState.realisedPL.toFixed(2)}
              </span>
            </div>
            <div className="bt-drawer-stat">
              <span className="bt-drawer-stat-label">Unrealized:</span>
              <span className={`bt-drawer-stat-value ${tradingState.unrealisedPL >= 0 ? 'profit' : 'loss'}`}>
                ${tradingState.unrealisedPL.toFixed(2)}
              </span>
            </div>
          </div>

          <div className="bt-drawer-actions">
            <button 
              className="bt-drawer-toggle-btn" 
              onClick={() => setIsDrawerCollapsed(!isDrawerCollapsed)}
              title={isDrawerCollapsed ? "Expand panel" : "Collapse panel"}
            >
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                {isDrawerCollapsed ? (
                  <path d="M18 15l-6-6-6 6"/>
                ) : (
                  <path d="M6 9l6 6 6-6"/>
                )}
              </svg>
            </button>
          </div>
        </div>

        <div className="bt-drawer-content">
          {activeDrawerTab === 'open' && (
            <>
              {tradingState.activeTrades ? (
                <table className="bt-trade-table">
                  <thead>
                    <tr>
                      <th>Asset</th>
                      <th>Side</th>
                      <th>Size</th>
                      <th>Entry</th>
                      <th>Take Profit</th>
                      <th>Stop Loss</th>
                      <th>Unrealized</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    <tr>
                      <td className="bt-table-symbol">{sessionData?.symbol || 'N/A'}</td>
                      <td>
                        <span className={`bt-table-side ${tradingState.activeTrades.type}`}>
                          {tradingState.activeTrades.type === 'long' ? 'BUY' : 'SELL'}
                        </span>
                      </td>
                      <td className="bt-table-value">{lotSize}</td>
                      <td className="bt-table-value">{tradingState.activeTrades.entry.toFixed(decimalPlaces || 5)}</td>
                      <td className="bt-table-value profit">
                        {tradingState.activeTrades.target !== undefined 
                          ? tradingState.activeTrades.target.toFixed(decimalPlaces || 5) 
                          : '-'}
                      </td>
                      <td className="bt-table-value loss">
                        {tradingState.activeTrades.stopLoss !== undefined 
                          ? tradingState.activeTrades.stopLoss.toFixed(decimalPlaces || 5) 
                          : '-'}
                      </td>
                      <td className={`bt-table-value ${tradingState.unrealisedPL >= 0 ? 'profit' : 'loss'}`}>
                        {tradingState.unrealisedPL >= 0 ? '+' : ''}${tradingState.unrealisedPL.toFixed(2)}
                      </td>
                      <td>
                        <div className="bt-table-actions">
                          <button 
                            className="bt-table-action-btn edit" 
                            onClick={handleModifyTrade}
                            title="Modify"
                          >
                            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                              <path d="M11 4H4a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-7"/>
                              <path d="M18.5 2.5a2.121 2.121 0 013 3L12 15l-4 1 1-4 9.5-9.5z"/>
                            </svg>
                          </button>
                          <button 
                            className="bt-table-action-btn close" 
                            onClick={handleManualClose}
                            title="Close"
                          >
                            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                              <path d="M18 6L6 18M6 6l12 12"/>
                            </svg>
                          </button>
                        </div>
                      </td>
                    </tr>
                  </tbody>
                </table>
              ) : (
                <div className="bt-table-empty">
                  <div className="bt-table-empty-icon">
                    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5">
                      <path d="M12 2v20M2 12h20"/>
                    </svg>
                  </div>
                  <p>No open positions</p>
                  <span className="bt-hint">Press B to buy or S to sell</span>
                </div>
              )}
            </>
          )}

          {activeDrawerTab === 'pending' && (
            <>
              {tradingState.limitOrders && tradingState.limitOrders.length > 0 ? (
                <table className="bt-trade-table">
                  <thead>
                    <tr>
                      <th>Asset</th>
                      <th>Side</th>
                      <th>Size</th>
                      <th>Entry Price</th>
                      <th>Take Profit</th>
                      <th>Stop Loss</th>
                      <th>Status</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {tradingState.limitOrders.map((order: any) => (
                      <tr key={order.id}>
                        <td className="bt-table-symbol">{sessionData?.symbol || 'N/A'}</td>
                        <td>
                          <span className={`bt-table-side ${order.type}`}>
                            {order.type === 'long' ? 'BUY LIMIT' : 'SELL LIMIT'}
                          </span>
                        </td>
                        <td className="bt-table-value">{order.size || lotSize}</td>
                        <td className="bt-table-value">{order.entry?.toFixed(decimalPlaces || 5) || '-'}</td>
                        <td className="bt-table-value profit">
                          {order.target !== undefined ? order.target.toFixed(decimalPlaces || 5) : '-'}
                        </td>
                        <td className="bt-table-value loss">
                          {order.stopLoss !== undefined ? order.stopLoss.toFixed(decimalPlaces || 5) : '-'}
                        </td>
                        <td className="bt-table-value muted">Pending</td>
                        <td>
                          <div className="bt-table-actions">
                            <button 
                              className="bt-table-action-btn close" 
                              onClick={() => dispatch({ type: 'REMOVE_LIMIT_ORDER', payload: order.id })}
                              title="Cancel Order"
                            >
                              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                                <path d="M18 6L6 18M6 6l12 12"/>
                              </svg>
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              ) : (
                <div className="bt-table-empty">
                  <div className="bt-table-empty-icon">
                    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5">
                      <rect x="3" y="3" width="18" height="18" rx="2"/>
                      <path d="M9 12h6"/>
                    </svg>
                  </div>
                  <p>No pending orders</p>
                  <span className="bt-hint">Use Place Order to create limit orders</span>
                </div>
              )}
            </>
          )}

          {activeDrawerTab === 'closed' && (
            <>
              {tradingState.tradeHistory.length > 0 ? (
                <table className="bt-trade-table">
                  <thead>
                    <tr>
                      <th>Asset</th>
                      <th>Side</th>
                      <th>Size</th>
                      <th>Entry</th>
                      <th>Exit</th>
                      <th>Exit Reason</th>
                      <th>Realized</th>
                      <th>Commission</th>
                    </tr>
                  </thead>
                  <tbody>
                    {tradingState.tradeHistory.map((trade: any) => (
                      <tr key={trade.id}>
                        <td className="bt-table-symbol">{sessionData?.symbol || 'N/A'}</td>
                        <td>
                          <span className={`bt-table-side ${trade.type}`}>
                            {trade.type === 'long' ? 'BUY' : 'SELL'}
                          </span>
                        </td>
                        <td className="bt-table-value">{trade.size || lotSize}</td>
                        <td className="bt-table-value">{trade.entry?.toFixed(decimalPlaces || 5) || '-'}</td>
                        <td className="bt-table-value">{trade.exit?.toFixed(decimalPlaces || 5) || '-'}</td>
                        <td className="bt-table-value muted">{trade.reason || 'Manual'}</td>
                        <td className={`bt-table-value ${trade.pnl >= 0 ? 'profit' : 'loss'}`}>
                          {trade.pnl >= 0 ? '+' : ''}${trade.pnl.toFixed(2)}
                        </td>
                        <td className="bt-table-value muted">$0.00</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              ) : (
                <div className="bt-table-empty">
                  <div className="bt-table-empty-icon">
                    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5">
                      <path d="M22 11.08V12a10 10 0 11-5.93-9.14"/>
                      <path d="M22 4L12 14.01l-3-3"/>
                    </svg>
                  </div>
                  <p>No closed positions</p>
                  <span className="bt-hint">Completed trades will appear here</span>
                </div>
              )}
            </>
          )}
        </div>
      </div>

      {showModifyTradePopup && (
        <div className="bt-modal-overlay" onClick={() => setShowModifyTradePopup(false)}>
          <div className="bt-modal" onClick={(e) => e.stopPropagation()}>
            <h3>Modify Trade</h3>
            <div className="bt-input-group">
              <label>Take Profit</label>
              <input
                type="number"
                value={modifyTradeData.newTP}
                onChange={(e) => setModifyTradeData({ ...modifyTradeData, newTP: e.target.value })}
                step="0.00001"
              />
            </div>
            <div className="bt-input-group">
              <label>Stop Loss</label>
              <input
                type="number"
                value={modifyTradeData.newSL}
                onChange={(e) => setModifyTradeData({ ...modifyTradeData, newSL: e.target.value })}
                step="0.00001"
              />
            </div>
            <div className="bt-modal-actions">
              <button onClick={() => setShowModifyTradePopup(false)} className="bt-modal-btn cancel">Cancel</button>
              <button onClick={executeModifyTrade} className="bt-modal-btn save">Save</button>
            </div>
          </div>
        </div>
      )}

      {showOrderDialog && (
        <div className="bt-modal-overlay" onClick={() => setShowOrderDialog(false)}>
          <div className="bt-order-modal" onClick={(e) => e.stopPropagation()}>
            <div className="bt-order-modal-header">
              <h3>Place Order</h3>
              <button className="bt-modal-close" onClick={() => setShowOrderDialog(false)}>
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <path d="M18 6L6 18M6 6l12 12"/>
                </svg>
              </button>
            </div>

            <div className="bt-order-balance-toggle">
              <div className="bt-order-balance-toggle-inner">
                <label className={`bt-radio-option ${orderFormData.balanceType === 'initial' ? 'active' : ''}`}>
                  <input 
                    type="radio" 
                    checked={orderFormData.balanceType === 'initial'}
                    onChange={() => setOrderFormData(prev => ({ ...prev, balanceType: 'initial' }))}
                  />
                  Initial Balance
                </label>
                <label className={`bt-radio-option ${orderFormData.balanceType === 'current' ? 'active' : ''}`}>
                  <input 
                    type="radio" 
                    checked={orderFormData.balanceType === 'current'}
                    onChange={() => setOrderFormData(prev => ({ ...prev, balanceType: 'current' }))}
                  />
                  Current Balance
                </label>
              </div>
            </div>

            <div className="bt-order-estimates">
              <div className="bt-estimate loss">
                <span className="bt-estimate-label">Estimated Loss</span>
                <span className="bt-estimate-value">${calculateEstimatedLoss().toFixed(2)}</span>
              </div>
              <div className="bt-estimate profit">
                <span className="bt-estimate-label">Estimated Profit</span>
                <span className="bt-estimate-value">${calculateEstimatedProfit().toFixed(2)}</span>
              </div>
            </div>

            <div className="bt-order-section">
              <label className="bt-order-section-label">Set risk percentage</label>
              <div className="bt-risk-presets">
                {[0.30, 0.50, 0.70, 1, 2, 3].map((pct) => (
                  <button
                    key={pct}
                    className={`bt-risk-btn ${orderFormData.riskPercent === pct ? 'active' : ''}`}
                    onClick={() => setOrderFormData(prev => ({ ...prev, riskPercent: pct }))}
                  >
                    {pct}%
                  </button>
                ))}
              </div>
            </div>

            <div className="bt-order-row">
              <div className="bt-order-field">
                <label>Side</label>
                <div className="bt-select-wrapper">
                  <select
                    value={orderFormData.side}
                    onChange={(e) => {
                      setOrderFormData(prev => ({ ...prev, side: e.target.value as 'buy' | 'sell' }));
                      setTimeout(initializeOrderForm, 0);
                    }}
                  >
                    <option value="buy">Buy</option>
                    <option value="sell">Sell</option>
                  </select>
                  <svg className="bt-select-arrow" width="12" height="12" viewBox="0 0 24 24" fill="currentColor">
                    <path d="M7 10l5 5 5-5H7z"/>
                  </svg>
                </div>
              </div>
              <div className="bt-order-field">
                <label>Type</label>
                <div className="bt-select-wrapper">
                  <select
                    value={orderFormData.orderType}
                    onChange={(e) => setOrderFormData(prev => ({ ...prev, orderType: e.target.value as 'market' | 'limit' }))}
                  >
                    <option value="market">Market</option>
                    <option value="limit">Limit</option>
                  </select>
                  <svg className="bt-select-arrow" width="12" height="12" viewBox="0 0 24 24" fill="currentColor">
                    <path d="M7 10l5 5 5-5H7z"/>
                  </svg>
                </div>
              </div>
            </div>

            <div className="bt-order-row">
              <div className="bt-order-field">
                <label>Risk Percent</label>
                <div className="bt-input-with-icon">
                  <span className="bt-input-icon">%</span>
                  <input
                    type="number"
                    value={orderFormData.riskPercent}
                    onChange={(e) => setOrderFormData(prev => ({ ...prev, riskPercent: parseFloat(e.target.value) || 0 }))}
                    step="0.1"
                  />
                </div>
              </div>
              <div className="bt-order-field">
                <label>Risk Amount</label>
                <div className="bt-input-with-icon">
                  <span className="bt-input-icon">$</span>
                  <input
                    type="text"
                    value={calculateRiskAmount().toFixed(2)}
                    readOnly
                    className="bt-readonly"
                  />
                </div>
              </div>
            </div>

            <div className="bt-order-row">
              <div className="bt-order-field">
                <label>Position Size (Contracts) *</label>
                <input
                  type="number"
                  value={orderFormData.positionSize || calculatePositionSize().toFixed(2)}
                  onChange={(e) => setOrderFormData(prev => ({ ...prev, positionSize: e.target.value }))}
                  step="0.01"
                  placeholder={calculatePositionSize().toFixed(2)}
                />
              </div>
              <div className="bt-order-field">
                <label>Entry Price *</label>
                <input
                  type="number"
                  value={orderFormData.entryPrice}
                  onChange={(e) => setOrderFormData(prev => ({ ...prev, entryPrice: e.target.value }))}
                  step="0.00001"
                  disabled={orderFormData.orderType === 'market'}
                  className={orderFormData.orderType === 'market' ? 'bt-readonly' : ''}
                />
              </div>
            </div>

            <div className="bt-order-toggle-row">
              <label className="bt-toggle">
                <input
                  type="checkbox"
                  checked={orderFormData.restrictedPositionSize}
                  onChange={(e) => setOrderFormData(prev => ({ ...prev, restrictedPositionSize: e.target.checked }))}
                />
                <span className="bt-toggle-slider"></span>
              </label>
              <span>Restricted Position Size</span>
            </div>

            <div className="bt-order-sl-tp-section">
              <div className="bt-sl-tp-header">
                <label className="bt-toggle">
                  <input
                    type="checkbox"
                    checked={orderFormData.stopLossEnabled}
                    onChange={(e) => setOrderFormData(prev => ({ ...prev, stopLossEnabled: e.target.checked }))}
                  />
                  <span className="bt-toggle-slider"></span>
                </label>
                <span>Stop Loss</span>
              </div>
              {orderFormData.stopLossEnabled && (
                <div className="bt-order-row">
                  <div className="bt-order-field">
                    <label>Stop Loss *</label>
                    <input
                      type="number"
                      value={orderFormData.stopLoss}
                      onChange={(e) => setOrderFormData(prev => ({ ...prev, stopLoss: e.target.value }))}
                      step="0.00001"
                    />
                  </div>
                  <div className="bt-order-field">
                    <label>Stop Loss in ticks *</label>
                    <div className="bt-input-with-suffix">
                      <input
                        type="number"
                        value={orderFormData.stopLossTicks}
                        onChange={(e) => updateStopLossFromTicks(e.target.value)}
                      />
                      <span className="bt-input-suffix">ticks</span>
                    </div>
                  </div>
                </div>
              )}
            </div>

            <div className="bt-order-sl-tp-section">
              <div className="bt-sl-tp-header">
                <label className="bt-toggle">
                  <input
                    type="checkbox"
                    checked={orderFormData.takeProfitEnabled}
                    onChange={(e) => setOrderFormData(prev => ({ ...prev, takeProfitEnabled: e.target.checked }))}
                  />
                  <span className="bt-toggle-slider"></span>
                </label>
                <span>Take Profit</span>
              </div>
              {orderFormData.takeProfitEnabled && (
                <div className="bt-order-row">
                  <div className="bt-order-field">
                    <label>Take Profit *</label>
                    <input
                      type="number"
                      value={orderFormData.takeProfit}
                      onChange={(e) => setOrderFormData(prev => ({ ...prev, takeProfit: e.target.value }))}
                      step="0.00001"
                    />
                  </div>
                  <div className="bt-order-field">
                    <label>Take Profit in ticks *</label>
                    <div className="bt-input-with-suffix">
                      <input
                        type="number"
                        value={orderFormData.takeProfitTicks}
                        onChange={(e) => updateTakeProfitFromTicks(e.target.value)}
                      />
                      <span className="bt-input-suffix">ticks</span>
                    </div>
                  </div>
                </div>
              )}
            </div>

            <div className="bt-order-actions">
              <button className="bt-order-action-btn discard" onClick={() => setShowOrderDialog(false)}>
                Discard
              </button>
              <button className="bt-order-action-btn save" onClick={() => handleOrderFormSubmit('save')}>
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z"/>
                  <polyline points="17 21 17 13 7 13 7 21"/>
                  <polyline points="7 3 7 8 15 8"/>
                </svg>
                Save
              </button>
              <button className="bt-order-action-btn save-journal" onClick={() => handleOrderFormSubmit('save_journal')}>
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/>
                  <polyline points="14 2 14 8 20 8"/>
                  <line x1="16" y1="13" x2="8" y2="13"/>
                  <line x1="16" y1="17" x2="8" y2="17"/>
                </svg>
                Save & Journal
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

/* =====================================================
   ASTRAFLOW BACKTESTING DESIGN SYSTEM
   Premium Trading Interface - Modern, Sleek, Engaging
   Color Psychology: Trust (Blue), Growth (Teal), Focus (Charcoal)

   Design tokens are defined in globals.css under .dark theme
   with --af-* prefix for app-wide consistency
   ===================================================== */

/* Local aliases pointing to shared AstraFlow tokens from globals.css */
:root {
  --bt-bg-deep: var(--af-bg-deep, #08090b);
  --bt-bg-base: var(--af-bg-base, #0c0d10);
  --bt-bg-elevated: var(--af-bg-elevated, #12141a);
  --bt-bg-surface: var(--af-bg-surface, #181b23);
  --bt-bg-hover: var(--af-bg-hover, #1e222d);

  --bt-border-subtle: var(--af-border-subtle, rgba(255, 255, 255, 0.04));
  --bt-border-default: var(--af-border-default, rgba(255, 255, 255, 0.08));
  --bt-border-strong: var(--af-border-strong, rgba(255, 255, 255, 0.12));

  --bt-text-primary: var(--af-text-primary, #f4f4f5);
  --bt-text-secondary: var(--af-text-secondary, #a1a1aa);
  --bt-text-muted: var(--af-text-muted, #71717a);
  --bt-text-disabled: var(--af-text-disabled, #52525b);

  --bt-accent-blue: var(--af-accent-blue, #3b82f6);
  --bt-accent-blue-hover: var(--af-accent-blue-hover, #2563eb);
  --bt-accent-blue-glow: var(--af-accent-blue-glow, rgba(59, 130, 246, 0.25));

  --bt-accent-teal: var(--af-accent-teal, #14b8a6);
  --bt-accent-teal-glow: var(--af-accent-teal-glow, rgba(20, 184, 166, 0.2));

  --bt-profit: var(--af-profit, #10b981);
  --bt-profit-bg: var(--af-profit-bg, rgba(16, 185, 129, 0.12));
  --bt-profit-border: var(--af-profit-border, rgba(16, 185, 129, 0.25));
  --bt-profit-glow: var(--af-profit-glow, rgba(16, 185, 129, 0.3));

  --bt-loss: var(--af-loss, #ef4444);
  --bt-loss-bg: var(--af-loss-bg, rgba(239, 68, 68, 0.12));
  --bt-loss-border: var(--af-loss-border, rgba(239, 68, 68, 0.25));
  --bt-loss-glow: var(--af-loss-glow, rgba(239, 68, 68, 0.3));

  --bt-warning: var(--af-warning, #f59e0b);
  --bt-warning-bg: var(--af-warning-bg, rgba(245, 158, 11, 0.12));

  --bt-purple: var(--af-purple, #8b5cf6);
  --bt-purple-bg: var(--af-purple-bg, rgba(139, 92, 246, 0.12));
  --bt-purple-border: var(--af-purple-border, rgba(139, 92, 246, 0.25));

  --bt-radius-sm: 6px;
  --bt-radius-md: 10px;
  --bt-radius-lg: 14px;
  --bt-radius-xl: 20px;
  --bt-radius-full: 9999px;

  --bt-shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.3);
  --bt-shadow-md: 0 4px 16px rgba(0, 0, 0, 0.4);
  --bt-shadow-lg: 0 8px 32px rgba(0, 0, 0, 0.5);
  --bt-shadow-glow-blue: 0 0 20px var(--bt-accent-blue-glow);
  --bt-shadow-glow-profit: 0 0 20px var(--bt-profit-glow);

  --bt-transition-fast: 0.15s cubic-bezier(0.4, 0, 0.2, 1);
  --bt-transition-medium: 0.25s cubic-bezier(0.4, 0, 0.2, 1);
  --bt-transition-slow: 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

/* =====================================================
   ANIMATIONS
   ===================================================== */
@keyframes bt-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.6; }
}

@keyframes bt-glow-pulse {
  0%, 100% { box-shadow: 0 0 0 0 var(--bt-accent-blue-glow); }
  50% { box-shadow: 0 0 20px 4px var(--bt-accent-blue-glow); }
}

@keyframes bt-profit-pulse {
  0%, 100% { box-shadow: 0 0 0 0 var(--bt-profit-glow); }
  50% { box-shadow: 0 0 24px 6px var(--bt-profit-glow); }
}

@keyframes bt-loss-pulse {
  0%, 100% { box-shadow: 0 0 0 0 var(--bt-loss-glow); }
  50% { box-shadow: 0 0 24px 6px var(--bt-loss-glow); }
}

@keyframes bt-slide-up {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes bt-slide-in-right {
  from { opacity: 0; transform: translateX(16px); }
  to { opacity: 1; transform: translateX(0); }
}

@keyframes bt-fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes bt-spin {
  to { transform: rotate(360deg); }
}

@keyframes bt-shimmer {
  0% { background-position: -200% 0; }
  100% { background-position: 200% 0; }
}

@keyframes bt-confetti {
  0% { transform: translateY(0) rotate(0deg); opacity: 1; }
  100% { transform: translateY(-50px) rotate(360deg); opacity: 0; }
}

/* =====================================================
   MAIN CONTAINER
   ===================================================== */
.bt-container {
  display: flex;
  flex-direction: column;
  width: 100vw;
  height: 100vh;
  background: var(--bt-bg-deep);
  overflow: hidden;
  font-family: var(--font-sans);
}

/* Loading State */
.bt-loading {
  position: fixed;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 20px;
  background: var(--bt-bg-deep);
  z-index: 9999;
}

.bt-spinner {
  width: 48px;
  height: 48px;
  border: 3px solid var(--bt-border-default);
  border-top-color: var(--bt-accent-blue);
  border-radius: 50%;
  animation: bt-spin 1s linear infinite;
}

.bt-loading span {
  color: var(--bt-text-muted);
  font-size: 14px;
  font-weight: 500;
}

/* =====================================================
   PREMIUM HEADER
   ===================================================== */
.bt-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 56px;
  padding: 0 20px;
  background: linear-gradient(180deg, var(--bt-bg-elevated) 0%, var(--bt-bg-base) 100%);
  border-bottom: 1px solid var(--bt-border-subtle);
  flex-shrink: 0;
  position: relative;
}

.bt-header::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent 0%, var(--bt-accent-blue) 50%, transparent 100%);
  opacity: 0.3;
}

.bt-header-left {
  display: flex;
  align-items: center;
  gap: 16px;
}

.bt-back {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  background: var(--bt-bg-surface);
  border: 1px solid var(--bt-border-default);
  border-radius: var(--bt-radius-md);
  color: var(--bt-text-secondary);
  cursor: pointer;
  transition: all var(--bt-transition-fast);
}

.bt-back:hover {
  background: var(--bt-bg-hover);
  color: var(--bt-text-primary);
  border-color: var(--bt-border-strong);
  transform: translateX(-2px);
}

.bt-session-info {
  display: flex;
  align-items: center;
  gap: 12px;
}

.bt-session-badge {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  background: var(--bt-accent-blue-glow);
  border: 1px solid rgba(59, 130, 246, 0.3);
  border-radius: var(--bt-radius-full);
}

.bt-session-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--bt-text-secondary);
  max-width: 180px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bt-pair {
  font-size: 15px;
  font-weight: 700;
  color: var(--bt-text-primary);
  letter-spacing: -0.02em;
}

.bt-timeframe {
  font-size: 11px;
  font-weight: 600;
  color: var(--bt-accent-blue);
  padding: 4px 8px;
  background: var(--bt-accent-blue-glow);
  border-radius: var(--bt-radius-sm);
  letter-spacing: 0.02em;
}

.bt-divider {
  width: 1px;
  height: 24px;
  background: linear-gradient(180deg, transparent 0%, var(--bt-border-strong) 50%, transparent 100%);
}

.bt-time {
  font-size: 13px;
  font-weight: 500;
  color: var(--bt-text-secondary);
  font-family: var(--font-mono);
  letter-spacing: -0.02em;
}

.bt-bar-count {
  font-size: 11px;
  color: var(--bt-text-muted);
  font-variant-numeric: tabular-nums;
}

/* Header Center Stats */
.bt-header-center {
  display: flex;
  align-items: center;
  gap: 32px;
}

.bt-stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: 8px 16px;
  background: var(--bt-bg-surface);
  border-radius: var(--bt-radius-md);
  border: 1px solid var(--bt-border-subtle);
  transition: all var(--bt-transition-fast);
}

.bt-stat:hover {
  border-color: var(--bt-border-default);
  background: var(--bt-bg-hover);
}

.bt-stat-label {
  font-size: 10px;
  font-weight: 600;
  color: var(--bt-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.bt-stat-value {
  font-size: 14px;
  font-weight: 700;
  color: var(--bt-text-primary);
  font-variant-numeric: tabular-nums;
}

.bt-stat-value.profit {
  color: var(--bt-profit);
}

.bt-stat-value.loss {
  color: var(--bt-loss);
}

/* Header Right */
.bt-header-right {
  display: flex;
  align-items: center;
  gap: 16px;
}

.bt-lot-control {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  background: var(--bt-bg-surface);
  border-radius: var(--bt-radius-md);
  border: 1px solid var(--bt-border-subtle);
}

.bt-lot-label {
  font-size: 11px;
  font-weight: 500;
  color: var(--bt-text-muted);
}

.bt-lot-input {
  width: 64px;
  padding: 6px 10px;
  background: var(--bt-bg-hover);
  border: 1px solid var(--bt-border-default);
  border-radius: var(--bt-radius-sm);
  color: var(--bt-text-primary);
  font-size: 13px;
  font-weight: 600;
  text-align: center;
  transition: all var(--bt-transition-fast);
}

.bt-lot-input:focus {
  outline: none;
  border-color: var(--bt-accent-blue);
  box-shadow: 0 0 0 3px var(--bt-accent-blue-glow);
}

.bt-panel-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 14px;
  background: var(--bt-bg-surface);
  border: 1px solid var(--bt-border-default);
  border-radius: var(--bt-radius-md);
  color: var(--bt-text-secondary);
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--bt-transition-fast);
}

.bt-panel-btn:hover {
  background: var(--bt-bg-hover);
  color: var(--bt-text-primary);
  border-color: var(--bt-border-strong);
}

.bt-panel-btn.active {
  background: var(--bt-accent-blue-glow);
  border-color: var(--bt-accent-blue);
  color: var(--bt-accent-blue);
}

/* =====================================================
   MODERN HEADER REDESIGN
   ===================================================== */
.bt-header-modern {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 52px;
  padding: 0 16px;
  background: linear-gradient(180deg, rgba(18, 20, 26, 0.98) 0%, rgba(12, 13, 16, 0.98) 100%);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--bt-border-subtle);
  flex-shrink: 0;
  position: relative;
  gap: 16px;
}

.bt-header-modern::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent 0%, var(--bt-accent-blue) 30%, var(--bt-accent-teal) 70%, transparent 100%);
  opacity: 0.25;
}

.bt-header-section {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
}

.bt-stats-row {
  flex: 1;
  justify-content: center;
  gap: 8px;
}

/* Back Button */
.bt-back-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--bt-border-subtle);
  border-radius: 8px;
  color: var(--bt-text-muted);
  cursor: pointer;
  transition: all var(--bt-transition-fast);
}

.bt-back-btn:hover {
  background: rgba(255, 255, 255, 0.08);
  color: var(--bt-text-primary);
  border-color: var(--bt-border-default);
  transform: translateX(-2px);
}

/* Session Pill */
.bt-session-pill {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  background: linear-gradient(135deg, rgba(59, 130, 246, 0.08) 0%, rgba(20, 184, 166, 0.06) 100%);
  border: 1px solid rgba(59, 130, 246, 0.15);
  border-radius: 10px;
}

.bt-session-name-text {
  font-size: 12px;
  font-weight: 500;
  color: var(--bt-text-muted);
  max-width: 100px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bt-symbol-badge {
  font-size: 13px;
  font-weight: 700;
  color: var(--bt-text-primary);
  letter-spacing: -0.02em;
}

.bt-tf-badge {
  font-size: 10px;
  font-weight: 700;
  color: var(--bt-accent-blue);
  padding: 3px 6px;
  background: var(--bt-accent-blue-glow);
  border-radius: 5px;
  letter-spacing: 0.03em;
}

/* Meta Pill (Time & Progress) */
.bt-meta-pill {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid var(--bt-border-subtle);
  border-radius: 8px;
}

.bt-meta-time {
  font-size: 12px;
  font-weight: 500;
  color: var(--bt-text-secondary);
  font-variant-numeric: tabular-nums;
}

.bt-meta-divider {
  color: var(--bt-text-disabled);
  font-size: 10px;
}

.bt-meta-progress {
  font-size: 11px;
  color: var(--bt-text-muted);
  font-variant-numeric: tabular-nums;
}

/* Stat Pills */
.bt-stat-pill {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid var(--bt-border-subtle);
  border-radius: 10px;
  transition: all var(--bt-transition-fast);
}

.bt-stat-pill:hover {
  background: rgba(255, 255, 255, 0.05);
  border-color: var(--bt-border-default);
}

.bt-stat-pill.positive {
  background: linear-gradient(135deg, rgba(16, 185, 129, 0.08) 0%, rgba(16, 185, 129, 0.03) 100%);
  border-color: rgba(16, 185, 129, 0.15);
}

.bt-stat-pill.positive .bt-stat-icon {
  color: var(--bt-profit);
}

.bt-stat-pill.positive .bt-stat-value-modern {
  color: var(--bt-profit);
}

.bt-stat-pill.negative {
  background: linear-gradient(135deg, rgba(239, 68, 68, 0.08) 0%, rgba(239, 68, 68, 0.03) 100%);
  border-color: rgba(239, 68, 68, 0.15);
}

.bt-stat-pill.negative .bt-stat-icon {
  color: var(--bt-loss);
}

.bt-stat-pill.negative .bt-stat-value-modern {
  color: var(--bt-loss);
}

.bt-stat-pill.neutral {
  background: linear-gradient(135deg, rgba(59, 130, 246, 0.06) 0%, rgba(139, 92, 246, 0.04) 100%);
  border-color: rgba(59, 130, 246, 0.12);
}

.bt-stat-pill.neutral .bt-stat-icon {
  color: var(--bt-accent-blue);
}

.bt-stat-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  background: rgba(255, 255, 255, 0.04);
  border-radius: 6px;
  color: var(--bt-text-muted);
}

.bt-stat-content {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.bt-stat-label-modern {
  font-size: 9px;
  font-weight: 600;
  color: var(--bt-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.bt-stat-value-modern {
  font-size: 13px;
  font-weight: 700;
  color: var(--bt-text-primary);
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.01em;
}

/* Analytics Button */
.bt-analytics-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 14px;
  background: linear-gradient(135deg, var(--bt-accent-blue) 0%, #2563eb 100%);
  border: none;
  border-radius: 9px;
  color: white;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: all var(--bt-transition-fast);
  box-shadow: 0 2px 8px rgba(59, 130, 246, 0.25);
}

.bt-analytics-btn:hover {
  background: linear-gradient(135deg, #2563eb 0%, #1d4ed8 100%);
  box-shadow: 0 4px 16px rgba(59, 130, 246, 0.35);
  transform: translateY(-1px);
}

.bt-analytics-btn svg {
  opacity: 0.9;
}

/* Reset Chart Button */
.bt-reset-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 14px;
  background: linear-gradient(135deg, #374151 0%, #1f2937 100%);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 9px;
  color: rgba(255, 255, 255, 0.8);
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: all var(--bt-transition-fast);
}

.bt-reset-btn:hover {
  background: linear-gradient(135deg, #ef4444 0%, #dc2626 100%);
  border-color: rgba(239, 68, 68, 0.3);
  color: white;
  box-shadow: 0 4px 16px rgba(239, 68, 68, 0.25);
  transform: translateY(-1px);
}

.bt-reset-btn svg {
  opacity: 0.9;
}

/* =====================================================
   CHART AREA
   ===================================================== */
.bt-chart-area {
  flex: 1;
  position: relative;
  min-height: 0;
  background: var(--bt-bg-base);
}

.bt-chart-wrapper {
  position: absolute;
  inset: 0;
}

.bt-chart {
  position: absolute;
  inset: 0;
}

.bt-chart-loading {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  background: rgba(10, 10, 11, 0.85);
  backdrop-filter: blur(4px);
  z-index: 50;
  color: var(--bt-text-secondary);
  font-size: 13px;
}

.bt-chart-loading .bt-spinner {
  width: 36px;
  height: 36px;
}

.bt-chart-loading span {
  color: var(--bt-text-muted);
  font-size: 13px;
  font-weight: 500;
}

/* =====================================================
   PREMIUM FLOATING COMMAND BAR
   ===================================================== */
.bt-floating-bar {
  position: absolute;
  top: 12px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 0;
  padding: 6px 12px;
  background: linear-gradient(180deg, rgba(24, 27, 35, 0.98) 0%, rgba(18, 20, 26, 0.98) 100%);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-radius: var(--bt-radius-lg);
  border: 1px solid var(--bt-border-default);
  box-shadow: var(--bt-shadow-lg), 0 0 40px rgba(0, 0, 0, 0.4);
  z-index: 100;
  animation: bt-slide-up 0.3s ease-out;
}

.bt-floating-bar::before {
  content: '';
  position: absolute;
  inset: -1px;
  border-radius: var(--bt-radius-xl);
  background: linear-gradient(135deg, rgba(59, 130, 246, 0.2) 0%, transparent 50%, rgba(20, 184, 166, 0.2) 100%);
  z-index: -1;
  opacity: 0.5;
}

.bt-floating-bar.dragging {
  cursor: grabbing;
  user-select: none;
  box-shadow: var(--bt-shadow-lg), var(--bt-shadow-glow-blue);
}

.bt-float-drag {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 24px;
  color: var(--bt-text-disabled);
  cursor: grab;
  margin-right: 6px;
  transition: color var(--bt-transition-fast);
}

.bt-float-drag:hover {
  color: var(--bt-text-muted);
}

.bt-float-drag:active {
  cursor: grabbing;
}

.bt-float-group {
  display: flex;
  align-items: center;
  gap: 4px;
}

.bt-float-group.speed-group {
  gap: 6px;
}

/* Playback Buttons */
.bt-float-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  background: transparent;
  border: none;
  border-radius: var(--bt-radius-sm);
  color: var(--bt-text-secondary);
  cursor: pointer;
  transition: all var(--bt-transition-fast);
  position: relative;
}

.bt-float-btn:hover:not(:disabled) {
  background: var(--bt-bg-hover);
  color: var(--bt-text-primary);
  transform: scale(1.05);
}

.bt-float-btn:active:not(:disabled) {
  transform: scale(0.95);
}

.bt-float-btn:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}

/* Play Button - Premium Design */
.bt-float-btn.play {
  width: 32px;
  height: 32px;
  background: linear-gradient(135deg, var(--bt-accent-blue) 0%, #1d4ed8 100%);
  color: white;
  border-radius: 50%;
  margin: 0 6px;
  box-shadow: 0 4px 16px var(--bt-accent-blue-glow);
}

.bt-float-btn.play:hover:not(:disabled) {
  background: linear-gradient(135deg, #2563eb 0%, #1e40af 100%);
  transform: scale(1.1);
  box-shadow: 0 6px 24px var(--bt-accent-blue-glow);
}

.bt-float-btn.play:active:not(:disabled) {
  transform: scale(0.95);
}

/* Reset Button */
.bt-float-btn.reset {
  color: var(--bt-warning);
}

.bt-float-btn.reset:hover:not(:disabled) {
  background: var(--bt-warning-bg);
}

.bt-float-divider {
  width: 1px;
  height: 20px;
  background: linear-gradient(180deg, transparent 0%, var(--bt-border-strong) 50%, transparent 100%);
  margin: 0 10px;
}

/* Speed Control */
.bt-float-label {
  font-size: 10px;
  font-weight: 600;
  color: var(--bt-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.bt-float-range {
  width: 70px;
  height: 3px;
  -webkit-appearance: none;
  appearance: none;
  background: var(--bt-bg-hover);
  border-radius: 2px;
  cursor: pointer;
}

.bt-float-range::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 12px;
  height: 12px;
  background: linear-gradient(135deg, var(--bt-accent-blue) 0%, var(--bt-accent-teal) 100%);
  border-radius: 50%;
  cursor: pointer;
  transition: all var(--bt-transition-fast);
  box-shadow: 0 2px 8px var(--bt-accent-blue-glow);
}

.bt-float-range::-webkit-slider-thumb:hover {
  transform: scale(1.15);
  box-shadow: 0 4px 12px var(--bt-accent-blue-glow);
}

.bt-float-range::-moz-range-thumb {
  width: 12px;
  height: 12px;
  background: linear-gradient(135deg, var(--bt-accent-blue) 0%, var(--bt-accent-teal) 100%);
  border: none;
  border-radius: 50%;
  cursor: pointer;
}

.bt-float-speed-value {
  font-size: 11px;
  font-weight: 700;
  color: var(--bt-accent-teal);
  min-width: 24px;
  text-align: center;
  font-variant-numeric: tabular-nums;
}

/* Timeframe Dropdown */
.bt-float-timeframe {
  position: relative;
}

.bt-float-tf-btn {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 5px 10px;
  background: var(--bt-bg-surface);
  border: 1px solid var(--bt-border-default);
  border-radius: var(--bt-radius-sm);
  color: var(--bt-text-primary);
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
  transition: all var(--bt-transition-fast);
}

.bt-float-tf-btn:hover {
  background: var(--bt-bg-hover);
  border-color: var(--bt-border-strong);
}

.bt-float-tf-btn svg {
  opacity: 0.5;
  transition: transform var(--bt-transition-fast);
}

.bt-float-tf-btn:hover svg {
  transform: rotate(180deg);
}

.bt-float-tf-dropdown {
  position: absolute;
  top: calc(100% + 10px);
  left: 50%;
  transform: translateX(-50%);
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  min-width: 160px;
  padding: 10px;
  background: var(--bt-bg-elevated);
  border: 1px solid var(--bt-border-default);
  border-radius: var(--bt-radius-lg);
  box-shadow: var(--bt-shadow-lg);
  z-index: 101;
  animation: bt-slide-up 0.2s ease-out;
}

.bt-float-tf-option {
  padding: 10px 14px;
  background: transparent;
  border: 1px solid transparent;
  border-radius: var(--bt-radius-sm);
  color: var(--bt-text-secondary);
  font-size: 12px;
  font-weight: 600;
  text-align: center;
  cursor: pointer;
  transition: all var(--bt-transition-fast);
}

.bt-float-tf-option:hover {
  background: var(--bt-bg-hover);
  color: var(--bt-text-primary);
}

.bt-float-tf-option.active {
  background: var(--bt-accent-blue-glow);
  border-color: var(--bt-accent-blue);
  color: var(--bt-accent-blue);
}

.bt-float-tf-option.custom {
  grid-column: 1 / -1;
  color: var(--bt-accent-blue);
  border-color: var(--bt-border-subtle);
}

.bt-float-tf-option.custom:hover {
  border-color: var(--bt-accent-blue);
  background: var(--bt-accent-blue-glow);
}

.bt-float-tf-divider {
  grid-column: 1 / -1;
  height: 1px;
  background: var(--bt-border-subtle);
  margin: 4px 0;
}

.bt-float-tf-custom-input {
  grid-column: 1 / -1;
  display: flex;
  gap: 6px;
}

.bt-float-tf-custom-input input {
  flex: 1;
  min-width: 0;
  padding: 8px 12px;
  background: var(--bt-bg-base);
  border: 1px solid var(--bt-border-default);
  border-radius: var(--bt-radius-sm);
  color: var(--bt-text-primary);
  font-size: 12px;
  font-weight: 600;
}

.bt-float-tf-custom-input input:focus {
  outline: none;
  border-color: var(--bt-accent-blue);
}

.bt-float-tf-custom-input input::placeholder {
  color: var(--bt-text-muted);
}

.bt-float-tf-custom-input button {
  padding: 8px 14px;
  background: var(--bt-accent-blue);
  border: none;
  border-radius: var(--bt-radius-sm);
  color: white;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: background var(--bt-transition-fast);
}

.bt-float-tf-custom-input button:hover {
  background: #2563eb;
}

/* Trade Buttons */
.bt-float-group.trade-group {
  display: flex;
  gap: 8px;
}

.bt-float-trade-btn {
  padding: 5px 12px;
  border-radius: var(--bt-radius-sm);
  font-size: 11px;
  font-weight: 700;
  border: none;
  cursor: pointer;
  transition: all var(--bt-transition-fast);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.bt-float-trade-btn.buy {
  background: linear-gradient(135deg, var(--bt-profit) 0%, #059669 100%);
  color: white;
  box-shadow: 0 4px 12px var(--bt-profit-glow);
}

.bt-float-trade-btn.buy:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px var(--bt-profit-glow);
}

.bt-float-trade-btn.sell {
  background: linear-gradient(135deg, var(--bt-loss) 0%, #dc2626 100%);
  color: white;
  box-shadow: 0 4px 12px var(--bt-loss-glow);
}

.bt-float-trade-btn.sell:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px var(--bt-loss-glow);
}

.bt-float-trade-btn.place {
  background: linear-gradient(135deg, var(--bt-purple) 0%, #7c3aed 100%);
  color: white;
  box-shadow: 0 4px 12px var(--bt-purple-bg);
}

.bt-float-trade-btn.place:hover:not(:disabled) {
  transform: translateY(-2px);
}

.bt-float-trade-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  transform: none;
  box-shadow: none;
}

.bt-float-trade-btn:active:not(:disabled) {
  transform: translateY(0);
}

/* =====================================================
   LEGACY BOTTOM CONTROLS (Fallback)
   ===================================================== */
.bt-controls {
  display: flex;
  align-items: center;
  gap: 24px;
  height: 60px;
  padding: 0 20px;
  background: var(--bt-bg-elevated);
  border-top: 1px solid var(--bt-border-subtle);
  flex-shrink: 0;
}

.bt-playback {
  display: flex;
  align-items: center;
  gap: 6px;
}

.bt-ctrl-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  background: var(--bt-bg-surface);
  border: 1px solid var(--bt-border-default);
  border-radius: var(--bt-radius-md);
  color: var(--bt-text-primary);
  cursor: pointer;
  transition: all var(--bt-transition-fast);
}

.bt-ctrl-btn:hover:not(:disabled) {
  background: var(--bt-bg-hover);
  border-color: var(--bt-border-strong);
}

.bt-ctrl-btn:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}

.bt-ctrl-btn.play {
  width: 48px;
  background: var(--bt-accent-blue);
  border-color: var(--bt-accent-blue);
  color: white;
}

.bt-ctrl-btn.play:hover:not(:disabled) {
  background: var(--bt-accent-blue-hover);
}

.bt-ctrl-btn.reset {
  color: var(--bt-warning);
  border-color: var(--bt-warning-bg);
}

.bt-ctrl-btn.reset:hover {
  background: var(--bt-warning-bg);
}

.bt-speed {
  display: flex;
  align-items: center;
  gap: 10px;
}

.bt-speed-label {
  font-size: 11px;
  color: var(--bt-text-muted);
  font-weight: 500;
}

.bt-speed-options {
  display: flex;
  background: var(--bt-bg-surface);
  border-radius: var(--bt-radius-md);
  padding: 3px;
}

.bt-speed-btn {
  padding: 6px 10px;
  background: transparent;
  border: none;
  border-radius: var(--bt-radius-sm);
  color: var(--bt-text-muted);
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
  transition: all var(--bt-transition-fast);
}

.bt-speed-btn:hover {
  color: var(--bt-text-primary);
}

.bt-speed-btn.active {
  background: var(--bt-accent-blue);
  color: white;
}

.bt-progress {
  flex: 1;
  max-width: 320px;
}

.bt-progress-track {
  height: 6px;
  background: var(--bt-bg-surface);
  border-radius: 3px;
  overflow: hidden;
}

.bt-progress-bar {
  height: 100%;
  background: linear-gradient(90deg, var(--bt-accent-blue) 0%, var(--bt-accent-teal) 100%);
  border-radius: 3px;
  transition: width 0.1s ease-out;
}

.bt-trade-actions {
  display: flex;
  gap: 10px;
  margin-left: auto;
}

.bt-trade-btn {
  padding: 10px 24px;
  border: none;
  border-radius: var(--bt-radius-md);
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  transition: all var(--bt-transition-fast);
}

.bt-trade-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.bt-trade-btn.buy {
  background: var(--bt-profit);
  color: white;
}

.bt-trade-btn.buy:hover:not(:disabled) {
  background: #059669;
}

.bt-trade-btn.sell {
  background: var(--bt-loss);
  color: white;
}

.bt-trade-btn.sell:hover:not(:disabled) {
  background: #dc2626;
}

.bt-trade-btn.place-order {
  background: linear-gradient(135deg, var(--bt-accent-blue), var(--bt-purple));
  color: white;
}

.bt-trade-btn.place-order:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow: 0 4px 16px var(--bt-accent-blue-glow);
}

/* =====================================================
   PREMIUM SLIDE PANEL
   ===================================================== */
.bt-slide-panel {
  position: fixed;
  top: 0;
  right: 0;
  width: 320px;
  height: 100%;
  background: linear-gradient(180deg, rgba(20, 22, 28, 0.98) 0%, rgba(10, 12, 16, 0.99) 100%);
  border-left: 1px solid rgba(255, 255, 255, 0.04);
  transform: translateX(100%);
  transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
  z-index: 200;
  display: flex;
  flex-direction: column;
  box-shadow: -16px 0 48px rgba(0, 0, 0, 0.5);
  backdrop-filter: blur(24px);
}

.bt-slide-panel::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 3px;
  height: 100%;
  background: linear-gradient(180deg, var(--bt-accent-blue) 0%, var(--bt-accent-teal) 50%, var(--bt-purple) 100%);
}

.bt-slide-panel.open {
  transform: translateX(0);
}

.bt-panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 18px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.04);
  background: rgba(255, 255, 255, 0.02);
}

.bt-panel-header h3 {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 14px;
  font-weight: 600;
  color: var(--bt-text-primary);
  letter-spacing: -0.01em;
}

.bt-panel-header h3::before {
  content: '';
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--bt-accent-blue) 0%, var(--bt-accent-teal) 100%);
  box-shadow: 0 0 10px var(--bt-accent-blue);
}

.bt-panel-close {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 6px;
  color: var(--bt-text-muted);
  cursor: pointer;
  transition: all 0.15s ease;
}

.bt-panel-close:hover {
  background: rgba(255, 255, 255, 0.08);
  color: var(--bt-text-primary);
  transform: scale(1.05);
}

.bt-panel-content {
  flex: 1;
  overflow-y: auto;
  padding: 16px;
}

.bt-panel-content::-webkit-scrollbar {
  width: 4px;
}

.bt-panel-content::-webkit-scrollbar-track {
  background: transparent;
}

.bt-panel-content::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.08);
  border-radius: 2px;
}

/* Position Card */
.bt-position-card {
  position: relative;
  background: rgba(0, 0, 0, 0.25);
  border: 1px solid rgba(255, 255, 255, 0.04);
  border-radius: 14px;
  padding: 16px;
  transition: all 0.2s ease;
  overflow: hidden;
}

.bt-position-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg, var(--bt-accent-blue) 0%, var(--bt-accent-teal) 100%);
}

.bt-position-card:hover {
  border-color: rgba(255, 255, 255, 0.08);
  background: rgba(0, 0, 0, 0.3);
}

.bt-position-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 14px;
}

.bt-position-type {
  font-size: 10px;
  font-weight: 700;
  padding: 5px 10px;
  border-radius: 6px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.bt-position-type.long {
  background: rgba(34, 197, 94, 0.15);
  color: var(--bt-profit);
  border: 1px solid rgba(34, 197, 94, 0.3);
}

.bt-position-type.short {
  background: rgba(239, 68, 68, 0.15);
  color: var(--bt-loss);
  border: 1px solid rgba(239, 68, 68, 0.3);
}

.bt-position-pnl {
  font-size: 20px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.02em;
}

.bt-position-pnl.profit {
  color: var(--bt-profit);
  text-shadow: 0 0 20px rgba(34, 197, 94, 0.4);
}

.bt-position-pnl.loss {
  color: var(--bt-loss);
  text-shadow: 0 0 20px rgba(239, 68, 68, 0.3);
}

.bt-position-details {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-bottom: 16px;
}

.bt-detail {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 10px 12px;
  background: rgba(255, 255, 255, 0.02);
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.03);
}

.bt-detail-label {
  font-size: 9px;
  color: var(--bt-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-weight: 600;
}

.bt-detail-value {
  font-size: 13px;
  font-weight: 600;
  color: var(--bt-text-primary);
  font-variant-numeric: tabular-nums;
}

.bt-detail-value.profit {
  color: var(--bt-profit);
}

.bt-detail-value.loss {
  color: var(--bt-loss);
}

.bt-position-actions {
  display: flex;
  gap: 8px;
}

.bt-action-btn {
  flex: 1;
  padding: 10px;
  border-radius: 10px;
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s ease;
}

.bt-action-btn.close {
  background: rgba(239, 68, 68, 0.12);
  border: 1px solid rgba(239, 68, 68, 0.25);
  color: var(--bt-loss);
}

.bt-action-btn.close:hover {
  background: rgba(239, 68, 68, 0.2);
  border-color: rgba(239, 68, 68, 0.4);
  transform: translateY(-1px);
}

.bt-action-btn.modify {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.08);
  color: var(--bt-text-primary);
}

.bt-action-btn.modify:hover {
  background: rgba(255, 255, 255, 0.1);
  border-color: rgba(255, 255, 255, 0.12);
  transform: translateY(-1px);
}

/* Empty State */
.bt-empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 48px 20px;
  color: var(--bt-text-muted);
}

.bt-empty-state::before {
  content: '';
  width: 48px;
  height: 48px;
  margin-bottom: 16px;
  background: radial-gradient(circle, rgba(59, 130, 246, 0.15) 0%, transparent 70%);
  border-radius: 50%;
  border: 1px dashed rgba(255, 255, 255, 0.08);
}

.bt-empty-state p {
  margin-bottom: 8px;
  font-size: 13px;
  font-weight: 500;
}

.bt-hint {
  font-size: 11px;
  opacity: 0.5;
  background: rgba(255, 255, 255, 0.04);
  padding: 6px 12px;
  border-radius: 6px;
  border: 1px solid rgba(255, 255, 255, 0.04);
}

/* History Section */
.bt-history-section {
  margin-top: 20px;
}

.bt-history-section h4 {
  font-size: 10px;
  font-weight: 600;
  color: var(--bt-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 12px;
  padding-left: 2px;
}

.bt-history-item {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 12px;
  background: rgba(0, 0, 0, 0.2);
  border: 1px solid rgba(255, 255, 255, 0.03);
  border-radius: 10px;
  margin-bottom: 6px;
  transition: all 0.15s ease;
  overflow: hidden;
}

.bt-history-item::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 2px;
}

.bt-history-item:has(.bt-history-pnl.profit)::before {
  background: linear-gradient(180deg, var(--bt-profit) 0%, rgba(34, 197, 94, 0.2) 100%);
}

.bt-history-item:has(.bt-history-pnl.loss)::before {
  background: linear-gradient(180deg, var(--bt-loss) 0%, rgba(239, 68, 68, 0.2) 100%);
}

.bt-history-item:hover {
  border-color: rgba(255, 255, 255, 0.06);
  background: rgba(0, 0, 0, 0.3);
}

.bt-history-info {
  display: flex;
  align-items: center;
  gap: 8px;
}

.bt-history-type {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
}

.bt-history-type.long {
  color: var(--bt-profit);
}

.bt-history-type.short {
  color: var(--bt-loss);
}

.bt-history-reason {
  font-size: 10px;
  color: var(--bt-text-muted);
  opacity: 0.7;
}

.bt-history-pnl {
  font-size: 12px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.bt-history-pnl.profit {
  color: var(--bt-profit);
}

.bt-history-pnl.loss {
  color: var(--bt-loss);
}

/* =====================================================
   PREMIUM ORDER MODAL
   ===================================================== */
.bt-modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.8);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
  animation: bt-fade-in 0.2s ease-out;
}

.bt-modal {
  background: var(--bt-bg-elevated);
  border: 1px solid var(--bt-border-default);
  border-radius: var(--bt-radius-xl);
  padding: 24px;
  width: 100%;
  max-width: 360px;
  box-shadow: var(--bt-shadow-lg);
  animation: bt-slide-up 0.3s ease-out;
}

.bt-modal h3 {
  font-size: 18px;
  font-weight: 700;
  color: var(--bt-text-primary);
  margin-bottom: 20px;
  letter-spacing: -0.02em;
}

.bt-order-modal {
  position: relative;
  width: 480px;
  max-width: 95vw;
  max-height: 90vh;
  overflow-y: auto;
  background: linear-gradient(180deg, rgba(24, 27, 35, 0.98) 0%, rgba(12, 14, 18, 0.99) 100%);
  border-radius: 20px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  box-shadow: 
    0 0 0 1px rgba(255, 255, 255, 0.03),
    0 24px 80px rgba(0, 0, 0, 0.6),
    0 8px 32px rgba(0, 0, 0, 0.4),
    inset 0 1px 0 rgba(255, 255, 255, 0.04);
  animation: bt-slide-up 0.25s cubic-bezier(0.16, 1, 0.3, 1);
  backdrop-filter: blur(24px);
}

.bt-order-modal::-webkit-scrollbar {
  width: 6px;
}

.bt-order-modal::-webkit-scrollbar-track {
  background: transparent;
}

.bt-order-modal::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.1);
  border-radius: 3px;
}

.bt-order-modal::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.15);
}

.bt-order-modal::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, var(--bt-accent-blue) 0%, var(--bt-accent-teal) 50%, var(--bt-purple) 100%);
  border-radius: 20px 20px 0 0;
}

.bt-order-modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 18px 20px 14px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.04);
}

.bt-order-modal-header h3 {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 15px;
  font-weight: 600;
  color: var(--bt-text-primary);
  margin: 0;
  letter-spacing: -0.01em;
}

.bt-order-modal-header h3::before {
  content: '';
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--bt-accent-blue) 0%, var(--bt-accent-teal) 100%);
  box-shadow: 0 0 12px var(--bt-accent-blue);
}

.bt-modal-close {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 8px;
  color: var(--bt-text-muted);
  cursor: pointer;
  transition: all 0.15s ease;
}

.bt-modal-close:hover {
  background: rgba(255, 255, 255, 0.08);
  color: var(--bt-text-primary);
  transform: scale(1.05);
}

/* Balance Toggle - Segmented Control */
.bt-order-balance-toggle {
  display: flex;
  justify-content: center;
  padding: 16px 20px;
}

.bt-order-balance-toggle-inner {
  display: flex;
  background: rgba(0, 0, 0, 0.3);
  border-radius: 10px;
  padding: 3px;
  border: 1px solid rgba(255, 255, 255, 0.04);
}

.bt-radio-option {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px 16px;
  cursor: pointer;
  font-size: 12px;
  font-weight: 500;
  color: var(--bt-text-muted);
  transition: all 0.2s ease;
  border-radius: 8px;
  border: none;
  background: transparent;
}

.bt-radio-option input {
  display: none;
}

.bt-radio-dot {
  display: none;
}

.bt-radio-option.active {
  color: var(--bt-text-primary);
  background: rgba(255, 255, 255, 0.08);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.2);
}

.bt-radio-option:hover:not(.active) {
  color: var(--bt-text-secondary);
}

/* Estimates */
.bt-order-estimates {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  padding: 0 20px 16px;
}

.bt-estimate {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 14px 16px;
  background: rgba(0, 0, 0, 0.25);
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.04);
  overflow: hidden;
  transition: all 0.2s ease;
}

.bt-estimate::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 3px;
  height: 100%;
}

.bt-estimate.loss::before {
  background: linear-gradient(180deg, var(--bt-loss) 0%, rgba(239, 68, 68, 0.3) 100%);
}

.bt-estimate.profit::before {
  background: linear-gradient(180deg, var(--bt-profit) 0%, rgba(34, 197, 94, 0.3) 100%);
}

.bt-estimate:hover {
  background: rgba(0, 0, 0, 0.35);
  border-color: rgba(255, 255, 255, 0.06);
}

.bt-estimate-label {
  font-size: 10px;
  font-weight: 600;
  color: var(--bt-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.bt-estimate-value {
  font-size: 20px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.02em;
}

.bt-estimate.loss .bt-estimate-value {
  color: var(--bt-loss);
}

.bt-estimate.profit .bt-estimate-value {
  color: var(--bt-profit);
}

/* Order Sections */
.bt-order-section {
  padding: 0 20px 16px;
}

.bt-order-section-label {
  display: block;
  font-size: 10px;
  font-weight: 600;
  color: var(--bt-text-muted);
  margin-bottom: 10px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.bt-risk-presets {
  display: flex;
  gap: 6px;
}

.bt-risk-btn {
  flex: 1;
  padding: 8px 10px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 8px;
  color: var(--bt-text-muted);
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s ease;
}

.bt-risk-btn:hover {
  background: rgba(255, 255, 255, 0.06);
  border-color: rgba(255, 255, 255, 0.1);
  color: var(--bt-text-primary);
}

.bt-risk-btn.active {
  background: rgba(59, 130, 246, 0.15);
  border-color: var(--bt-accent-blue);
  color: var(--bt-accent-blue);
  box-shadow: 0 0 16px rgba(59, 130, 246, 0.2);
}

/* Order Row */
.bt-order-row {
  display: flex;
  gap: 10px;
  padding: 0 20px 12px;
}

.bt-order-field {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.bt-order-field label {
  font-size: 10px;
  font-weight: 600;
  color: var(--bt-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.bt-order-field input,
.bt-order-field select {
  padding: 10px 12px;
  background: rgba(0, 0, 0, 0.25);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 10px;
  color: var(--bt-text-primary);
  font-size: 13px;
  font-weight: 500;
  transition: all 0.15s ease;
}

.bt-order-field input:focus,
.bt-order-field select:focus {
  outline: none;
  border-color: rgba(59, 130, 246, 0.5);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.1);
  background: rgba(0, 0, 0, 0.35);
}

.bt-order-field input.bt-readonly,
.bt-order-field input:disabled {
  background: rgba(0, 0, 0, 0.15);
  color: var(--bt-text-disabled);
  cursor: not-allowed;
  border-color: rgba(255, 255, 255, 0.03);
}

/* Select Wrapper */
.bt-select-wrapper {
  position: relative;
}

.bt-select-wrapper select {
  width: 100%;
  appearance: none;
  padding-right: 32px;
  cursor: pointer;
}

.bt-select-arrow {
  position: absolute;
  right: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--bt-text-muted);
  pointer-events: none;
  opacity: 0.5;
}

/* Input with Icon */
.bt-input-with-icon {
  position: relative;
}

.bt-input-with-icon input {
  width: 100%;
  padding-left: 28px;
}

.bt-input-icon {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 12px;
  font-weight: 600;
  color: var(--bt-text-muted);
  opacity: 0.6;
}

.bt-input-with-suffix {
  position: relative;
}

.bt-input-with-suffix input {
  width: 100%;
  padding-right: 48px;
}

.bt-input-suffix {
  position: absolute;
  right: 12px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 10px;
  font-weight: 600;
  color: var(--bt-text-muted);
  opacity: 0.5;
}

/* Toggle */
.bt-order-toggle-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 20px 14px;
  font-size: 12px;
  font-weight: 500;
  color: var(--bt-text-secondary);
}

.bt-toggle {
  position: relative;
  display: inline-block;
  width: 36px;
  height: 20px;
}

.bt-toggle input {
  opacity: 0;
  width: 0;
  height: 0;
}

.bt-toggle-slider {
  position: absolute;
  cursor: pointer;
  inset: 0;
  background: rgba(255, 255, 255, 0.08);
  border-radius: 20px;
  transition: all 0.2s ease;
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.bt-toggle-slider::before {
  content: '';
  position: absolute;
  height: 14px;
  width: 14px;
  left: 2px;
  bottom: 2px;
  background: var(--bt-text-muted);
  border-radius: 50%;
  transition: all 0.2s cubic-bezier(0.68, -0.55, 0.265, 1.55);
}

.bt-toggle input:checked + .bt-toggle-slider {
  background: linear-gradient(135deg, var(--bt-accent-blue) 0%, var(--bt-accent-teal) 100%);
  border-color: transparent;
}

.bt-toggle input:checked + .bt-toggle-slider::before {
  transform: translateX(16px);
  background: white;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
}

/* SL/TP Section */
.bt-order-sl-tp-section {
  margin: 0 20px 12px;
  background: rgba(0, 0, 0, 0.2);
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.04);
  overflow: hidden;
}

.bt-sl-tp-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 14px;
  background: rgba(255, 255, 255, 0.02);
  font-size: 11px;
  font-weight: 600;
  color: var(--bt-text-secondary);
  border-bottom: 1px solid rgba(255, 255, 255, 0.03);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.bt-order-sl-tp-section .bt-order-row {
  padding: 12px 14px 14px;
}

/* Order Actions */
.bt-order-actions {
  display: flex;
  gap: 10px;
  padding: 16px 20px 20px;
  border-top: 1px solid rgba(255, 255, 255, 0.04);
  background: rgba(0, 0, 0, 0.15);
  border-radius: 0 0 20px 20px;
}

.bt-order-action-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 10px 14px;
  border-radius: 10px;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s ease;
}

.bt-order-action-btn.discard {
  background: transparent;
  border: 1px solid rgba(255, 255, 255, 0.08);
  color: var(--bt-text-muted);
}

.bt-order-action-btn.discard:hover {
  background: rgba(255, 255, 255, 0.04);
  color: var(--bt-text-primary);
  border-color: rgba(255, 255, 255, 0.12);
}

.bt-order-action-btn.save {
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.08);
  color: var(--bt-text-primary);
}

.bt-order-action-btn.save:hover {
  background: rgba(255, 255, 255, 0.1);
  border-color: rgba(255, 255, 255, 0.12);
}

.bt-order-action-btn.save-journal {
  flex: 1;
  background: linear-gradient(135deg, var(--bt-accent-blue) 0%, var(--bt-accent-teal) 100%);
  border: none;
  color: white;
  box-shadow: 0 4px 20px rgba(59, 130, 246, 0.25);
}

.bt-order-action-btn.save-journal:hover {
  transform: translateY(-1px);
  box-shadow: 0 8px 32px rgba(59, 130, 246, 0.35);
  filter: brightness(1.1);
}

/* =====================================================
   STATUS BAR
   ===================================================== */
.bt-status-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 48px;
  padding: 0 16px;
  background: var(--bt-bg-elevated);
  border-top: 1px solid var(--bt-border-subtle);
}

.bt-status-left {
  display: flex;
  align-items: center;
  gap: 14px;
}

.bt-status-drag {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 6px;
  color: var(--bt-text-disabled);
  cursor: grab;
  transition: color var(--bt-transition-fast);
}

.bt-status-drag:hover {
  color: var(--bt-text-muted);
}

.bt-status-analytics {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  background: var(--bt-bg-surface);
  border: 1px solid var(--bt-border-default);
  border-radius: var(--bt-radius-md);
  color: var(--bt-text-secondary);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--bt-transition-fast);
}

.bt-status-analytics:hover {
  background: var(--bt-bg-hover);
  border-color: var(--bt-border-strong);
  color: var(--bt-text-primary);
}

.bt-status-center {
  display: flex;
  align-items: center;
  gap: 28px;
}

.bt-status-item {
  display: flex;
  align-items: center;
  gap: 8px;
}

.bt-status-label {
  color: var(--bt-text-muted);
  font-size: 13px;
  font-weight: 400;
}

.bt-status-value {
  color: var(--bt-text-primary);
  font-size: 13px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.bt-status-value.profit {
  color: var(--bt-profit);
}

.bt-status-value.loss {
  color: var(--bt-loss);
}

.bt-status-right {
  display: flex;
  align-items: center;
  gap: 6px;
}

.bt-status-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  background: transparent;
  border: none;
  border-radius: var(--bt-radius-sm);
  color: var(--bt-text-muted);
  cursor: pointer;
  transition: all var(--bt-transition-fast);
}

.bt-status-icon:hover {
  background: var(--bt-bg-hover);
  color: var(--bt-text-primary);
}

/* =====================================================
   INPUT GROUPS
   ===================================================== */
.bt-input-group {
  margin-bottom: 14px;
}

.bt-input-group label {
  display: block;
  font-size: 12px;
  font-weight: 600;
  color: var(--bt-text-muted);
  margin-bottom: 8px;
}

.bt-input-group input {
  width: 100%;
  padding: 12px 14px;
  background: var(--bt-bg-surface);
  border: 1px solid var(--bt-border-default);
  border-radius: var(--bt-radius-md);
  color: var(--bt-text-primary);
  font-size: 14px;
  transition: all var(--bt-transition-fast);
}

.bt-input-group input:focus {
  outline: none;
  border-color: var(--bt-accent-blue);
  box-shadow: 0 0 0 3px var(--bt-accent-blue-glow);
}

.bt-modal-actions {
  display: flex;
  gap: 10px;
  margin-top: 20px;
}

.bt-modal-btn {
  flex: 1;
  padding: 12px;
  border-radius: var(--bt-radius-md);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: all var(--bt-transition-fast);
  border: none;
}

.bt-modal-btn.cancel {
  background: var(--bt-bg-surface);
  border: 1px solid var(--bt-border-default);
  color: var(--bt-text-secondary);
}

.bt-modal-btn.cancel:hover {
  background: var(--bt-bg-hover);
  color: var(--bt-text-primary);
}

.bt-modal-btn.save {
  background: var(--bt-accent-blue);
  color: white;
}

.bt-modal-btn.save:hover {
  background: var(--bt-accent-blue-hover);
}

.bt-modal-btn.full-width {
  width: 100%;
  margin-top: 14px;
}

/* Order Type Badges */
.bt-order-info {
  margin-bottom: 18px;
}

.bt-order-type-badge {
  margin-bottom: 14px;
}

.bt-order-type-badge span {
  display: inline-block;
  padding: 8px 14px;
  border-radius: var(--bt-radius-md);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.bt-order-type-badge span.long {
  background: var(--bt-profit-bg);
  color: var(--bt-profit);
  border: 1px solid var(--bt-profit-border);
}

.bt-order-type-badge span.short {
  background: var(--bt-loss-bg);
  color: var(--bt-loss);
  border: 1px solid var(--bt-loss-border);
}

.bt-order-details {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 14px;
  background: var(--bt-bg-surface);
  border-radius: var(--bt-radius-md);
  border: 1px solid var(--bt-border-subtle);
}

.bt-order-details .bt-detail {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.bt-order-details .bt-detail-label {
  font-size: 12px;
  color: var(--bt-text-muted);
}

.bt-order-details .bt-detail-value {
  font-size: 14px;
  font-weight: 600;
  color: var(--bt-text-primary);
  font-variant-numeric: tabular-nums;
}

/* Order Buttons */
.bt-order-buttons {
  display: flex;
  gap: 12px;
  margin-bottom: 14px;
}

.bt-order-btn {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 18px 14px;
  border-radius: var(--bt-radius-lg);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: all var(--bt-transition-fast);
  border: 1px solid var(--bt-border-default);
  background: var(--bt-bg-surface);
  color: var(--bt-text-primary);
}

.bt-order-btn:hover {
  border-color: var(--bt-accent-blue);
  background: var(--bt-accent-blue-glow);
}

.bt-order-btn.market {
  background: linear-gradient(135deg, var(--bt-profit-bg), transparent);
  border-color: var(--bt-profit-border);
}

.bt-order-btn.market:hover {
  background: linear-gradient(135deg, rgba(16, 185, 129, 0.2), var(--bt-profit-bg));
  border-color: var(--bt-profit);
}

.bt-order-btn.limit {
  background: linear-gradient(135deg, var(--bt-purple-bg), transparent);
  border-color: var(--bt-purple-border);
}

.bt-order-btn.limit:hover {
  background: linear-gradient(135deg, rgba(139, 92, 246, 0.2), var(--bt-purple-bg));
  border-color: var(--bt-purple);
}

.bt-order-btn svg {
  opacity: 0.9;
}

/* =====================================================
   RESPONSIVE ADJUSTMENTS
   ===================================================== */
@media (max-width: 768px) {
  .bt-header {
    padding: 0 12px;
  }

  .bt-header-center {
    display: none;
  }

  .bt-floating-bar {
    padding: 8px 12px;
    gap: 0;
  }

  .bt-float-divider {
    margin: 0 8px;
  }

  .bt-float-group.speed-group {
    display: none;
  }

  .bt-slide-panel {
    width: 100%;
  }

  .bt-order-modal {
    width: 100%;
    max-width: 100%;
    border-radius: var(--bt-radius-lg) var(--bt-radius-lg) 0 0;
    max-height: 85vh;
  }
}

/* =====================================================
   SKELETON LOADING STATES
   ===================================================== */
.bt-skeleton {
  background: linear-gradient(
    90deg,
    var(--bt-bg-surface) 25%,
    var(--bt-bg-hover) 50%,
    var(--bt-bg-surface) 75%
  );
  background-size: 200% 100%;
  animation: bt-shimmer 1.5s infinite;
  border-radius: var(--bt-radius-sm);
}

.bt-skeleton-text {
  height: 14px;
  width: 100%;
  margin-bottom: 8px;
}

.bt-skeleton-text.short {
  width: 60%;
}

.bt-skeleton-box {
  height: 48px;
  width: 100%;
}

/* =====================================================
   BOTTOM DRAWER PANEL
   ===================================================== */
.bt-bottom-drawer {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: linear-gradient(180deg, rgba(16, 18, 24, 0.98) 0%, rgba(8, 10, 14, 0.99) 100%);
  border-top: 1px solid rgba(255, 255, 255, 0.06);
  z-index: 150;
  display: flex;
  flex-direction: column;
  backdrop-filter: blur(24px);
  -webkit-backdrop-filter: blur(24px);
  box-shadow: 0 -8px 32px rgba(0, 0, 0, 0.4);
  transition: height 0.05s ease-out;
}

.bt-bottom-drawer::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg, var(--bt-accent-blue) 0%, var(--bt-accent-teal) 50%, var(--bt-purple) 100%);
}

.bt-drawer-resize-handle {
  position: absolute;
  top: -8px;
  left: 0;
  right: 0;
  height: 16px;
  cursor: ns-resize;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 100;
  touch-action: none;
}

.bt-drawer-resize-handle::after {
  content: '';
  width: 48px;
  height: 4px;
  background: rgba(255, 255, 255, 0.2);
  border-radius: 4px;
  transition: all 0.15s ease;
  pointer-events: none;
}

.bt-drawer-resize-handle:hover::after {
  background: rgba(255, 255, 255, 0.4);
  width: 64px;
}

.bt-drawer-resize-handle:active::after,
.bt-bottom-drawer.resizing .bt-drawer-resize-handle::after {
  background: var(--bt-accent-blue);
  width: 80px;
}

.bt-bottom-drawer.resizing {
  transition: none;
}

.bt-bottom-drawer.collapsed {
  transition: height 0.2s ease;
}

.bt-bottom-drawer.collapsed .bt-drawer-content {
  display: none;
}

.bt-bottom-drawer.collapsed .bt-drawer-header {
  border-bottom: none;
}

.bt-drawer-toggle-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border: none;
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.06);
  color: var(--bt-text-muted);
  cursor: pointer;
  transition: all 0.15s ease;
}

.bt-drawer-toggle-btn:hover {
  background: rgba(255, 255, 255, 0.1);
  color: var(--bt-text-primary);
}

.bt-drawer-toggle-btn:active {
  background: rgba(255, 255, 255, 0.08);
  transform: scale(0.95);
}

.bt-drawer-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 20px 10px 20px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.04);
  background: rgba(255, 255, 255, 0.01);
  flex-shrink: 0;
}

.bt-drawer-tabs {
  display: flex;
  align-items: center;
  gap: 4px;
}

.bt-drawer-tab {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 14px;
  font-size: 12px;
  font-weight: 500;
  color: var(--bt-text-muted);
  background: transparent;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.15s ease;
}

.bt-drawer-tab:hover {
  color: var(--bt-text-secondary);
  background: rgba(255, 255, 255, 0.04);
}

.bt-drawer-tab.active {
  color: var(--bt-text-primary);
  background: rgba(255, 255, 255, 0.08);
}

.bt-drawer-tab-count {
  font-size: 10px;
  font-weight: 600;
  padding: 2px 6px;
  background: rgba(255, 255, 255, 0.08);
  border-radius: 10px;
  min-width: 18px;
  text-align: center;
}

.bt-drawer-tab.active .bt-drawer-tab-count {
  background: var(--bt-accent-blue);
  color: white;
}

.bt-drawer-stats {
  display: flex;
  align-items: center;
  gap: 24px;
}

.bt-drawer-stat {
  display: flex;
  align-items: center;
  gap: 8px;
}

.bt-drawer-stat-label {
